def require_google_login():
    """
    Streamlit Google OIDC login gate.
    Uses single-provider [auth] setup from .streamlit/secrets.toml.
    """
    if not st.user.is_logged_in:
        st.title("23 Saeulen Analyse")
        st.info("Bitte mit Google anmelden, um die App zu nutzen.")
        st.button("Mit Google anmelden", on_click=st.login, type="primary", key="google_login_main")
        st.stop()


def require_allowed_email():
    """
    Restrict app access to configured email addresses in Streamlit secrets.

    Expected secrets format:
    [access]
    allowed_emails = ["user@example.com", "other@example.com"]
    """
    try:
        allowed_emails = {
            str(mail).strip().lower()
            for mail in st.secrets.get("access", {}).get("allowed_emails", [])
            if str(mail).strip()
        }
    except Exception:
        allowed_emails = set()

    # If no whitelist is configured, allow all authenticated users.
    if not allowed_emails:
        return

    user_email = str(st.user.get("email", "")).strip().lower()

    if user_email not in allowed_emails:
        st.error(f"Dieses Konto ist nicht freigeschaltet: {user_email or 'unbekannt'}")
        st.write("Bitte mit einem freigegebenen Google-Konto anmelden.")
        st.button("Abmelden", on_click=st.logout, key="google_logout_denied")
        st.stop()


def render_user_bar():
    try:
        c1, c2 = st.columns([8, 1])
        with c1:
            user_name = getattr(st.user, "name", None) or st.user.get("email", "angemeldet")
            user_email = st.user.get("email", "")
            if user_email:
                st.caption(f"Angemeldet als: {user_name} ({user_email})")
            else:
                st.caption(f"Angemeldet als: {user_name}")
        with c2:
            st.button("Abmelden", on_click=st.logout, key="google_logout_main")
    except Exception:
        pass


def infer_ultra_bias_from_signal(ultra_signal):
    try:
        label = str((ultra_signal or {}).get("label", "")).strip().lower()
        reason = str((ultra_signal or {}).get("reason", "")).strip().lower()
        bullets = " - ".join([str(x).lower() for x in ((ultra_signal or {}).get("bullets", []) or [])])
        confirmation = str((ultra_signal or {}).get("confirmation", "")).strip().lower()
        strength = float((ultra_signal or {}).get("strength", 0) or 0)
    except Exception:
        return ("Neutral", "⚪")

    context = " ".join([label, reason, bullets])

    if "bullish" in label:
        return ("Bestaetigt bullish" if ("vorhand" in confirmation or strength >= 60) else "Leicht bullish", "🟢" if ("vorhand" in confirmation or strength >= 60) else "🟠")
    if "bearish" in label:
        return ("Bestaetigt bearish" if ("vorhand" in confirmation or strength >= 60) else "Leicht bearish", "🔴" if ("vorhand" in confirmation or strength >= 60) else "🟠")

    if "zone unter beobachtung" in label:
        if "support" in context or "unterer docht" in context:
            return ("Leicht bullish", "🟠")
        if "widerstand" in context or "oberer docht" in context or "rejection" in context:
            return ("Leicht bearish", "🟠")
        return ("Neutral", "⚪")

    if "kein signal" in label:
        return ("Neutral", "⚪")

    return ("Neutral", "⚪")

def _ultra_bias_from_signal(signal_label, confirmation_text=None, strength_value=None):
    lbl = str(signal_label or "").strip().lower()
    conf = str(confirmation_text or "").strip().lower()
    try:
        strength = float(strength_value) if strength_value is not None else None
    except Exception:
        strength = None

    if "bull" in lbl:
        return "Bestaetigt bullish" if ("vorhand" in conf or (strength is not None and strength >= 60)) else "Leicht bullish"
    if "bear" in lbl:
        return "Bestaetigt bearish" if ("vorhand" in conf or (strength is not None and strength >= 60)) else "Leicht bearish"
    if "beob" in lbl:
        # infer tilt from zone wording if possible
        if "support" in lbl:
            return "Leicht bullish"
        if "widerstand" in lbl:
            return "Leicht bearish"
        return "Neutral"
    return "Neutral"

def _ultra_bias_badge(bias_label):
    b = str(bias_label or "").strip().lower()
    if "bestaetigt bullish" in b:
        return "🟢"
    if "leicht bullish" in b:
        return "🟠"
    if "neutral" in b:
        return "⚪"
    if "leicht bearish" in b:
        return "🟠"
    if "bestaetigt bearish" in b:
        return "🔴"
    return "⚪"

def _ultra_short_term_signal_badge(signal_label):
    label = str(signal_label or "").strip().lower()
    if "bull" in label:
        return "🟢"
    if "bear" in label:
        return "🔴"
    if "beob" in label:
        return "🟠"
    return "⚪"

def _ultra_short_term_signal_bg(signal_label):
    label = str(signal_label or "").strip().lower()
    if "bull" in label:
        return "background-color:#d9fbe6;color:#0f5132;border-radius:10px;padding:10px 12px;font-weight:700;"
    if "bear" in label:
        return "background-color:#ffe0e0;color:#8a1c1c;border-radius:10px;padding:10px 12px;font-weight:700;"
    if "beob" in label:
        return "background-color:#fff2d6;color:#8a5a00;border-radius:10px;padding:10px 12px;font-weight:700;"
    return "background-color:#eef1f4;color:#4b5563;border-radius:10px;padding:10px 12px;font-weight:700;"

