def shorten_text(value, max_len=42):
    if value is None:
        return "-"
    txt = str(value).strip()
    if not txt:
        return "-"
    if len(txt) <= max_len:
        return txt
    clipped = txt[: max_len - 3]
    if " " in clipped:
        clipped = clipped.rsplit(" ", 1)[0]
    clipped = clipped.rstrip(" ,;:-")
    return clipped + "..."


