def compute_signal_conflict_phase_ui(
    investment_case="-",
    timing_label="-",
    risk_label="-",
    action_label="-",
    candle_daily=None,
    candle_hourly=None,
    ultra_label="-",
    tactical_label="-",
):
    reasons = []
    score = 0

    inv = str(investment_case or "").lower()
    timing = str(timing_label or "").lower()
    risk = str(risk_label or "").lower()
    action = str(action_label or "").lower()
    ultra = str(ultra_label or "").lower()
    tactical = str(tactical_label or "").lower()

    daily_tone = str((candle_daily or {}).get("tone", "neutral")).lower() if isinstance(candle_daily, dict) else "neutral"
    hourly_tone = str((candle_hourly or {}).get("tone", "neutral")).lower() if isinstance(candle_hourly, dict) else "neutral"

    # Core tension: strong case, weak timing
    if inv in {"attraktiv", "solide"} and timing in {"noch nicht reif", "unattraktiv"}:
        score += 1
        reasons.append("Grundcase besser als Timing")

    # Strong timing but elevated risk
    if timing in {"reif", "fast reif"} and risk in {"erhöht", "kritisch"}:
        score += 2
        reasons.append("Timing kollidiert mit Risiko")

    # Bullish candles but defensive action
    if (daily_tone == "bullish" or hourly_tone == "bullish") and action in {"abwarten", "stop enger", "teilgewinn prüfen", "exit prüfen"}:
        score += 1
        reasons.append("Bullische Reaktion, aber defensive Aktion")

    # Bearish candles but constructive action
    if (daily_tone == "bearish" or hourly_tone == "bearish") and action in {"kaufen", "vorbereiten"}:
        score += 2
        reasons.append("Bearische Reaktion, aber konstruktive Aktion")

    # Ultra-short-term vs timing mismatch
    if ultra in {"aktives signal", "frühe reaktion"} and timing in {"noch nicht reif", "unattraktiv"}:
        score += 1
        reasons.append("Kurzfristig besser als mittelfristiges Timing")

    # Tactical pressure vs stable risk mismatch
    if tactical in {"erhöht", "kritisch"} and risk == "stabil":
        score += 1
        reasons.append("Taktik warnt stärker als die Haupt-Risikolage")

    # Constructive action but clearly defensive tactical state
    if action in {"kaufen", "vorbereiten"} and tactical == "kritisch":
        score += 2
        reasons.append("Konstruktive Aktion trotz kritischer Taktik")

    if score <= 1:
        label = "konsistent"
        tone = "bull" if action in {"kaufen", "vorbereiten", "halten"} and risk != "kritisch" else "neutral"
        summary = "Die wichtigsten Signale ziehen weitgehend in dieselbe Richtung."
    elif score <= 3:
        label = "gemischt"
        tone = "warn"
        summary = "Es gibt erkennbare Spannungen zwischen Setup, Timing und Risiko."
    else:
        label = "widersprüchlich"
        tone = "bear"
        summary = "Mehrere Signalebenen sprechen aktuell nicht sauber dieselbe Sprache."

    top_reason = reasons[0] if reasons else "Keine dominanten Konflikte erkannt."
    return {
        "label": label,
        "tone": tone,
        "summary": summary,
        "reason": top_reason,
        "score": score,
        "reasons": reasons[:4],
    }





def compute_chart_period_performance(chart_df):
    try:
        if chart_df is None or len(chart_df) < 2:
            return None, None
        close_col = None
        for candidate in ["Close", "close", "Adj Close", "adj_close"]:
            if candidate in chart_df.columns:
                close_col = candidate
                break
        if close_col is None:
            return None, None
        start_val = float(chart_df[close_col].iloc[0])
        end_val = float(chart_df[close_col].iloc[-1])
        if start_val <= 0:
            return None, None
        perf_pct = ((end_val / start_val) - 1.0) * 100.0
        perf_abs = end_val - start_val
        return perf_pct, perf_abs
    except Exception:
        return None, None


def render_chart_period_performance_block(chart_period_label, perf_pct, perf_abs=None):
    try:
        perf_num = float(perf_pct) if perf_pct is not None and str(perf_pct) not in {"", "-", "None"} else None
    except Exception:
        perf_num = None

    if perf_num is None:
        perf_text = "-"
        perf_label = "Keine Performance verfügbar"
    else:
        perf_text = f"{perf_num:.1f}%"
        if perf_num > 0:
            perf_label = "Positiv im gewählten Zeitraum"
        elif perf_num < 0:
            perf_label = "Negativ im gewählten Zeitraum"
        else:
            perf_label = "Unverändert im gewählten Zeitraum"

    abs_line = ""
    if perf_abs is not None and str(perf_abs) not in {"", "-", "None"}:
        try:
            abs_line = f" · Absolut: {float(perf_abs):.2f}"
        except Exception:
            abs_line = f" · Absolut: {perf_abs}"

    st.markdown(
        f"""
        <div class="section-card">
            <div class="premium-title">Zeitraum-Performance</div>
            <div class="premium-value">Start bis aktuell: {perf_text}</div>
            <div class="premium-sub">Bezieht sich auf den aktuell ausgewählten Chart-Zeitraum ({chart_period_label}).{abs_line}</div>
            <div class="premium-sub" style="margin-top:6px;">{perf_label}</div>
        </div>
        """,
        unsafe_allow_html=True,
    )











def _v1533_1_fmt_price(value, suffix=""):
    try:
        if value is None:
            return "n/a"
        v = float(value)
        if not np.isfinite(v):
            return "n/a"
        return f"{v:.2f}{suffix}"
    except Exception:
        return "n/a"


def _v1533_1_fmt_pct(value):
    try:
        if value is None:
            return "n/a"
        v = float(value)
        if not np.isfinite(v):
            return "n/a"
        return f"{v:.1f}%"
    except Exception:
        return "n/a"


def _v1533_1_support_zone_text(result=None, fallback=None):
    """Best-effort Support-/Invalidierungszone fuer erklaerende Chartkontexte."""
    result = result or {}
    candidates = []
    for key in ["stop_used", "stop", "technical_stop", "support_s1", "s1", "nearest_support"]:
        try:
            val = result.get(key)
        except Exception:
            val = None
        if val not in (None, "", "-", "n/a"):
            candidates.append(val)
    if fallback not in (None, "", "-", "n/a"):
        candidates.append(fallback)
    for val in candidates:
        txt = _v1533_1_fmt_price(val)
        if txt != "n/a":
            return txt
    return "n/a"



def build_setup_pattern_context_v162(chart_df=None, result=None):
    """Weicher Chart-Setup-Kontext fuer High Tight Pivot, Power Play und High Tight Flag.

    Bewusst nicht score-wirksam: Diese Muster sind selten und koennen bei zu
    harter Automatisierung Scheinsicherheit erzeugen. Die Funktion erkennt nur,
    ob eine Struktur in diese Richtung geht und ob ein Trigger bereits sichtbar
    ist.
    """
    result = result or {}
    out = {
        "label": "kein klares Spezialmuster",
        "phase": "Nicht aktiv",
        "pattern_type": "keines",
        "summary": "Kein belastbarer High-Tight-/Power-Play-Kontext erkennbar.",
        "action_hint": "Nicht aus diesem Baustein handeln; normale Entry-, S/R- und Bestätigungssignale nutzen.",
        "active_zone_text": "n/a",
        "trigger_label": "kein Trigger",
        "trigger_score": 0,
        "trigger_text": "Kein aktiver Spezialmuster-Trigger.",
        "trigger_action": "Nur beobachten; andere Analysebausteine bleiben führend.",
        "confirmation_needed": "Kein Spezialmuster aktiv; normale Entry-, S/R- und Konfluenzsignale bleiben wichtiger.",
        "drivers": [],
        "rows": [],
        "is_score_relevant": False,
    }
    try:
        dfp = chart_df.copy() if chart_df is not None else None
        if dfp is None or dfp.empty:
            return out
        close_col = "Close" if "Close" in dfp.columns else "Adj Close" if "Adj Close" in dfp.columns else None
        if close_col is None:
            return out
        high_col = "High" if "High" in dfp.columns else close_col
        low_col = "Low" if "Low" in dfp.columns else close_col
        vol_col = "Volume" if "Volume" in dfp.columns else None
        close = pd.to_numeric(dfp[close_col], errors="coerce").dropna()
        high = pd.to_numeric(dfp[high_col], errors="coerce").dropna()
        low = pd.to_numeric(dfp[low_col], errors="coerce").dropna()
        if len(close) < 45 or len(high) < 45 or len(low) < 45:
            return out
        price = float(close.iloc[-1])
        ma10 = float(close.rolling(10).mean().iloc[-1]) if len(close) >= 10 else np.nan
        ma20 = float(close.rolling(20).mean().iloc[-1]) if len(close) >= 20 else np.nan
        ma50 = float(close.rolling(50).mean().iloc[-1]) if len(close) >= 50 else np.nan
        high10 = float(high.tail(10).max())
        low10 = float(low.tail(10).min())
        high20 = float(high.tail(20).max())
        low20 = float(low.tail(20).min())
        high40 = float(high.tail(40).max())
        low40 = float(low.tail(40).min())
        high60 = float(high.tail(min(60, len(high))).max())
        low60 = float(low.tail(min(60, len(low))).min())
        prev_high10 = float(high.iloc[:-1].tail(10).max()) if len(high) > 11 else high10
        prev_high20 = float(high.iloc[:-1].tail(20).max()) if len(high) > 21 else high20
        run20 = ((price / float(close.iloc[-21])) - 1) * 100 if len(close) > 21 and float(close.iloc[-21]) else np.nan
        run40 = ((price / float(close.iloc[-41])) - 1) * 100 if len(close) > 41 and float(close.iloc[-41]) else np.nan
        run60 = ((price / float(close.iloc[-61])) - 1) * 100 if len(close) > 61 and float(close.iloc[-61]) else np.nan
        move_from_60_low = ((high60 / low60) - 1) * 100 if low60 else np.nan
        pullback20 = ((high20 - price) / high20) * 100 if high20 else np.nan
        pullback60 = ((high60 - price) / high60) * 100 if high60 else np.nan
        tight10 = ((high10 - low10) / max(price, 1e-9)) * 100
        tight20 = ((high20 - low20) / max(price, 1e-9)) * 100
        dist_ma10 = ((price / ma10) - 1) * 100 if pd.notna(ma10) and ma10 else np.nan
        dist_ma20 = ((price / ma20) - 1) * 100 if pd.notna(ma20) and ma20 else np.nan
        dist_ma50 = ((price / ma50) - 1) * 100 if pd.notna(ma50) and ma50 else np.nan
        vol_ratio = np.nan
        if vol_col and vol_col in dfp.columns:
            vol = pd.to_numeric(dfp[vol_col], errors="coerce").dropna()
            if len(vol) >= 20 and float(vol.tail(20).mean() or 0) > 0:
                vol_ratio = float(vol.iloc[-1] / vol.tail(20).mean())

        drivers = []
        def add_driver(txt):
            if txt and txt not in drivers:
                drivers.append(txt)

        # Candidate pattern conditions, deliberately soft.
        near_high = pd.notna(pullback20) and pullback20 <= 6
        above_short = (pd.notna(ma10) and price >= ma10 * 0.985) and (pd.notna(ma20) and price >= ma20 * 0.97)
        above_ma50 = pd.notna(ma50) and price >= ma50
        strong_60_move = pd.notna(move_from_60_low) and move_from_60_low >= 45
        extreme_60_move = pd.notna(move_from_60_low) and move_from_60_low >= 90
        tight_recent = tight10 <= 7 or tight20 <= 12
        flag_depth_ok = pd.notna(pullback60) and 5 <= pullback60 <= 28
        pivot_zone = prev_high10 if prev_high10 and np.isfinite(prev_high10) else prev_high20
        pivot_dist = ((pivot_zone - price) / max(price, 1e-9)) * 100 if pivot_zone else np.nan
        breakout = bool(pivot_zone and price >= pivot_zone * 1.002)
        near_pivot = bool(pivot_zone and abs(pivot_dist) <= 2.0)
        vol_conf = pd.notna(vol_ratio) and vol_ratio >= 1.15

        scores = {"High Tight Pivot": 0, "Power Play": 0, "High Tight Flag": 0}
        # High Tight Pivot: tight action near highs, close around/above short pivot.
        if near_high: scores["High Tight Pivot"] += 20; add_driver(f"nahe 20T-Hoch ({pullback20:.1f}% darunter)")
        if tight_recent: scores["High Tight Pivot"] += 24; add_driver(f"enge kurzfristige Range ({tight10:.1f}% / 10T)")
        if above_short: scores["High Tight Pivot"] += 18; add_driver("Kurs hält MA10/MA20")
        if near_pivot or breakout: scores["High Tight Pivot"] += 24; add_driver(f"Pivotbereich um {_v1533_1_fmt_price(pivot_zone)}")
        if vol_conf: scores["High Tight Pivot"] += 10; add_driver(f"Volumen über Schnitt ({vol_ratio:.2f}x)")

        # Power Play: strong fast move, high/tight hold, little pullback.
        if pd.notna(run20) and run20 >= 20: scores["Power Play"] += 22; add_driver(f"starker 20T-Lauf ({run20:.1f}%)")
        if pd.notna(run40) and run40 >= 35: scores["Power Play"] += 22; add_driver(f"starker 40T-Lauf ({run40:.1f}%)")
        if near_high: scores["Power Play"] += 18
        if above_short and above_ma50: scores["Power Play"] += 18
        if tight20 <= 16: scores["Power Play"] += 12
        if vol_conf: scores["Power Play"] += 8

        # High Tight Flag: large move from recent low, then shallow/tight flag near top.
        if extreme_60_move: scores["High Tight Flag"] += 34; add_driver(f"sehr starker Move vom 60T-Tief ({move_from_60_low:.1f}%)")
        elif strong_60_move: scores["High Tight Flag"] += 20; add_driver(f"starker Move vom 60T-Tief ({move_from_60_low:.1f}%)")
        if flag_depth_ok: scores["High Tight Flag"] += 24; add_driver(f"Flag-/Konsolidierungstiefe {pullback60:.1f}%")
        if tight_recent: scores["High Tight Flag"] += 18
        if above_ma50: scores["High Tight Flag"] += 10
        if near_pivot or breakout: scores["High Tight Flag"] += 10
        if vol_conf: scores["High Tight Flag"] += 4

        best_type = max(scores, key=scores.get)
        best_score = int(round(min(max(scores[best_type], 0), 100)))
        if best_score < 45:
            label = "kein klares Spezialmuster"
            phase = "Nicht aktiv"
            pattern_type = "keines"
            summary = "Kein belastbarer High-Tight-/Power-Play-Kontext. Normale Chart- und Entry-Logik bleibt führend."
            action = "Nicht aus diesem Baustein handeln; S/R, Entry-Zone, Candlestick und Konfluenz prüfen."
        elif best_type == "High Tight Pivot":
            label = "möglicher High Tight Pivot"
            phase = "Enger Pivot nahe Hoch"
            pattern_type = best_type
            summary = "Kurs handelt eng nahe dem Hoch. Das kann ein kurzer Pivot sein, braucht aber einen klaren Ausbruch oder eine bestätigte Reaktion."
            action = f"Aktiv prüfen erst bei Ausbruch/Stabilisierung über dem Pivotbereich um {_v1533_1_fmt_price(pivot_zone)}; defensiver, wenn MA10/MA20 brechen."
        elif best_type == "Power Play":
            label = "mögliches Power Play"
            phase = "Starker kurzer Impuls"
            pattern_type = best_type
            summary = "Sehr dynamischer kurzfristiger Move. Stärke ist vorhanden, aber FOMO-/Überdehnungsrisiko beachten."
            action = f"Nicht hinterherlaufen. Einstieg nur bei enger Konsolidierung, Reclaim oder Pullback in Richtung MA10/MA20 ({_v1533_1_fmt_price(ma10)} / {_v1533_1_fmt_price(ma20)})."
        else:
            label = "mögliche High Tight Flag"
            phase = "Starker Move mit enger Flagge"
            pattern_type = best_type
            summary = "Nach starkem Anstieg hält der Kurs relativ eng im oberen Bereich. Das kann konstruktiv sein, ist aber selten und braucht Ausbruchsbestätigung."
            action = f"Trigger wäre ein sauberer Ausbruch über den Flag-/Pivotbereich um {_v1533_1_fmt_price(pivot_zone)} mit Bestätigung; Bruch unter MA20/Flag-Tief macht es defensiver."

        # Trigger state.
        trigger_score = 0
        tdrivers = []
        if breakout:
            trigger_score += 35; tdrivers.append(f"Kurs über Pivot {_v1533_1_fmt_price(pivot_zone)}")
        elif near_pivot:
            trigger_score += 18; tdrivers.append(f"Kurs nahe Pivot {_v1533_1_fmt_price(pivot_zone)}")
        if above_short:
            trigger_score += 18; tdrivers.append("MA10/MA20 halten")
        if tight_recent:
            trigger_score += 14; tdrivers.append("kurzfristig enge Struktur")
        if vol_conf:
            trigger_score += 18; tdrivers.append(f"Volumenbestätigung {vol_ratio:.2f}x")
        if near_high:
            trigger_score += 10; tdrivers.append("nahe Hochbereich")
        trigger_score = int(round(min(trigger_score, 100))) if best_score >= 45 else 0
        if best_score < 45:
            trig_label = "kein Trigger"
            trig_text = "Kein aktiver Spezialmuster-Trigger."
            trig_action = "Normale Analysebausteine verwenden."
        elif trigger_score >= 72:
            trig_label = "bestätigt"
            trig_text = "Spezialmuster-Trigger wirkt bestätigt: Pivot/Struktur, kurzfristiger Trend und Bestätigung ziehen zusammen."
            trig_action = "Nur im Zusammenspiel mit Aktion, Risiko, Entry-Zone und Konfluenz als aktiven Trigger werten."
        elif trigger_score >= 52:
            trig_label = "erste Bestätigung"
            trig_text = "Erste Bestätigung sichtbar, aber noch nicht vollständig."
            trig_action = "Vorbereiten/aktiv prüfen; auf Schlusskurs, Volumen und Folgetag achten."
        elif trigger_score >= 30:
            trig_label = "unter Beobachtung"
            trig_text = "Struktur ist interessant, aber Trigger ist noch unvollständig."
            trig_action = "Watchlist/Alarm am Pivotbereich setzen; nicht blind handeln."
        else:
            trig_label = "noch nicht erreicht"
            trig_text = "Musterkontext möglich, aber der operative Trigger fehlt."
            trig_action = "Auf Pivot-Ausbruch, Reclaim oder enge Konsolidierung warten."

        if best_type == "High Tight Pivot":
            confirmation_needed = (
                f"Passt wahrscheinlicher, wenn der Kurs den Pivotbereich um {_v1533_1_fmt_price(pivot_zone)} "
                "zurückerobert oder darüber schließt, die Kerzen eng bleiben und MA10/MA20 halten. "
                "Idealer Zusatz: Volumen zieht beim Ausbruch an. Schwächer wird es bei Bruch von MA10/MA20."
            )
        elif best_type == "Power Play":
            confirmation_needed = (
                f"Passt wahrscheinlicher, wenn der starke Lauf nicht sofort abverkauft wird, der Kurs eng oberhalb/nahe MA10/MA20 "
                f"({_v1533_1_fmt_price(ma10)} / {_v1533_1_fmt_price(ma20)}) konsolidiert und anschließend mit Volumen wieder nach oben dreht. "
                "Kein Hinterherlaufen bei weiterem Abstand ohne Konsolidierung."
            )
        elif best_type == "High Tight Flag":
            confirmation_needed = (
                f"Passt wahrscheinlicher, wenn die Flagge eng bleibt, MA10/MA20 halten und der Kurs den Flag-/Pivotbereich um "
                f"{_v1533_1_fmt_price(pivot_zone)} mit Schlusskurs und idealerweise Volumenbestätigung überschreitet. "
                "Schwächer wird es bei Bruch der Flagge oder MA20."
            )
        else:
            confirmation_needed = "Kein Spezialmuster aktiv; normale Entry-, S/R- und Konfluenzsignale bleiben wichtiger."

        rows = [
            {"Muster": "High Tight Pivot", "Score": int(round(min(scores["High Tight Pivot"],100))), "Lesart": "Enger Pivot nahe Hoch.", "Damit es passt": f"Ausbruch/Stabilisierung über Pivot um {_v1533_1_fmt_price(pivot_zone)}, MA10/MA20 halten, ideal mit Volumen."},
            {"Muster": "Power Play", "Score": int(round(min(scores["Power Play"],100))), "Lesart": "Starker kurzer Impuls.", "Damit es passt": f"Enge Konsolidierung statt Abverkauf; Reclaim/Halten von MA10/MA20 ({_v1533_1_fmt_price(ma10)} / {_v1533_1_fmt_price(ma20)}) und neue Stärke."},
            {"Muster": "High Tight Flag", "Score": int(round(min(scores["High Tight Flag"],100))), "Lesart": "Starker Move plus enge Flagge.", "Damit es passt": f"Flagge bleibt eng; Ausbruch über Pivot/Flagge um {_v1533_1_fmt_price(pivot_zone)} mit Schlusskurs/Volumen."},
        ]
        out.update({
            "label": label,
            "phase": phase,
            "pattern_type": pattern_type,
            "summary": summary,
            "action_hint": action,
            "active_zone_text": f"Pivot/Triggerbereich um {_v1533_1_fmt_price(pivot_zone)}" if pivot_zone else "n/a",
            "trigger_label": trig_label,
            "trigger_score": trigger_score,
            "trigger_text": trig_text,
            "trigger_action": trig_action,
            "confirmation_needed": confirmation_needed,
            "drivers": (tdrivers + drivers)[:8],
            "rows": rows,
            "metrics": {
                "Kurs": round(price, 2),
                "Pivotbereich": round(float(pivot_zone), 2) if pivot_zone and np.isfinite(pivot_zone) else "n/a",
                "Pullback_20T_Hoch_%": round(float(pullback20), 1) if pd.notna(pullback20) else "n/a",
                "Range_10T_%": round(float(tight10), 1) if pd.notna(tight10) else "n/a",
                "Move_60T_Tief_%": round(float(move_from_60_low), 1) if pd.notna(move_from_60_low) else "n/a",
                "Volumen_Ratio": round(float(vol_ratio), 2) if pd.notna(vol_ratio) else "n/a",
            },
        })
        return out
    except Exception as exc:
        out["summary"] = f"Setup-Muster-Kontext nicht belastbar: {exc}"
        return out


# v17.3: erweiterter Spezialmuster-Kontext. Diese spaetere Definition ueberschreibt bewusst
# die fruehere v16.2-Variante und ergaenzt Pocket Pivot, VCP, MA-Pullback,
# Undercut & Rally sowie Failed-Breakout/Exhaustion-Warnungen.
def build_setup_pattern_context_v162(chart_df=None, result=None):
    result = result or {}
    out = {
        "label": "kein klares Spezialmuster",
        "phase": "Nicht aktiv",
        "pattern_type": "keines",
        "summary": "Kein belastbarer Spezialmuster-Kontext erkennbar.",
        "action_hint": "Nicht aus diesem Baustein handeln; normale Entry-, S/R- und Bestaetigungssignale nutzen.",
        "active_zone_text": "n/a",
        "trigger_label": "kein Trigger",
        "trigger_score": 0,
        "trigger_text": "Kein aktiver Spezialmuster-Trigger.",
        "trigger_action": "Nur beobachten; andere Analysebausteine bleiben fuehrend.",
        "confirmation_needed": "Kein Spezialmuster aktiv; normale Entry-, S/R- und Konfluenzsignale bleiben wichtiger.",
        "drivers": [],
        "rows": [],
        "is_score_relevant": False,
    }
    try:
        dfp = chart_df.copy() if chart_df is not None else None
        if dfp is None or dfp.empty:
            return out
        close_col = "Close" if "Close" in dfp.columns else "Adj Close" if "Adj Close" in dfp.columns else None
        if close_col is None:
            return out
        high_col = "High" if "High" in dfp.columns else close_col
        low_col = "Low" if "Low" in dfp.columns else close_col
        open_col = "Open" if "Open" in dfp.columns else close_col
        vol_col = "Volume" if "Volume" in dfp.columns else None
        close = pd.to_numeric(dfp[close_col], errors="coerce")
        high = pd.to_numeric(dfp[high_col], errors="coerce")
        low = pd.to_numeric(dfp[low_col], errors="coerce")
        opn = pd.to_numeric(dfp[open_col], errors="coerce")
        work = pd.DataFrame({"close": close, "high": high, "low": low, "open": opn}).dropna()
        if len(work) < 45:
            return out
        price = float(work["close"].iloc[-1])
        prev_close = float(work["close"].iloc[-2]) if len(work) >= 2 else price
        day_high = float(work["high"].iloc[-1]); day_low = float(work["low"].iloc[-1]); day_open = float(work["open"].iloc[-1])
        day_range = max(day_high - day_low, 1e-9)
        close_pos = (price - day_low) / day_range
        body_pct = abs(price - day_open) / max(price, 1e-9) * 100
        lower_wick_pct = (min(price, day_open) - day_low) / max(price, 1e-9) * 100
        upper_wick_pct = (day_high - max(price, day_open)) / max(price, 1e-9) * 100
        ma10 = float(work["close"].rolling(10).mean().iloc[-1]) if len(work) >= 10 else np.nan
        ma20 = float(work["close"].rolling(20).mean().iloc[-1]) if len(work) >= 20 else np.nan
        ma50 = float(work["close"].rolling(50).mean().iloc[-1]) if len(work) >= 50 else np.nan
        high10 = float(work["high"].tail(10).max()); low10 = float(work["low"].tail(10).min())
        high20 = float(work["high"].tail(20).max()); low20 = float(work["low"].tail(20).min())
        high40 = float(work["high"].tail(40).max()); low40 = float(work["low"].tail(40).min())
        high60 = float(work["high"].tail(min(60, len(work))).max()); low60 = float(work["low"].tail(min(60, len(work))).min())
        prev_high10 = float(work["high"].iloc[:-1].tail(10).max()) if len(work) > 11 else high10
        prev_high20 = float(work["high"].iloc[:-1].tail(20).max()) if len(work) > 21 else high20
        prev_low20 = float(work["low"].iloc[:-1].tail(20).min()) if len(work) > 21 else low20
        run20 = ((price / float(work["close"].iloc[-21])) - 1) * 100 if len(work) > 21 and float(work["close"].iloc[-21]) else np.nan
        run40 = ((price / float(work["close"].iloc[-41])) - 1) * 100 if len(work) > 41 and float(work["close"].iloc[-41]) else np.nan
        move_from_60_low = ((high60 / low60) - 1) * 100 if low60 else np.nan
        pullback20 = ((high20 - price) / high20) * 100 if high20 else np.nan
        pullback60 = ((high60 - price) / high60) * 100 if high60 else np.nan
        tight10 = ((high10 - low10) / max(price, 1e-9)) * 100
        tight20 = ((high20 - low20) / max(price, 1e-9)) * 100
        tight40 = ((high40 - low40) / max(price, 1e-9)) * 100
        dist_ma10 = ((price / ma10) - 1) * 100 if pd.notna(ma10) and ma10 else np.nan
        dist_ma20 = ((price / ma20) - 1) * 100 if pd.notna(ma20) and ma20 else np.nan
        dist_ma50 = ((price / ma50) - 1) * 100 if pd.notna(ma50) and ma50 else np.nan
        vol_ratio = np.nan
        if vol_col and vol_col in dfp.columns:
            vol = pd.to_numeric(dfp[vol_col], errors="coerce").dropna()
            if len(vol) >= 20 and float(vol.tail(20).mean() or 0) > 0:
                vol_ratio = float(vol.iloc[-1] / vol.tail(20).mean())
        drivers=[]
        def add_driver(txt):
            if txt and txt not in drivers:
                drivers.append(txt)
        near_high = pd.notna(pullback20) and pullback20 <= 6
        above_short = (pd.notna(ma10) and price >= ma10 * 0.985) and (pd.notna(ma20) and price >= ma20 * 0.97)
        above_ma50 = pd.notna(ma50) and price >= ma50
        strong_60_move = pd.notna(move_from_60_low) and move_from_60_low >= 45
        extreme_60_move = pd.notna(move_from_60_low) and move_from_60_low >= 90
        tight_recent = tight10 <= 7 or tight20 <= 12
        flag_depth_ok = pd.notna(pullback60) and 5 <= pullback60 <= 28
        pivot_zone = prev_high10 if prev_high10 and np.isfinite(prev_high10) else prev_high20
        pivot_dist = ((pivot_zone - price) / max(price, 1e-9)) * 100 if pivot_zone else np.nan
        breakout = bool(pivot_zone and price >= pivot_zone * 1.002)
        near_pivot = bool(pivot_zone and abs(pivot_dist) <= 2.0)
        vol_conf = pd.notna(vol_ratio) and vol_ratio >= 1.15
        bull_day = price > prev_close and close_pos >= 0.60
        strong_close = close_pos >= 0.72
        scores = {
            "High Tight Pivot": 0, "Power Play": 0, "High Tight Flag": 0,
            "Pocket Pivot": 0, "VCP / Volatility Contraction": 0,
            "MA10/20 Pullback-Reaktion": 0, "Undercut & Rally / Support-Reclaim": 0,
            "Flat Base / Base Breakout": 0, "Tight Range Breakout": 0,
            "Accumulation Cluster": 0, "Pullback Dry-Up": 0,
            "RS-New-High / Leadership-Reclaim": 0, "Double Bottom / Higher Low": 0,
            "Failed Breakout / Exhaustion-Warnung": 0, "Wide & Loose / Climax-Warnung": 0,
        }
        # Bestehende seltene Muster.
        if near_high: scores["High Tight Pivot"] += 20; add_driver(f"nahe 20T-Hoch ({pullback20:.1f}% darunter)")
        if tight_recent: scores["High Tight Pivot"] += 24; add_driver(f"enge kurzfristige Range ({tight10:.1f}% / 10T)")
        if above_short: scores["High Tight Pivot"] += 18; add_driver("Kurs haelt MA10/MA20")
        if near_pivot or breakout: scores["High Tight Pivot"] += 24; add_driver(f"Pivotbereich um {_v1533_1_fmt_price(pivot_zone)}")
        if vol_conf: scores["High Tight Pivot"] += 10; add_driver(f"Volumen ueber Schnitt ({vol_ratio:.2f}x)")
        if pd.notna(run20) and run20 >= 20: scores["Power Play"] += 22; add_driver(f"starker 20T-Lauf ({run20:.1f}%)")
        if pd.notna(run40) and run40 >= 35: scores["Power Play"] += 22; add_driver(f"starker 40T-Lauf ({run40:.1f}%)")
        if near_high: scores["Power Play"] += 18
        if above_short and above_ma50: scores["Power Play"] += 18
        if tight20 <= 16: scores["Power Play"] += 12
        if vol_conf: scores["Power Play"] += 8
        if extreme_60_move: scores["High Tight Flag"] += 34; add_driver(f"sehr starker Move vom 60T-Tief ({move_from_60_low:.1f}%)")
        elif strong_60_move: scores["High Tight Flag"] += 20; add_driver(f"starker Move vom 60T-Tief ({move_from_60_low:.1f}%)")
        if flag_depth_ok: scores["High Tight Flag"] += 24; add_driver(f"Flag-/Konsolidierungstiefe {pullback60:.1f}%")
        if tight_recent: scores["High Tight Flag"] += 18
        if above_ma50: scores["High Tight Flag"] += 10
        if near_pivot or breakout: scores["High Tight Flag"] += 10
        if vol_conf: scores["High Tight Flag"] += 4
        # Neue, praxisnaehere Signale.
        if vol_conf and bull_day: scores["Pocket Pivot"] += 32; add_driver(f"bullischer Volumentag ({vol_ratio:.2f}x)")
        if above_short: scores["Pocket Pivot"] += 18
        if near_pivot or breakout: scores["Pocket Pivot"] += 22
        if strong_close: scores["Pocket Pivot"] += 12
        if tight_recent: scores["Pocket Pivot"] += 8
        contraction_ratio = tight10 / max(tight40, 1e-9) if tight40 and np.isfinite(tight40) else np.nan
        if pd.notna(contraction_ratio) and contraction_ratio <= 0.58: scores["VCP / Volatility Contraction"] += 34; add_driver(f"Volatilitaet zieht zusammen ({tight10:.1f}% vs. {tight40:.1f}%)")
        if tight_recent: scores["VCP / Volatility Contraction"] += 18
        if near_high: scores["VCP / Volatility Contraction"] += 16
        if above_short: scores["VCP / Volatility Contraction"] += 12
        if near_pivot: scores["VCP / Volatility Contraction"] += 12
        near_ma10 = pd.notna(dist_ma10) and abs(dist_ma10) <= 2.2
        near_ma20 = pd.notna(dist_ma20) and abs(dist_ma20) <= 3.0
        reclaim_ma10 = pd.notna(ma10) and price >= ma10 and day_low <= ma10 * 1.01
        reclaim_ma20 = pd.notna(ma20) and price >= ma20 and day_low <= ma20 * 1.015
        if near_ma10 or near_ma20: scores["MA10/20 Pullback-Reaktion"] += 24; add_driver(f"nahe MA10/MA20 ({_v1533_1_fmt_price(ma10)} / {_v1533_1_fmt_price(ma20)})")
        if reclaim_ma10 or reclaim_ma20: scores["MA10/20 Pullback-Reaktion"] += 24
        if bull_day: scores["MA10/20 Pullback-Reaktion"] += 18
        if lower_wick_pct >= 0.8 and strong_close: scores["MA10/20 Pullback-Reaktion"] += 18
        if vol_conf: scores["MA10/20 Pullback-Reaktion"] += 8
        undercut = day_low < prev_low20 * 0.995 if prev_low20 else False
        reclaim_support = price > prev_low20 * 1.003 if prev_low20 else False
        if undercut and reclaim_support: scores["Undercut & Rally / Support-Reclaim"] += 42; add_driver(f"Undercut/Reclaim um {_v1533_1_fmt_price(prev_low20)}")
        if bull_day: scores["Undercut & Rally / Support-Reclaim"] += 18
        if lower_wick_pct >= 1.0: scores["Undercut & Rally / Support-Reclaim"] += 18
        if vol_conf: scores["Undercut & Rally / Support-Reclaim"] += 10
        failed_breakout = price < pivot_zone * 0.99 and high10 >= pivot_zone * 1.002 if pivot_zone else False
        exhaustion = pd.notna(dist_ma10) and dist_ma10 >= 9 and upper_wick_pct >= 1.0 and close_pos <= 0.55
        # Weitere relevante, weiche Chartmuster. Diese Signale sollen keine eigenen Kaufsignale sein,
        # sondern die Triggernaehe/Qualitaet der Struktur fuer Konfluenz und Radar besser einordnen.
        flat_base = (tight40 <= 18 and tight20 <= 11 and abs(pullback60) <= 20) if pd.notna(pullback60) else False
        if flat_base: scores["Flat Base / Base Breakout"] += 34; add_driver(f"flache Base/Range ({tight40:.1f}% / 40T)")
        if above_ma50: scores["Flat Base / Base Breakout"] += 14
        if near_high: scores["Flat Base / Base Breakout"] += 14
        if near_pivot or breakout: scores["Flat Base / Base Breakout"] += 20
        if vol_conf: scores["Flat Base / Base Breakout"] += 8

        tight3 = ((float(work["high"].tail(3).max()) - float(work["low"].tail(3).min())) / max(price, 1e-9)) * 100 if len(work) >= 3 else np.nan
        tight5 = ((float(work["high"].tail(5).max()) - float(work["low"].tail(5).min())) / max(price, 1e-9)) * 100 if len(work) >= 5 else np.nan
        if pd.notna(tight5) and tight5 <= 4.5: scores["Tight Range Breakout"] += 28; add_driver(f"sehr enge 5T-Range ({tight5:.1f}%)")
        if pd.notna(tight3) and tight3 <= 3.0: scores["Tight Range Breakout"] += 16
        if near_pivot or breakout: scores["Tight Range Breakout"] += 24
        if above_short: scores["Tight Range Breakout"] += 12
        if vol_conf and breakout: scores["Tight Range Breakout"] += 12

        # Akkumulation/Distribution als Kontext, falls bereits berechnet.
        acc_score = _turnaround_v174_float(result.get("accumulation_score"), 0)
        dist_score = _turnaround_v174_float(result.get("distribution_pressure_score", result.get("distribution_score")), 0)
        acc_days = _turnaround_v174_float(result.get("accumulation_day_count"), 0)
        dist_days = _turnaround_v174_float(result.get("distribution_day_count"), 0)
        pullback_dry = _turnaround_v174_float(result.get("pullback_dryup_score"), 0)
        breakout_vol_score = _turnaround_v174_float(result.get("breakout_volume_score"), 0)
        if acc_score >= 60 or (acc_days and acc_days >= 2): scores["Accumulation Cluster"] += 32; add_driver(f"Akkumulation sichtbar ({acc_score:.0f})")
        if dist_score <= 45: scores["Accumulation Cluster"] += 12
        if vol_conf and bull_day: scores["Accumulation Cluster"] += 22
        if breakout_vol_score >= 55: scores["Accumulation Cluster"] += 16

        pullback_context = (pd.notna(pullback20) and 2 <= pullback20 <= 12) or near_ma10 or near_ma20
        if pullback_context and pullback_dry >= 55: scores["Pullback Dry-Up"] += 36; add_driver(f"Pullback-Volumen trocknet aus ({pullback_dry:.0f})")
        if pullback_context: scores["Pullback Dry-Up"] += 16
        if above_short: scores["Pullback Dry-Up"] += 12
        if bull_day or lower_wick_pct >= 0.8: scores["Pullback Dry-Up"] += 14

        leadership_score = _turnaround_v174_float(result.get("leadership_score"), 0)
        rs_acc = _turnaround_v174_float(result.get("rs_acceleration_score"), 0)
        rs_bench = _turnaround_v174_float(result.get("rs_benchmark_score"), 0)
        if leadership_score >= 65 or rs_bench >= 65: scores["RS-New-High / Leadership-Reclaim"] += 28; add_driver(f"Relative Staerke/Leadership konstruktiv ({max(leadership_score, rs_bench):.0f})")
        if rs_acc >= 55: scores["RS-New-High / Leadership-Reclaim"] += 18
        if near_high and above_short: scores["RS-New-High / Leadership-Reclaim"] += 16
        if breakout or near_pivot: scores["RS-New-High / Leadership-Reclaim"] += 12

        # Doppelboden/Higher-Low-Reversal als weicher Turnaround-/Reclaim-Hinweis.
        recent_lows = work["low"].tail(30)
        dbl_score = 0
        if len(recent_lows) >= 18:
            first_low = float(recent_lows.iloc[:15].min())
            second_low = float(recent_lows.iloc[15:].min())
            low_gap = abs(second_low - first_low) / max(first_low, 1e-9) * 100
            higher_low = second_low > first_low * 1.01
            if low_gap <= 4.0 or higher_low:
                dbl_score += 30; add_driver(f"zweites Tief/Higher Low nahe {_v1533_1_fmt_price(second_low)}")
            if price > float(work["close"].tail(10).mean()): dbl_score += 12
            if bull_day or reclaim_ma10 or reclaim_ma20: dbl_score += 18
            if vol_conf: dbl_score += 10
        scores["Double Bottom / Higher Low"] += dbl_score

        failed_breakout = price < pivot_zone * 0.99 and high10 >= pivot_zone * 1.002 if pivot_zone else False
        exhaustion = pd.notna(dist_ma10) and dist_ma10 >= 9 and upper_wick_pct >= 1.0 and close_pos <= 0.55
        if failed_breakout: scores["Failed Breakout / Exhaustion-Warnung"] += 45; add_driver(f"Rueckfall unter Pivot {_v1533_1_fmt_price(pivot_zone)}")
        if exhaustion: scores["Failed Breakout / Exhaustion-Warnung"] += 35; add_driver(f"deutlich ueber MA10 ({dist_ma10:.1f}%) mit schwachem Close")
        if pd.notna(vol_ratio) and vol_ratio >= 1.4 and close_pos <= 0.45: scores["Failed Breakout / Exhaustion-Warnung"] += 20

        wide_loose = (tight20 >= 22 and pd.notna(pullback20) and pullback20 >= 8) or (body_pct >= 4.0 and close_pos <= 0.45)
        climax = (pd.notna(run20) and run20 >= 35 and pd.notna(dist_ma10) and dist_ma10 >= 10)
        if wide_loose: scores["Wide & Loose / Climax-Warnung"] += 32; add_driver(f"weite/unruhige Struktur ({tight20:.1f}% / 20T)")
        if climax: scores["Wide & Loose / Climax-Warnung"] += 32; add_driver(f"Climax-/Stretch-Risiko ({run20:.1f}% / 20T, {dist_ma10:.1f}% ueber MA10)")
        if pd.notna(vol_ratio) and vol_ratio >= 1.4 and close_pos <= 0.5: scores["Wide & Loose / Climax-Warnung"] += 16

        best_type = max(scores, key=scores.get)
        best_score = int(round(min(max(scores[best_type],0),100)))
        warning = best_type in {"Failed Breakout / Exhaustion-Warnung", "Wide & Loose / Climax-Warnung"} and best_score >= 45
        if best_score < 45:
            label="kein klares Spezialmuster"; phase="Nicht aktiv"; pattern_type="keines"
            summary="Kein belastbarer Spezialmuster-Kontext. Normale Chart- und Entry-Logik bleibt fuehrend."
            action="Nicht aus diesem Baustein handeln; S/R, Entry-Zone, Candlestick und Konfluenz pruefen."
        elif warning:
            label="Chart-Warnsignal: Failed Breakout / Wide & Loose"; phase="Defensiver Spezialkontext"; pattern_type=best_type
            summary="Der Chart zeigt eher ein Warnsignal: Ausbruch, Stretch oder weite Schwankungen wirken anfaellig."
            action=f"Nicht prozyklisch hinterherlaufen. Defensiver bei Rueckfall unter Pivot/Support um {_v1533_1_fmt_price(pivot_zone)}; neue enge Base abwarten."
        elif best_type == "Pocket Pivot":
            label="moeglicher Pocket Pivot"; phase="Volumenimpuls nahe Trigger"; pattern_type=best_type
            summary="Ein bullischer Volumentag nahe Pivot/MA-Struktur kann fruehe institutionelle Nachfrage anzeigen."
            action=f"Aktiv pruefen, wenn der Kurs den Pivotbereich um {_v1533_1_fmt_price(pivot_zone)} haelt/ueberschreitet und Volumen bestaetigt."
        elif best_type == "VCP / Volatility Contraction":
            label="moegliches VCP"; phase="Volatilitaet zieht zusammen"; pattern_type=best_type
            summary="Die Schwankungen werden enger. Das kann auf abnehmendes Angebot vor einem Ausbruch hinweisen."
            action=f"Alarm am Pivotbereich um {_v1533_1_fmt_price(pivot_zone)} setzen. Aktiv erst bei Ausbruch mit Volumen/Schlusskurs."
        elif best_type == "MA10/20 Pullback-Reaktion":
            label="MA10/20-Pullback-Reaktion"; phase="Pullback-Reaktion"; pattern_type=best_type
            summary="Der Kurs reagiert an MA10/MA20. Das kann ein frueher Entry-Hinweis sein, wenn die Reaktion haelt."
            action=f"Einstieg nur pruefen, wenn MA10/MA20 ({_v1533_1_fmt_price(ma10)} / {_v1533_1_fmt_price(ma20)}) halten und die Kerze/Volumen bestaetigen."
        elif best_type == "Undercut & Rally / Support-Reclaim":
            label="moeglicher Undercut & Rally / Support-Reclaim"; phase="Reclaim nach kurzem Bruch"; pattern_type=best_type
            summary="Ein Tief/Support wurde kurz verletzt und zurueckerobert. Das kann ein Reversal-Trigger sein."
            action=f"Aktiv pruefen, wenn der Reclaim ueber {_v1533_1_fmt_price(prev_low20)} haelt und Folgestaerke entsteht."
        elif best_type == "Flat Base / Base Breakout":
            label="moegliche Flat Base / Base-Breakout"; phase="enge Base nahe Trigger"; pattern_type=best_type
            summary="Der Kurs konsolidiert relativ flach. Das ist konstruktiv, wenn die obere Range mit Volumen gebrochen wird."
            action=f"Alarm am Base-/Pivotbereich um {_v1533_1_fmt_price(pivot_zone)} setzen; aktiv erst bei Schlusskurs/Volumen ueber der Range."
        elif best_type == "Tight Range Breakout":
            label="moeglicher Tight-Range-Breakout"; phase="Spannung baut sich auf"; pattern_type=best_type
            summary="Die kurzfristige Range ist sehr eng. Ein Ausbruch kann relevant werden, wenn Volumen und Schlusskurs bestaetigen."
            action=f"Nicht vorwegnehmen. Aktiv pruefen bei Ausbruch ueber {_v1533_1_fmt_price(pivot_zone)} mit enger Invalidierung."
        elif best_type == "Accumulation Cluster":
            label="Akkumulationscluster sichtbar"; phase="Smart-Money-Bestaetigung"; pattern_type=best_type
            summary="Mehrere Volumen-/Akkumulationshinweise sprechen dafuer, dass Kaufinteresse vorhanden ist."
            action="Als Qualitaetsbestaetigung werten; Einstieg trotzdem nur ueber Entry-Zone, Pivot oder Konfluenz aktivieren."
        elif best_type == "Pullback Dry-Up":
            label="Pullback-Dry-Up"; phase="Verkaufsdruck trocknet aus"; pattern_type=best_type
            summary="Der Ruecksetzer wirkt kontrolliert, weil das Volumen im Pullback nachlaesst."
            action=f"Bullischer wird es bei Reaktion an MA10/MA20 ({_v1533_1_fmt_price(ma10)} / {_v1533_1_fmt_price(ma20)}) oder Reclaim der Entry-Zone."
        elif best_type == "RS-New-High / Leadership-Reclaim":
            label="Leadership-/Relative-Staerke-Reclaim"; phase="relative Staerke verbessert sich"; pattern_type=best_type
            summary="Relative Staerke/Leadership zieht an. Das stuetzt Leader-Setups, ist aber allein kein Entry-Trigger."
            action="Als Bestaetigung werten; aktiv wird es erst mit Pivot, Entry-Zone oder klarer Kursreaktion."
        elif best_type == "Double Bottom / Higher Low":
            label="moeglicher Double-Bottom / Higher-Low-Reversal"; phase="fruehe Bodenbildung"; pattern_type=best_type
            summary="Der Kurs zeigt eine moegliche zweite Tief-/Higher-Low-Struktur. Das kann ein frueher Turnaround-Hinweis sein."
            action=f"Aktiv pruefen erst bei Bruch ueber das Zwischenhoch/Pivot um {_v1533_1_fmt_price(pivot_zone)} oder Reclaim wichtiger MAs."
        elif best_type == "High Tight Pivot":
            label="moeglicher High Tight Pivot"; phase="Enger Pivot nahe Hoch"; pattern_type=best_type
            summary="Kurs handelt eng nahe dem Hoch. Das kann ein kurzer Pivot sein, braucht aber Ausbruch/Bestaetigung."
            action=f"Aktiv pruefen erst bei Ausbruch/Stabilisierung ueber dem Pivotbereich um {_v1533_1_fmt_price(pivot_zone)}; defensiver, wenn MA10/MA20 brechen."
        elif best_type == "Power Play":
            label="moegliches Power Play"; phase="Starker kurzer Impuls"; pattern_type=best_type
            summary="Sehr dynamischer kurzfristiger Move. Staerke ist vorhanden, aber FOMO-/Ueberdehnungsrisiko beachten."
            action=f"Nicht hinterherlaufen. Einstieg nur bei enger Konsolidierung, Reclaim oder Pullback Richtung MA10/MA20 ({_v1533_1_fmt_price(ma10)} / {_v1533_1_fmt_price(ma20)})."
        else:
            label="moegliche High Tight Flag"; phase="Starker Move mit enger Flagge"; pattern_type=best_type
            summary="Nach starkem Anstieg haelt der Kurs relativ eng im oberen Bereich. Das braucht Ausbruchsbestaetigung."
            action=f"Trigger waere ein sauberer Ausbruch ueber den Flag-/Pivotbereich um {_v1533_1_fmt_price(pivot_zone)} mit Bestaetigung."
        trigger_score = 0; tdrivers=[]
        if warning:
            trigger_score = best_score
            trig_label = "Warnung aktiv" if best_score >= 60 else "Warnung im Aufbau"
            trig_text = "Warnsignal aus Failed-Breakout, Wide-&-Loose oder Climax-Kontext."
            trig_action = "Defensiver handeln; keinen aggressiven Long-Trigger daraus ableiten."
        else:
            if breakout: trigger_score += 35; tdrivers.append(f"Kurs ueber Pivot {_v1533_1_fmt_price(pivot_zone)}")
            elif near_pivot: trigger_score += 18; tdrivers.append(f"Kurs nahe Pivot {_v1533_1_fmt_price(pivot_zone)}")
            if above_short: trigger_score += 18; tdrivers.append("MA10/MA20 halten")
            if tight_recent: trigger_score += 14; tdrivers.append("kurzfristig enge Struktur")
            if vol_conf: trigger_score += 18; tdrivers.append(f"Volumenbestaetigung {vol_ratio:.2f}x")
            if bull_day: trigger_score += 10; tdrivers.append("bullische Tagesreaktion")
            trigger_score = int(round(min(trigger_score,100))) if best_score >= 45 else 0
            if best_score < 45:
                trig_label="kein Trigger"; trig_text="Kein aktiver Spezialmuster-Trigger."; trig_action="Normale Analysebausteine verwenden."
            elif trigger_score >= 72:
                trig_label="bestaetigt"; trig_text="Spezialmuster-Trigger wirkt bestaetigt: Pivot/Struktur, Trend und Bestaetigung ziehen zusammen."; trig_action="Nur mit Aktion, Risiko, Entry-Zone und Konfluenz als aktiven Trigger werten."
            elif trigger_score >= 52:
                trig_label="erste Bestaetigung"; trig_text="Erste Bestaetigung sichtbar, aber noch nicht vollstaendig."; trig_action="Vorbereiten/aktiv pruefen; auf Schlusskurs, Volumen und Folgetag achten."
            elif trigger_score >= 30:
                trig_label="unter Beobachtung"; trig_text="Struktur ist interessant, aber Trigger ist noch unvollstaendig."; trig_action="Watchlist/Alarm am Pivotbereich setzen; nicht blind handeln."
            else:
                trig_label="noch nicht erreicht"; trig_text="Musterkontext moeglich, aber der operative Trigger fehlt."; trig_action="Auf Pivot-Ausbruch, Reclaim oder enge Konsolidierung warten."
        need_map = {
            "Pocket Pivot": f"Passt eher, wenn ein bullischer Volumentag nahe Pivot/MA-Struktur entsteht und der Kurs den Bereich um {_v1533_1_fmt_price(pivot_zone)} haelt oder ueberschreitet.",
            "VCP / Volatility Contraction": f"Passt eher, wenn die Range weiter eng bleibt und der Ausbruch ueber {_v1533_1_fmt_price(pivot_zone)} mit Volumen/Schlusskurs erfolgt.",
            "MA10/20 Pullback-Reaktion": f"Passt eher, wenn MA10/MA20 ({_v1533_1_fmt_price(ma10)} / {_v1533_1_fmt_price(ma20)}) halten, die Kerze bullisch dreht und kein starker Abgabedruck folgt.",
            "Undercut & Rally / Support-Reclaim": f"Passt eher, wenn der Reclaim ueber {_v1533_1_fmt_price(prev_low20)} haelt und Folgestaerke entsteht.",
            "Flat Base / Base Breakout": f"Passt eher, wenn die flache Range intakt bleibt und ein Schlusskurs ueber {_v1533_1_fmt_price(pivot_zone)} mit Volumen erfolgt.",
            "Tight Range Breakout": f"Passt eher, wenn die enge Range nach oben aufloest und der Kurs ueber {_v1533_1_fmt_price(pivot_zone)} schliesst.",
            "Accumulation Cluster": "Passt eher als Qualitaetsbestaetigung, wenn Akkumulation/Volumen weiter konstruktiv bleiben und Distribution nicht anzieht.",
            "Pullback Dry-Up": f"Passt eher, wenn der Pullback ruhig bleibt, MA10/MA20 ({_v1533_1_fmt_price(ma10)} / {_v1533_1_fmt_price(ma20)}) halten und anschliessend eine bullische Reaktion folgt.",
            "RS-New-High / Leadership-Reclaim": "Passt eher, wenn relative Staerke weiter anzieht und ein Kurs-/Pivottrigger nachfolgt.",
            "Double Bottom / Higher Low": f"Passt eher, wenn das zweite Tief haelt und der Kurs ueber das Zwischenhoch/Pivot um {_v1533_1_fmt_price(pivot_zone)} zieht.",
            "Failed Breakout / Exhaustion-Warnung": "Warnsignal: Passt als Bremse, wenn der Kurs nach Ausbruch/Stretch nicht anschliesst und unter Pivot/MA-Struktur zurueckfaellt.",
            "Wide & Loose / Climax-Warnung": "Warnsignal: Passt als Bremse, wenn die Bewegung sehr unruhig oder ueberdehnt wird und keine enge Base entsteht.",
            "High Tight Pivot": f"Passt wahrscheinlicher, wenn der Kurs den Pivotbereich um {_v1533_1_fmt_price(pivot_zone)} zurueckerobert oder darueber schliesst, MA10/MA20 halten und Volumen anzieht.",
            "Power Play": f"Passt wahrscheinlicher, wenn der starke Lauf nicht abverkauft wird, der Kurs eng nahe MA10/MA20 ({_v1533_1_fmt_price(ma10)} / {_v1533_1_fmt_price(ma20)}) konsolidiert und wieder nach oben dreht.",
            "High Tight Flag": f"Passt wahrscheinlicher, wenn die Flagge eng bleibt, MA10/MA20 halten und der Kurs den Pivotbereich um {_v1533_1_fmt_price(pivot_zone)} mit Schlusskurs/Volumen ueberschreitet.",
        }
        confirmation_needed = need_map.get(best_type, "Kein Spezialmuster aktiv; normale Entry-, S/R- und Konfluenzsignale bleiben wichtiger.")
        row_info = {
            "High Tight Pivot": ("Enger Pivot nahe Hoch.", "Frueher Trigger nahe Hoch: Käufer halten den Kurs eng am Pivot statt abzuverkaufen.", f"Ausbruch/Stabilisierung ueber Pivot um {_v1533_1_fmt_price(pivot_zone)}, MA10/MA20 halten, ideal mit Volumen."),
            "Power Play": ("Starker kurzer Impuls.", "Sehr starker Anstieg, der danach nicht stark abverkauft wird; nur interessant, wenn die enge Konsolidierung haelt.", f"Enge Konsolidierung statt Abverkauf; Reclaim/Halten von MA10/MA20 ({_v1533_1_fmt_price(ma10)} / {_v1533_1_fmt_price(ma20)})."),
            "High Tight Flag": ("Starker Move plus enge Flagge.", "Seltener Momentum-Aufbau: starker Lauf, danach kleine enge Flagge im oberen Bereich.", f"Flagge bleibt eng; Ausbruch ueber Pivot/Flagge um {_v1533_1_fmt_price(pivot_zone)} mit Schlusskurs/Volumen."),
            "Pocket Pivot": ("Bullischer Volumenimpuls nahe Pivot/MA.", "Frueher Kaufdruck vor dem klassischen Ausbruch; Volumen muss den Move bestaetigen.", f"Volumen ueber Schnitt, Schluss stark, Pivot/MA um {_v1533_1_fmt_price(pivot_zone)} wird gehalten/ueberschritten."),
            "VCP / Volatility Contraction": ("Schwankung zieht zusammen.", "Mehrere engere Ruecksetzer: Angebot trocknet aus, ein Ausbruch kann dadurch belastbarer werden.", f"Range bleibt eng; Ausbruch ueber {_v1533_1_fmt_price(pivot_zone)} mit Volumen."),
            "MA10/20 Pullback-Reaktion": ("Ruecksetzer reagiert an MA10/20.", "Trend-Pullback: Kurs testet die kurzfristigen Linien und zeigt dort wieder Nachfrage.", f"MA10/MA20 halten ({_v1533_1_fmt_price(ma10)} / {_v1533_1_fmt_price(ma20)}), bullische Kerze/Folgestaerke."),
            "Undercut & Rally / Support-Reclaim": ("Kurzer Bruch wird zurueckerobert.", "Shakeout/Reversal: ein Tief oder Support wird kurz verletzt und danach wieder zurueckerobert.", f"Reclaim ueber {_v1533_1_fmt_price(prev_low20)} haelt, ideal mit Volumen/Folgestaerke."),
            "Flat Base / Base Breakout": ("Flache Base / enge Range.", "Ruhige Seitwaertsphase; wird erst interessant, wenn die obere Range sauber bricht.", f"Schlusskurs ueber Range/Pivot {_v1533_1_fmt_price(pivot_zone)} mit Volumen; Invalidierung unter Range."),
            "Tight Range Breakout": ("Sehr enge Kurzfrist-Range.", "Kurzfristige Spannung baut sich auf; der Trigger ist der Ausbruch aus der engen Range.", f"Ausbruch ueber {_v1533_1_fmt_price(pivot_zone)}; nicht vor dem Trigger vorwegnehmen."),
            "Accumulation Cluster": ("Mehrere Akkumulations-/Volumenhinweise.", "Hinweis auf wiederholte Nachfrage/groessere Kaeufer; allein noch kein Entry-Signal.", "Qualitaetsbestaetigung; wird erst mit Entry-/Pivottrigger handelbar."),
            "Pullback Dry-Up": ("Ruhiger Pullback, Verkaufsdruck nimmt ab.", "Ruecksetzer bei sinkendem Volumen: Verkaufsdruck trocknet aus, danach braucht es eine bullische Reaktion.", f"MA10/MA20 halten ({_v1533_1_fmt_price(ma10)} / {_v1533_1_fmt_price(ma20)}) plus bullische Reaktion."),
            "RS-New-High / Leadership-Reclaim": ("Relative Staerke verbessert sich.", "Die Aktie wird relativ zum Markt/Sektor staerker; guter Zusatzfilter fuer Leader.", "Bestaetigt Leader-Qualitaet; aktiver Trigger braucht Kurs-/Pivotbestaetigung."),
            "Double Bottom / Higher Low": ("Moegliche Boden-/Higher-Low-Struktur.", "Bodenbildungs-/Turnaround-Struktur: zweites Tief haelt besser als das erste.", f"Zweites Tief haelt; Bruch ueber Zwischenhoch/Pivot {_v1533_1_fmt_price(pivot_zone)}."),
            "Failed Breakout / Exhaustion-Warnung": ("Warnung: Ausbruch/Stretch wird anfaellig.", "Warnsignal: Ausbruch scheitert oder der Kurs wirkt nach starkem Lauf erschoepft.", f"Defensiv, wenn Rueckfall unter Pivot {_v1533_1_fmt_price(pivot_zone)} oder MA10/MA20-Bruch folgt."),
            "Wide & Loose / Climax-Warnung": ("Warnung: zu unruhig oder ueberdehnt.", "Warnsignal: zu grosse, chaotische Schwankungen oder Climax-Lauf; schlechter fuer kontrollierte Entries.", "Keine Long-Bestaetigung; neue enge Base oder klare Stabilisierung abwarten."),
        }
        rows=[]
        for k in ["Pocket Pivot","VCP / Volatility Contraction","Flat Base / Base Breakout","Tight Range Breakout","MA10/20 Pullback-Reaktion","Pullback Dry-Up","Undercut & Rally / Support-Reclaim","Double Bottom / Higher Low","Accumulation Cluster","RS-New-High / Leadership-Reclaim","High Tight Pivot","Power Play","High Tight Flag","Failed Breakout / Exhaustion-Warnung","Wide & Loose / Climax-Warnung"]:
            les, expl, need = row_info[k]
            rows.append({"Muster": k, "Score": int(round(min(max(scores[k],0),100))), "Lesart": les, "Kurz erklärt": expl, "Damit es passt": need})
        out.update({
            "label": label, "phase": phase, "pattern_type": pattern_type, "summary": summary,
            "action_hint": action, "active_zone_text": f"Pivot/Triggerbereich um {_v1533_1_fmt_price(pivot_zone)}" if pivot_zone else "n/a",
            "trigger_label": trig_label, "trigger_score": trigger_score, "trigger_text": trig_text,
            "trigger_action": trig_action, "confirmation_needed": confirmation_needed,
            "drivers": (tdrivers + drivers)[:8], "rows": rows,
            "metrics": {"Kurs": round(price,2), "Pivotbereich": round(float(pivot_zone),2) if pivot_zone and np.isfinite(pivot_zone) else "n/a", "Range_10T_%": round(float(tight10),1), "Range_20T_%": round(float(tight20),1), "Volumen_Ratio": round(float(vol_ratio),2) if pd.notna(vol_ratio) else "n/a"},
        })
        return out
    except Exception as exc:
        out["summary"] = f"Setup-Muster-Kontext nicht belastbar: {exc}"
        return out


def _turnaround_v174_float(value, default=None):
    try:
        if value is None:
            return default
        if isinstance(value, str):
            value = value.replace('%', '').replace(',', '.').strip()
            if value.lower() in {'', '-', 'nan', 'none', 'n/a'}:
                return default
        out = float(value)
        if not np.isfinite(out):
            return default
        return out
    except Exception:
        return default


def _turnaround_v174_fmt(value, suffix=""):
    v = _turnaround_v174_float(value)
    if v is None:
        return "n/a"
    try:
        return f"{v:.2f}{suffix}"
    except Exception:
        return str(value)


def _turnaround_v174_pct(value):
    v = _turnaround_v174_float(value)
    return "n/a" if v is None else f"{v:.1f}%"


def _turnaround_v174_get(result, *keys, default=None):
    result = result or {}
    for key in keys:
        try:
            val = result.get(key)
        except Exception:
            val = None
        if val not in [None, "", "-", "n/a"]:
            return val
    return default


def build_turnaround_context_v174(chart_df=None, result=None):
    """Weicher charttechnischer Turnaround-Kontext.

    Der Baustein erkennt fruehe Stabilisierung, Reclaim-/Turnaround-Aufbau,
    bestaetigte Drehung oder gescheiterte Turnaround-Versuche. Er ist bewusst
    Kontext, kein automatisches Kaufsignal.
    """
    result = result or {}
    out = {
        "label": "kein klarer Turnaround",
        "phase": "Nicht aktiv",
        "score": 0,
        "summary": "Kein belastbarer charttechnischer Turnaround-Kontext erkennbar.",
        "action_hint": "Normale Trend-, Entry- und S/R-Logik nutzen.",
        "fits": [],
        "missing": [],
        "drivers": [],
        "key_level_text": "n/a",
        "invalid_text": "n/a",
        "fits_text": "",
        "missing_text": "",
        "is_score_relevant": False,
    }
    try:
        # Preis- und Trendwerte bevorzugt aus Chartdaten, sonst aus result.
        price = _turnaround_v174_float(_turnaround_v174_get(result, "price", "analysis_price", "Kurs"))
        ma10 = _turnaround_v174_float(_turnaround_v174_get(result, "ma10", "MA10"))
        ma20 = _turnaround_v174_float(_turnaround_v174_get(result, "ma20", "MA20"))
        ma50 = _turnaround_v174_float(_turnaround_v174_get(result, "ma50", "MA50"))
        ma200 = _turnaround_v174_float(_turnaround_v174_get(result, "ma200", "MA200"))
        prev_high20 = None; prev_low20 = None; high20 = None; low20 = None
        perf20 = _turnaround_v174_float(_turnaround_v174_get(result, "perf_20d", "return_20d", "performance_20d"))
        perf60 = _turnaround_v174_float(_turnaround_v174_get(result, "perf_60d", "return_60d", "performance_60d"))
        vol_ratio = _turnaround_v174_float(_turnaround_v174_get(result, "breakout_day_volume_ratio", "volume_ratio", "relative_volume", "Volumen_Ratio"))
        rs_acc = _turnaround_v174_float(_turnaround_v174_get(result, "rs_acceleration_score", "RS-Beschleunigung"))
        acc = _turnaround_v174_float(_turnaround_v174_get(result, "accumulation_score", "Akkumulation"))
        dist = _turnaround_v174_float(_turnaround_v174_get(result, "distribution_pressure_score", "distribution_score", "Distribution"))
        exit_score = _turnaround_v174_float(_turnaround_v174_get(result, "exit_score"), 0)
        risk_text = str(_turnaround_v174_get(result, "risk_final", "risk_label", "risk", default="")).lower()

        if chart_df is not None:
            dfp = chart_df.copy()
            close_col = "Close" if "Close" in dfp.columns else "Adj Close" if "Adj Close" in dfp.columns else None
            high_col = "High" if "High" in dfp.columns else close_col
            low_col = "Low" if "Low" in dfp.columns else close_col
            vol_col = "Volume" if "Volume" in dfp.columns else None
            if close_col:
                close = pd.to_numeric(dfp[close_col], errors="coerce").dropna()
                if len(close) >= 2:
                    price = float(close.iloc[-1]) if price is None else price
                    ma10 = float(close.rolling(10).mean().iloc[-1]) if len(close) >= 10 else ma10
                    ma20 = float(close.rolling(20).mean().iloc[-1]) if len(close) >= 20 else ma20
                    ma50 = float(close.rolling(50).mean().iloc[-1]) if len(close) >= 50 else ma50
                    ma200 = float(close.rolling(200).mean().iloc[-1]) if len(close) >= 200 else ma200
                    perf20 = ((float(close.iloc[-1]) / float(close.iloc[-21])) - 1) * 100 if len(close) > 21 and float(close.iloc[-21]) else perf20
                    perf60 = ((float(close.iloc[-1]) / float(close.iloc[-61])) - 1) * 100 if len(close) > 61 and float(close.iloc[-61]) else perf60
                if high_col and low_col and high_col in dfp.columns and low_col in dfp.columns:
                    high = pd.to_numeric(dfp[high_col], errors="coerce").dropna()
                    low = pd.to_numeric(dfp[low_col], errors="coerce").dropna()
                    if len(high) >= 21 and len(low) >= 21:
                        prev_high20 = float(high.iloc[:-1].tail(20).max())
                        prev_low20 = float(low.iloc[:-1].tail(20).min())
                        high20 = float(high.tail(20).max())
                        low20 = float(low.tail(20).min())
                if vol_col and vol_col in dfp.columns:
                    vol = pd.to_numeric(dfp[vol_col], errors="coerce").dropna()
                    if len(vol) >= 20 and float(vol.tail(20).mean() or 0) > 0:
                        vol_ratio = float(vol.iloc[-1] / vol.tail(20).mean())

        if price is None:
            return out

        fits=[]; missing=[]; drivers=[]
        def add_fit(txt):
            if txt and txt not in fits: fits.append(txt)
        def add_missing(txt):
            if txt and txt not in missing: missing.append(txt)
        def add_driver(txt):
            if txt and txt not in drivers: drivers.append(txt)

        score = 0
        # Turnaround braucht meist vorherige Schwaeche oder zumindest Reclaim-Kontext.
        prior_weak = False
        if perf60 is not None and perf60 <= -8:
            prior_weak = True; score += 16; add_fit(f"vorherige Schwächephase ({_turnaround_v174_pct(perf60)} / 60T)")
        elif ma50 and price < ma50:
            prior_weak = True; score += 10; add_fit("Kurs kommt aus einer schwächeren Struktur unter MA50")
        else:
            add_driver("kein klassischer Turnaround-Kontext; eher Trendfolge/Continuation")

        above_ma10 = bool(ma10 and price >= ma10)
        above_ma20 = bool(ma20 and price >= ma20)
        above_ma50 = bool(ma50 and price >= ma50)
        above_ma200 = bool(ma200 and price >= ma200)
        if above_ma10: score += 8; add_fit(f"MA10 zurückerobert/gehalten ({_turnaround_v174_fmt(ma10)})")
        else: add_missing(f"MA10-Reclaim fehlt ({_turnaround_v174_fmt(ma10)})")
        if above_ma20: score += 10; add_fit(f"MA20 zurückerobert/gehalten ({_turnaround_v174_fmt(ma20)})")
        else: add_missing(f"MA20-Reclaim fehlt ({_turnaround_v174_fmt(ma20)})")
        if above_ma50: score += 18; add_fit(f"MA50 zurückerobert/gehalten ({_turnaround_v174_fmt(ma50)})")
        else: add_missing(f"MA50-Reclaim fehlt ({_turnaround_v174_fmt(ma50)})")
        if above_ma200: score += 6

        if prev_high20 and price >= prev_high20 * 1.002:
            score += 18; add_fit(f"Bruch über kurzfristiges Hoch ({_turnaround_v174_fmt(prev_high20)})")
        elif prev_high20:
            add_missing(f"Bruch über kurzfristiges Hoch fehlt ({_turnaround_v174_fmt(prev_high20)})")

        if prev_low20 and price > prev_low20 * 1.01:
            score += 6; add_fit(f"Support/Reclaim über 20T-Tief ({_turnaround_v174_fmt(prev_low20)})")
        elif prev_low20:
            add_missing(f"Support über 20T-Tief muss halten ({_turnaround_v174_fmt(prev_low20)})")

        if vol_ratio is not None and vol_ratio >= 1.15:
            score += 10; add_fit(f"Volumen bestätigt Erholung ({vol_ratio:.2f}x)")
        else:
            add_missing("Volumenbestätigung fehlt")
        if rs_acc is not None and rs_acc >= 55:
            score += 8; add_fit(f"Relative Stärke verbessert sich ({rs_acc:.0f}/100)")
        else:
            add_missing("Relative-Stärke-Verbesserung fehlt")
        if acc is not None and dist is not None and acc >= dist + 5:
            score += 8; add_fit(f"Akkumulation über Distribution ({acc:.0f}/{dist:.0f})")
        elif dist is not None and acc is not None and dist > acc + 10:
            score -= 10; add_missing(f"Distribution noch höher als Akkumulation ({acc:.0f}/{dist:.0f})")
        if exit_score is not None and exit_score >= 55:
            score -= 14; add_missing(f"Exit-/Trenddruck erhöht ({exit_score:.0f}/100)")
        if "hoch" in risk_text or "erhöht" in risk_text:
            score -= 6

        # First higher low proxy: price above recent 20d low but not necessarily over high.
        if low20 and price > low20 * 1.05:
            score += 6; add_fit(f"Abstand zum jüngsten Tief positiv ({_turnaround_v174_fmt(low20)})")
        score = max(0, min(100, int(round(score))))

        failed = False
        if (ma20 and price < ma20 * 0.985 and dist is not None and acc is not None and dist > acc + 10) or (exit_score is not None and exit_score >= 70):
            failed = True

        if failed:
            label = "gescheiterter Turnaround"
            phase = "Defensiv"
            summary = "Der Turnaround-Versuch wirkt angeschlagen. Rueckeroberung wichtiger Linien/Zonen fehlt oder Abgabedruck dominiert."
            action = "Nicht erzwingen. Erst neue Stabilisierung, MA-Reclaim und nachlassenden Abgabedruck abwarten."
        elif score >= 72:
            label = "Turnaround bestätigt"
            phase = "Bestätigend"
            summary = "Mehrere Reclaim- und Bestätigungssignale sprechen für eine belastbarere Drehung."
            action = "Aktiv prüfen, aber nur mit Stop/Invalidierung. Ruecksetzer/Reclaim nicht ueberdehnen."
        elif score >= 52:
            label = "Turnaround im Aufbau"
            phase = "Aufbau"
            summary = "Erste wichtige Reclaims/Bestätigungen sind sichtbar, aber der Turnaround ist noch nicht vollständig belastbar."
            action = "Vorbereiten. Belastbarer wird es bei Bruch über kurzfristiges Hoch, MA50-Reclaim und Volumenbestätigung."
        elif score >= 30:
            label = "frühe Stabilisierung"
            phase = "Früh"
            summary = "Erste Stabilisierung ist möglich, aber noch ohne ausreichende Bestätigung."
            action = "Beobachten. Erst bei MA10/MA20-Reclaim, höherem Tief und bullischer Reaktion aktiv werden."
        else:
            label = "kein belastbarer Turnaround"
            phase = "Nicht aktiv"
            summary = "Noch keine ausreichenden charttechnischen Hinweise auf eine tragfähige Drehung."
            action = "Nicht aus Turnaround-Sicht handeln; normale Entry- und Trendlogik bleibt führend."

        key_levels=[]
        if ma20: key_levels.append(f"MA20 {_turnaround_v174_fmt(ma20)}")
        if ma50: key_levels.append(f"MA50 {_turnaround_v174_fmt(ma50)}")
        if prev_high20: key_levels.append(f"kurzfristiges Hoch {_turnaround_v174_fmt(prev_high20)}")
        key_level_text = " · ".join(key_levels[:3]) if key_levels else "n/a"
        invalid=[]
        if ma20: invalid.append(f"Bruch unter MA20 {_turnaround_v174_fmt(ma20)}")
        if prev_low20: invalid.append(f"Bruch unter 20T-Tief/Support {_turnaround_v174_fmt(prev_low20)}")
        invalid_text = " · ".join(invalid[:2]) if invalid else "n/a"

        out.update({
            "label": label,
            "phase": phase,
            "score": score,
            "summary": summary,
            "action_hint": action,
            "fits": fits[:5],
            "missing": missing[:5],
            "drivers": drivers[:4],
            "key_level_text": key_level_text,
            "invalid_text": invalid_text,
            "fits_text": " · ".join(fits[:5]),
            "missing_text": " · ".join(missing[:5]),
            "is_score_relevant": False,
        })
        return out
    except Exception as exc:
        out["summary"] = f"Turnaround-Kontext nicht belastbar: {exc}"
        out["action_hint"] = "Nicht als eigenständiges Signal verwenden."
        return out

def build_wave_structure_context_v1532(chart_df=None, result=None):
    """Weicher Wellen-/Strukturkontext ohne harte Elliott-Wellen-Signale.

    Ziel: Keine Scheingenauigkeit. Die Funktion beschreibt nur, ob die aktuelle
    Kursstruktur eher impulsiv, korrektiv, fortgeschritten/ueberdehnt oder unklar
    wirkt. Der Baustein ist bewusst Kontext und nicht score-wirksam.
    """
    result = result or {}
    out = {
        "label": "unklar",
        "phase": "Nicht belastbar",
        "summary": "Keine belastbare Struktur ableitbar.",
        "action_hint": "Nicht als eigenständiges Signal verwenden.",
        "score": 0,
        "drivers": [],
        "zones": [],
        "plain_hint": "Dieser Kontext beschreibt nur die Struktur des letzten Moves. Er ist kein eigenständiges Kauf-/Verkaufssignal.",
        "confirmation_label": "nicht geprüft",
        "confirmation_score": 0,
        "confirmation_text": "Noch keine automatische Bestätigungsprüfung verfügbar.",
        "confirmation_action": "Bei Annäherung an ein Fibonacci-Level erneut auf Kursreaktion, Kerze, Volumen und kurzfristiges Timing prüfen.",
        "confirmation_drivers": [],
        "is_score_relevant": False,
    }
    try:
        dfw = chart_df.copy() if chart_df is not None else None
        if dfw is None or dfw.empty:
            return out
        close_col = "Close" if "Close" in dfw.columns else "Adj Close" if "Adj Close" in dfw.columns else None
        high_col = "High" if "High" in dfw.columns else close_col
        low_col = "Low" if "Low" in dfw.columns else close_col
        if close_col is None:
            return out
        close = pd.to_numeric(dfw[close_col], errors="coerce").dropna()
        high = pd.to_numeric(dfw[high_col], errors="coerce").dropna() if high_col else close
        low = pd.to_numeric(dfw[low_col], errors="coerce").dropna() if low_col else close
        if len(close) < 40:
            return out
        price = float(close.iloc[-1])
        ma10 = float(close.rolling(10).mean().iloc[-1]) if len(close) >= 10 else np.nan
        ma20 = float(close.rolling(20).mean().iloc[-1]) if len(close) >= 20 else np.nan
        ma50 = float(close.rolling(50).mean().iloc[-1]) if len(close) >= 50 else np.nan
        high20 = float(high.tail(20).max())
        low20 = float(low.tail(20).min())
        high60 = float(high.tail(min(60, len(high))).max())
        low60 = float(low.tail(min(60, len(low))).min())
        high52 = _fomo_v1525_parse_float(result.get("high52"))
        if high52 is None:
            high52 = np.nan
        roc20 = ((price / float(close.iloc[-21])) - 1.0) * 100.0 if len(close) > 21 and float(close.iloc[-21]) else np.nan
        roc60 = ((price / float(close.iloc[-61])) - 1.0) * 100.0 if len(close) > 61 and float(close.iloc[-61]) else np.nan
        dist_ma10 = ((price / ma10) - 1.0) * 100.0 if pd.notna(ma10) and ma10 else np.nan
        dist_ma20 = ((price / ma20) - 1.0) * 100.0 if pd.notna(ma20) and ma20 else np.nan
        dist_ma50 = ((price / ma50) - 1.0) * 100.0 if pd.notna(ma50) and ma50 else np.nan
        pullback20 = ((high20 - price) / high20) * 100.0 if high20 else np.nan
        rebound20 = ((price - low20) / low20) * 100.0 if low20 else np.nan
        range_pos20 = ((price - low20) / max(high20 - low20, 1e-9)) * 100.0
        near_52w_high = pd.notna(high52) and high52 > 0 and ((high52 - price) / high52) * 100.0 <= 5.0

        drivers = []
        score = 0.0
        if pd.notna(roc20):
            if roc20 >= 12:
                drivers.append(f"starker 20T-Lauf ({roc20:.1f}%)")
                score += 24
            elif roc20 >= 5:
                drivers.append(f"konstruktiver 20T-Lauf ({roc20:.1f}%)")
                score += 14
            elif roc20 <= -8:
                drivers.append(f"20T-Korrektur ({roc20:.1f}%)")
                score -= 14
        if pd.notna(roc60):
            if roc60 >= 25:
                drivers.append(f"starker 60T-Impuls ({roc60:.1f}%)")
                score += 22
            elif roc60 >= 10:
                drivers.append(f"positiver 60T-Trend ({roc60:.1f}%)")
                score += 12
            elif roc60 <= -15:
                drivers.append(f"60T-Schwäche ({roc60:.1f}%)")
                score -= 16
        if near_52w_high:
            drivers.append("nahe Jahreshoch")
            score += 12
        if pd.notna(dist_ma10):
            if dist_ma10 > 8:
                drivers.append(f"deutlich über MA10 ({dist_ma10:.1f}%)")
                score += 16
            elif dist_ma10 < -3:
                drivers.append(f"unter MA10 ({dist_ma10:.1f}%)")
                score -= 12
            elif abs(dist_ma10) <= 2:
                drivers.append(f"MA10-Test/nahe MA10 ({dist_ma10:.1f}%)")
        if pd.notna(dist_ma50):
            if dist_ma50 > 18:
                drivers.append(f"deutlich über MA50 ({dist_ma50:.1f}%)")
                score += 16
            elif dist_ma50 < -5:
                drivers.append(f"unter MA50 ({dist_ma50:.1f}%)")
                score -= 18
        if pd.notna(pullback20):
            if pullback20 <= 2 and range_pos20 >= 78:
                drivers.append("nahe 20T-Hoch")
                score += 10
            elif 3 <= pullback20 <= 10 and pd.notna(dist_ma20) and dist_ma20 >= -2:
                drivers.append(f"geordneter Pullback vom 20T-Hoch ({pullback20:.1f}%)")
                score -= 2
            elif pullback20 > 14:
                drivers.append(f"tiefer Pullback vom 20T-Hoch ({pullback20:.1f}%)")
                score -= 14

        # Phase ableiten: bewusst weich, keine harte Elliott-Zaehllogik.
        if pd.notna(roc60) and roc60 >= 20 and pd.notna(dist_ma10) and dist_ma10 > 6 and pd.notna(dist_ma50) and dist_ma50 > 15:
            label = "fortgeschritten"
            phase = "Späte/fortgeschrittene Impulsstruktur"
            summary = "Trend wirkt stark, aber bereits fortgeschritten. Nicht hinterherlaufen; Pullback/Base bevorzugen."
            action = "Einstieg nur bei Rücksetzer, neuer Base oder klarer Bestätigung; FOMO-Risiko beachten."
        elif pd.notna(roc20) and roc20 >= 5 and pd.notna(dist_ma10) and dist_ma10 >= -1 and pd.notna(dist_ma50) and dist_ma50 >= 0:
            label = "impulsiv"
            phase = "Konstruktive Impulsstruktur"
            summary = "Kursstruktur wirkt trendfolgend/impulsiv, solange MA10/MA20 und Triggerzone halten."
            action = "Bei Entry-Nähe Bestätigung prüfen; unter MA10/Triggerzone wird die Struktur anfälliger."
        elif pd.notna(pullback20) and 3 <= pullback20 <= 12 and pd.notna(dist_ma20) and dist_ma20 >= -3 and pd.notna(dist_ma50) and dist_ma50 >= -2:
            label = "korrektiv"
            phase = "Geordnete Korrektur / mögliche Base"
            summary = "Rücklauf wirkt bisher eher geordnet als wie ein Trendbruch. Entscheidend ist die Reaktion an Support/MA10/MA20."
            action = "Bullisher erst bei Stabilisierung/Reclaim; defensiver bei Bruch der Support-/Triggerzone."
        elif pd.notna(dist_ma50) and dist_ma50 < -5:
            label = "angeschlagen"
            phase = "Korrektur-/Schwächestruktur"
            summary = "Struktur ist angeschlagen; ein Einstieg braucht erst Reclaim und neue Stabilisierung."
            action = "Keine aggressive Entry-Logik; erst Bodenbildung oder klare Reversal-Struktur abwarten."
        else:
            label = "unklar"
            phase = "Keine klare Wellen-/Strukturlesart"
            summary = "Die Struktur liefert keinen belastbaren Zusatzvorteil. Klassische Trigger und Supportzonen bleiben wichtiger."
            action = "Nicht aus der Struktur ableiten; Entry-/Support-Bestätigung abwarten."

        # Konkrete Orientierungspunkte fuer die Anzeige. Keine harte Wellenzaehlung.
        support_txt = _v1533_1_support_zone_text(result, ma20 if pd.notna(ma20) else ma50)
        zones = [
            {"Punkt": "Aktueller Kurs", "Zone/Wert": _v1533_1_fmt_price(price), "Lesart": "Ausgangspunkt fuer die Strukturlesart."},
            {"Punkt": "MA10", "Zone/Wert": _v1533_1_fmt_price(ma10), "Lesart": "Kurzfristiger Trendtakt. Deutlich darueber = moeglich spaet/ueberdehnt; Reclaim/Halten = konstruktiv."},
            {"Punkt": "MA20", "Zone/Wert": _v1533_1_fmt_price(ma20), "Lesart": "Erste Pullback-/Stabilisierungszone im Trend."},
            {"Punkt": "MA50", "Zone/Wert": _v1533_1_fmt_price(ma50), "Lesart": "Mittelfristige Strukturzone. Bruch/Reclaim veraendert die Lage deutlich."},
            {"Punkt": "Naechste Invalidierung", "Zone/Wert": support_txt, "Lesart": "Darunter wird die Struktur defensiver; nicht als exakter Stop missverstehen."},
        ]
        if label == "fortgeschritten":
            plain_hint = f"Starker Move, aber der Kurs liegt deutlich ueber dem kurzfristigen Taktgeber. Kurs {_v1533_1_fmt_price(price)}, MA10 {_v1533_1_fmt_price(ma10)} ({_v1533_1_fmt_pct(dist_ma10)} Abstand)."
        elif label == "impulsiv":
            plain_hint = f"Trendstruktur ist konstruktiv, solange Kurs {_v1533_1_fmt_price(price)} MA10/MA20 und Triggerzone haelt."
        elif label == "korrektiv":
            plain_hint = f"Ruecklauf wirkt bisher geordnet. Relevant ist jetzt Reaktion/Reclaim im Bereich MA10/MA20 ({_v1533_1_fmt_price(ma10)} / {_v1533_1_fmt_price(ma20)})."
        elif label == "angeschlagen":
            plain_hint = f"Struktur ist angeschlagen. Erst Reclaim von MA50 ({_v1533_1_fmt_price(ma50)}) oder klare Bodenbildung verbessert die Lage."
        else:
            plain_hint = "Keine belastbare Zusatzlesart. Entry-Zone, Support/Resistance und Bestaetigung bleiben primaer."

        # v15.36.2: Struktur-Trigger automatisch pruefen.
        # Der Wellen-/Strukturkontext bleibt weich/nicht score-wirksam, sagt aber jetzt,
        # ob ein sinnvoller Pullback-/Reclaim-/Trendhalte-Trigger bereits erreicht wurde.
        try:
            open_col = "Open" if "Open" in dfw.columns else close_col
            volume_col = "Volume" if "Volume" in dfw.columns else None
            open_s = pd.to_numeric(dfw[open_col], errors="coerce").dropna() if open_col else close
            vol_s = pd.to_numeric(dfw[volume_col], errors="coerce").dropna() if volume_col else pd.Series(dtype=float)
            last_open = float(open_s.iloc[-1]) if len(open_s) else np.nan
            last_high = float(high.iloc[-1]) if len(high) else np.nan
            last_low = float(low.iloc[-1]) if len(low) else np.nan
            prev_close = float(close.iloc[-2]) if len(close) >= 2 else np.nan
            prev_high = float(high.iloc[-2]) if len(high) >= 2 else np.nan
            vol_last = float(vol_s.iloc[-1]) if len(vol_s) else np.nan
            vol20 = float(vol_s.tail(20).mean()) if len(vol_s) >= 20 else np.nan
            bullish_candle = pd.notna(last_open) and price > last_open
            close_up = pd.notna(prev_close) and price > prev_close
            breakout_prev_high = pd.notna(prev_high) and price > prev_high
            lower_wick_reaction = pd.notna(last_low) and pd.notna(last_open) and (min(price, last_open) - last_low) > max(abs(price - last_open) * 0.7, price * 0.003)
            vol_confirm = pd.notna(vol_last) and pd.notna(vol20) and vol20 > 0 and vol_last >= vol20 * 1.05
            near_ma10 = pd.notna(ma10) and ma10 > 0 and abs(price / ma10 - 1.0) <= 0.018
            near_ma20 = pd.notna(ma20) and ma20 > 0 and abs(price / ma20 - 1.0) <= 0.022
            above_ma10 = pd.notna(ma10) and price >= ma10
            above_ma20 = pd.notna(ma20) and price >= ma20
            reclaim_ma10 = above_ma10 and pd.notna(prev_close) and pd.notna(ma10) and prev_close < ma10
            reclaim_ma20 = above_ma20 and pd.notna(prev_close) and pd.notna(ma20) and prev_close < ma20

            conf_score = 0
            conf_drivers = []
            if bullish_candle:
                conf_score += 16; conf_drivers.append("bullische Tageskerze")
            if close_up:
                conf_score += 14; conf_drivers.append("Schluss ueber Vortag")
            if breakout_prev_high:
                conf_score += 20; conf_drivers.append("Bruch ueber Vortageshoch")
            if lower_wick_reaction:
                conf_score += 14; conf_drivers.append("Kaufreaktion/unterer Docht")
            if vol_confirm:
                conf_score += 16; conf_drivers.append("Volumen bestaetigt")
            if above_ma10:
                conf_score += 10; conf_drivers.append("ueber MA10")
            if above_ma20:
                conf_score += 8; conf_drivers.append("ueber MA20")
            if reclaim_ma10 or reclaim_ma20:
                conf_score += 14; conf_drivers.append("Reclaim kurzfristiger Linie")

            if label == "fortgeschritten":
                if near_ma10 or near_ma20:
                    trigger_base = f"Pullback hat den Bereich MA10/MA20 erreicht ({_v1533_1_fmt_price(ma10)} / {_v1533_1_fmt_price(ma20)})."
                else:
                    trigger_base = f"Pullback-Trigger noch nicht erreicht. Sinnvolle Pruefzone waere eher MA10/MA20 ({_v1533_1_fmt_price(ma10)} / {_v1533_1_fmt_price(ma20)}) oder neue Base."
                    conf_score = min(conf_score, 45)
            elif label == "korrektiv":
                trigger_base = f"Korrektur-/Base-Trigger pruefen: Reaktion/Reclaim bei MA10/MA20 ({_v1533_1_fmt_price(ma10)} / {_v1533_1_fmt_price(ma20)})."
            elif label == "impulsiv":
                trigger_base = f"Trendhalte-Trigger: Kurs sollte MA10/MA20 halten ({_v1533_1_fmt_price(ma10)} / {_v1533_1_fmt_price(ma20)})."
            elif label == "angeschlagen":
                trigger_base = f"Reclaim-Trigger fehlt. Bullisher erst bei Rueckeroberung von MA50 ({_v1533_1_fmt_price(ma50)}) oder klarer Bodenbildung."
                conf_score = min(conf_score, 45)
            else:
                trigger_base = "Kein belastbarer Struktur-Trigger. Klassische Entry-/Support-Bestaetigung nutzen."
                conf_score = min(conf_score, 35)

            if label in {"fortgeschritten", "korrektiv"} and not (near_ma10 or near_ma20 or reclaim_ma10 or reclaim_ma20):
                conf_label = "noch nicht erreicht"
                conf_text = trigger_base
                conf_action = "Nicht aus der Struktur handeln; Pullback/Base oder klaren Reclaim abwarten."
            elif conf_score >= 72:
                conf_label = "bestaetigt"
                conf_text = trigger_base + " Reaktion ist bereits deutlich bestaetigt."
                conf_action = "Aktiv pruefen; trotzdem Entry-/Risikolimit und Supportbruch beachten."
            elif conf_score >= 52:
                conf_label = "erste Bestaetigung"
                conf_text = trigger_base + " Erste Reaktion sichtbar, aber noch nicht voll bestaetigt."
                conf_action = "Vorbereiten; Einstieg erst mit weiterer Bestaetigung/sauberem Trigger."
            elif conf_score >= 32:
                conf_label = "unter Beobachtung"
                conf_text = trigger_base + " Reaktion ist noch unvollstaendig."
                conf_action = "Beobachten; ohne Kerzen-/Volumenbestaetigung nicht handeln."
            else:
                conf_label = "kein Trigger"
                conf_text = trigger_base
                conf_action = "Abwarten; Struktur liefert aktuell keinen eigenstaendigen Trigger."

            out["confirmation_label"] = conf_label
            out["confirmation_score"] = int(max(0, min(100, round(conf_score))))
            out["confirmation_text"] = conf_text
            out["confirmation_action"] = conf_action
            out["confirmation_drivers"] = conf_drivers[:5]
        except Exception:
            out["confirmation_label"] = "nicht belastbar"
            out["confirmation_score"] = 0
            out["confirmation_text"] = "Struktur-Trigger konnte nicht automatisch geprueft werden."
            out["confirmation_action"] = "Nicht als eigenstaendiges Signal verwenden."
            out["confirmation_drivers"] = []

        out.update({
            "label": label,
            "phase": phase,
            "summary": summary,
            "action_hint": action,
            "score": int(max(0, min(100, round(score + 35)))),
            "drivers": drivers[:5],
            "zones": zones,
            "plain_hint": plain_hint,
            "metrics": {
                "Aktueller_Kurs": round(float(price), 2),
                "MA10": round(float(ma10), 2) if pd.notna(ma10) else "n/a",
                "MA20": round(float(ma20), 2) if pd.notna(ma20) else "n/a",
                "MA50": round(float(ma50), 2) if pd.notna(ma50) else "n/a",
                "20T_Hoch": round(float(high20), 2) if pd.notna(high20) else "n/a",
                "20T_Tief": round(float(low20), 2) if pd.notna(low20) else "n/a",
                "20T_Performance_%": round(float(roc20), 1) if pd.notna(roc20) else "n/a",
                "60T_Performance_%": round(float(roc60), 1) if pd.notna(roc60) else "n/a",
                "Abstand_MA10_%": round(float(dist_ma10), 1) if pd.notna(dist_ma10) else "n/a",
                "Abstand_MA50_%": round(float(dist_ma50), 1) if pd.notna(dist_ma50) else "n/a",
                "Pullback_vom_20T_Hoch_%": round(float(pullback20), 1) if pd.notna(pullback20) else "n/a",
            },
        })
        return out
    except Exception as exc:
        out["summary"] = f"Strukturkontext nicht belastbar: {exc}"
        return out



def _wave_v190_fmt_num(value, digits=2):
    try:
        if value is None or pd.isna(value):
            return "n/a"
        return f"{float(value):.{digits}f}"
    except Exception:
        return "n/a"


def _wave_v190_swing_points(df, high_col="High", low_col="Low", close_col="Close", window=3, max_points=9):
    """Findet robuste lokale Swing-Highs/-Lows ohne externe Abhaengigkeiten."""
    points = []
    try:
        highs = pd.to_numeric(df[high_col], errors="coerce") if high_col in df.columns else pd.to_numeric(df[close_col], errors="coerce")
        lows = pd.to_numeric(df[low_col], errors="coerce") if low_col in df.columns else pd.to_numeric(df[close_col], errors="coerce")
        closes = pd.to_numeric(df[close_col], errors="coerce")
        n = len(closes)
        if n < window * 2 + 8:
            return []
        start = max(window, n - 180)
        for i in range(start, n - window):
            h = highs.iloc[i]
            l = lows.iloc[i]
            if pd.isna(h) or pd.isna(l):
                continue
            h_slice = highs.iloc[i-window:i+window+1]
            l_slice = lows.iloc[i-window:i+window+1]
            if h >= h_slice.max() and h > h_slice.drop(highs.index[i], errors="ignore").max():
                points.append({"idx": int(i), "type": "H", "price": float(h)})
            if l <= l_slice.min() and l < l_slice.drop(lows.index[i], errors="ignore").min():
                points.append({"idx": int(i), "type": "L", "price": float(l)})
        points = sorted(points, key=lambda x: x["idx"])
        cleaned = []
        for p in points:
            if not cleaned:
                cleaned.append(p)
                continue
            last = cleaned[-1]
            if p["type"] == last["type"]:
                if (p["type"] == "H" and p["price"] >= last["price"]) or (p["type"] == "L" and p["price"] <= last["price"]):
                    cleaned[-1] = p
            else:
                cleaned.append(p)
        return cleaned[-max_points:]
    except Exception:
        return []



def _wave_v191_sequence_text(sequence):
    seq = str(sequence or "").strip().upper()
    mapping = {
        "HH/HL": "höhere Hochs und höhere Tiefs",
        "HH": "höheres Hoch, aber noch kein bestätigtes höheres Tief",
        "HL": "höheres Tief, aber noch kein neues höheres Hoch",
        "LH/LL": "tiefere Hochs und tiefere Tiefs",
        "LH": "tieferes Hoch",
        "LL": "tieferes Tief",
    }
    return mapping.get(seq, "gemischte Hoch-/Tief-Struktur")


def _wave_v191_readable_status(label, phase, quality_label, sequence):
    lbl = str(label or "").lower()
    q = str(quality_label or "").lower()
    if lbl in {"impulsfortsetzung", "welle-2-pullback"}:
        if q in {"hoch", "gut"}:
            return "Konstruktiv und nahe an einer Bestätigung"
        return "Konstruktiv, aber noch nicht klar genug bestätigt"
    if lbl == "frueher-reclaim":
        return "Frühe Stabilisierung, Bestätigung fehlt noch"
    if lbl == "abwaertsstruktur":
        return "Defensiv: die Wellenstruktur ist angeschlagen"
    if "gemischt" in lbl or "gemischt" in str(phase or "").lower():
        if str(sequence or "").upper() == "HH/HL":
            return "Konstruktiv, aber noch nicht eindeutig bestätigt"
        return "Seitwärts/gemischt: nicht aus der Wellenstruktur allein handeln"
    return "Nicht eindeutig genug für ein eigenes Signal"


def _wave_v191_strip_price_text(text):
    txt = str(text or "").strip()
    if not txt or txt.lower() in {"n/a", "nan", "none", "-"}:
        return "n/a"
    return txt


def _wave_v191_build_readable_fields(pkg):
    """Macht aus technischen Wellenfeldern eine verständliche UI-Lesart."""
    pkg = pkg or {}
    phase = str(pkg.get("wave_phase") or pkg.get("phase") or "-")
    label = str(pkg.get("wave_label") or pkg.get("label") or "")
    sequence = str(pkg.get("wave_sequence") or "gemischt")
    quality = str(pkg.get("wave_quality_label") or "-")
    trigger = _wave_v191_strip_price_text(pkg.get("wave_trigger") or pkg.get("confirmation_text") or "-")
    invalidation = _wave_v191_strip_price_text(pkg.get("wave_invalidation") or "-")
    target = _wave_v191_strip_price_text(pkg.get("wave_target_zone") or "-")
    seq_text = _wave_v191_sequence_text(sequence)
    status = _wave_v191_readable_status(label, phase, quality, sequence)

    if "HH/HL" in sequence.upper() or seq_text.startswith("höhere"):
        meaning = (
            f"Der Kurs zeigt {seq_text}. Das spricht grundsätzlich für eine intakte Aufwärtsstruktur. "
            f"Die Qualität ist {quality}; deshalb sollte der Trigger bestätigt werden, bevor daraus ein aktiver Einstieg wird."
        )
    elif "LH/LL" in sequence.upper() or "tiefere" in seq_text:
        meaning = (
            f"Der Kurs zeigt {seq_text}. Das bremst Long-Setups; erst ein Reclaim und neue höhere Tiefs würden die Lage verbessern."
        )
    else:
        meaning = (
            f"Die Swing-Folge ist gemischt. Fibonacci-Zonen, Entry-Zone, Volumen und klassische Trigger bleiben wichtiger als die Wellenstruktur allein."
        )

    if trigger and trigger != "n/a":
        action = f"Aktiv wird die Struktur erst bei: {trigger}."
    else:
        action = "Aktiv wird die Struktur erst bei einem klaren Reclaim oder Ausbruch mit Bestätigung."

    if invalidation and invalidation != "n/a":
        risk = f"Hinfällig bzw. angeschlagen wird sie bei: {invalidation}."
    else:
        risk = "Hinfällig wird sie bei Bruch der nächsten relevanten Support-/Entry-Zone."

    if target and target != "n/a":
        target_text = f"Erste Zielzone bei Bestätigung: {target}."
    else:
        target_text = "Eine belastbare Zielzone ist aus der Wellenstruktur noch nicht ableitbar."

    compact = f"{status}. {meaning} {action} {risk} {target_text}"
    return {
        "wave_readable_status": status,
        "wave_readable_sequence": seq_text,
        "wave_readable_meaning": meaning,
        "wave_readable_action": action,
        "wave_readable_risk": risk,
        "wave_readable_target": target_text,
        "wave_readable_compact": compact,
    }

def build_wave_structure_context_v190(chart_df=None, result=None):
    """v19.0: Robuste Swing-/Wellenstruktur-Analyse.

    Keine dogmatische Elliott-Wellen-Zaehlung. Die Funktion arbeitet regelbasiert:
    Swing High/Low, HH/HL/LH/LL-Sequenz, Impuls/Korrektur, Pullback-Tiefe,
    Trigger, Invalidierung und moegliche Extension-Zielzone.
    """
    base = build_wave_structure_context_v1532(chart_df, result)
    result = result or {}
    try:
        df = chart_df.copy() if chart_df is not None else None
        if df is None or df.empty:
            return base
        close_col = "Close" if "Close" in df.columns else "Adj Close" if "Adj Close" in df.columns else None
        if close_col is None:
            return base
        high_col = "High" if "High" in df.columns else close_col
        low_col = "Low" if "Low" in df.columns else close_col
        close = pd.to_numeric(df[close_col], errors="coerce").dropna()
        high = pd.to_numeric(df[high_col], errors="coerce").dropna()
        low = pd.to_numeric(df[low_col], errors="coerce").dropna()
        if len(close) < 60:
            return base
        price = float(close.iloc[-1])
        ma20 = float(close.rolling(20).mean().iloc[-1]) if len(close) >= 20 else np.nan
        ma50 = float(close.rolling(50).mean().iloc[-1]) if len(close) >= 50 else np.nan
        swings = _wave_v190_swing_points(df, high_col=high_col, low_col=low_col, close_col=close_col, window=3, max_points=10)
        if len(swings) < 4:
            base.update({
                "wave_phase": "Nicht belastbar",
                "wave_sequence": "zu wenige Swing-Punkte",
                "wave_quality_label": "n/a",
                "wave_trigger": base.get("confirmation_text", "klassische Trigger nutzen"),
                "wave_invalidation": base.get("zones", [{}])[-1].get("Zone/Wert", "n/a") if base.get("zones") else "n/a",
                "wave_target_zone": "n/a",
            })
            base.update(_wave_v191_build_readable_fields(base))
            return base

        highs = [p for p in swings if p["type"] == "H"]
        lows = [p for p in swings if p["type"] == "L"]
        last_high = highs[-1] if highs else None
        prev_high = highs[-2] if len(highs) >= 2 else None
        last_low = lows[-1] if lows else None
        prev_low = lows[-2] if len(lows) >= 2 else None
        hh = bool(last_high and prev_high and last_high["price"] > prev_high["price"])
        hl = bool(last_low and prev_low and last_low["price"] > prev_low["price"])
        lh = bool(last_high and prev_high and last_high["price"] < prev_high["price"])
        ll = bool(last_low and prev_low and last_low["price"] < prev_low["price"])
        seq_parts = []
        if hh: seq_parts.append("HH")
        elif lh: seq_parts.append("LH")
        if hl: seq_parts.append("HL")
        elif ll: seq_parts.append("LL")
        sequence = "/".join(seq_parts) if seq_parts else "gemischt"

        # letzten sinnvollen Impuls bestimmen: meist letzter Low->High oder High->Low
        swing_low = last_low["price"] if last_low else float(low.tail(60).min())
        swing_high = last_high["price"] if last_high else float(high.tail(60).max())
        if last_low and last_high and last_low["idx"] > last_high["idx"] and prev_low and last_high:
            impulse_low = prev_low["price"]
            impulse_high = last_high["price"]
        else:
            impulse_low = swing_low
            impulse_high = swing_high
        impulse = max(impulse_high - impulse_low, 1e-9)
        pullback_pct = ((impulse_high - price) / impulse) * 100.0 if impulse_high >= price and impulse > 0 else 0.0
        extension_127 = impulse_high + impulse * 0.272
        extension_162 = impulse_high + impulse * 0.618

        quality = 45.0
        drivers = []
        if hh and hl:
            quality += 22; drivers.append("HH/HL-Sequenz intakt")
        elif hl and not ll:
            quality += 12; drivers.append("Higher Low sichtbar")
        if lh or ll:
            quality -= 18; drivers.append("LH/LL bremst Struktur")
        if pd.notna(ma20) and price >= ma20:
            quality += 8; drivers.append("ueber MA20")
        elif pd.notna(ma20):
            quality -= 8; drivers.append("unter MA20")
        if pd.notna(ma50) and price >= ma50:
            quality += 7; drivers.append("ueber MA50")
        elif pd.notna(ma50):
            quality -= 10; drivers.append("unter MA50")
        if 30 <= pullback_pct <= 68 and (hl or price >= swing_low):
            quality += 12; drivers.append(f"Pullback-Tiefe konstruktiv ({pullback_pct:.0f}%)")
        elif pullback_pct > 78:
            quality -= 14; drivers.append(f"tiefer Pullback ({pullback_pct:.0f}%)")
        elif pullback_pct < 15 and price >= impulse_high * 0.98:
            quality += 4; drivers.append("nahe Impulshoch")
        quality = max(0, min(100, quality))

        if hh and hl and 25 <= pullback_pct <= 68:
            phase = "Moegliche Welle-2-/Pullback-Zone vor Fortsetzung"
            label = "welle-2-pullback"
            summary = "Swing-Struktur zeigt HH/HL und einen geordneten Ruecklauf. Das ist ein moeglicher frueher Fortsetzungsbereich, aber erst Reclaim/Volumen bestaetigt den Einstieg."
            action = "Reclaim ueber kurzfristigen Pivot abwarten; Invalidierung unter letztem Higher Low."
        elif hh and hl and price >= impulse_high * 0.98:
            phase = "Moegliche fruehe Impulsfortsetzung / Welle 3"
            label = "impulsfortsetzung"
            summary = "HH/HL-Sequenz ist intakt und der Kurs arbeitet am Impulshoch. Das spricht fuer eine moegliche Fortsetzung, solange kein Rueckfall unter das letzte Higher Low folgt."
            action = "Bei Ausbruch/Reclaim mit Volumen aktiv pruefen; nicht hinterherlaufen, wenn Abstand zur Entry-Zone zu gross wird."
        elif hl and not hh:
            phase = "Fruehe Boden-/Reclaim-Struktur"
            label = "frueher-reclaim"
            summary = "Ein Higher Low ist erkennbar, aber ein neues Higher High fehlt noch. Das ist Watchlist-/Trigger-Naehe, kein voll bestaetigter Impuls."
            action = "Bullisher erst ueber dem letzten Swing High; Bruch des Higher Low invalidiert die Struktur."
        elif lh and ll:
            phase = "Abwaertsstruktur / gebrochene Wellenfolge"
            label = "abwaertsstruktur"
            summary = "LH/LL-Sequenz spricht gegen eine aktive Long-Wellenstruktur. Erst Reclaim und neue HH/HL-Folge verbessern die Lage."
            action = "Kein aggressiver Einstieg; Reversal-/Reclaim-Struktur abwarten."
        else:
            phase = "Gemischte Swing-Struktur"
            label = "gemischt"
            summary = "Die Swing-Folge ist nicht eindeutig. Fibonacci, Entry-Zone, Volumen und klassische Trigger bleiben primaer."
            action = "Nicht aus der Wellenstruktur handeln; klare Trigger abwarten."

        trigger_price = None
        if last_high and price <= last_high["price"]:
            trigger_price = last_high["price"]
            trigger = f"Reclaim/Ausbruch ueber letztes Swing High {_wave_v190_fmt_num(trigger_price)}"
        elif last_high:
            trigger_price = max(float(high.tail(5).max()), price)
            trigger = f"Folgestaerke ueber kurzfristigem Hoch {_wave_v190_fmt_num(trigger_price)}"
        else:
            trigger = base.get("confirmation_text", "Klassischen Trigger nutzen")
        invalid_price = last_low["price"] if last_low else (ma20 if pd.notna(ma20) else np.nan)
        invalidation = f"Bruch unter letztes Swing Low/Higher Low {_wave_v190_fmt_num(invalid_price)}" if pd.notna(invalid_price) else "n/a"
        target_zone = f"1.272-1.618 Extension ca. {_wave_v190_fmt_num(extension_127)} - {_wave_v190_fmt_num(extension_162)}" if impulse_high > impulse_low else "n/a"
        quality_label = "hoch" if quality >= 75 else "gut" if quality >= 62 else "mittel" if quality >= 48 else "schwach"

        zones = list(base.get("zones") or [])
        zones.extend([
            {"Punkt": "Letztes Swing High", "Zone/Wert": _wave_v190_fmt_num(last_high["price"] if last_high else None), "Lesart": "Reclaim/Ausbruch darueber verbessert die Wellenstruktur."},
            {"Punkt": "Letztes Swing Low", "Zone/Wert": _wave_v190_fmt_num(last_low["price"] if last_low else None), "Lesart": "Darunter ist die aktuelle Long-Struktur invalidiert."},
            {"Punkt": "Wellen-Zielzone", "Zone/Wert": target_zone, "Lesart": "Orientierungszone aus Extension, nur mit aktivem Trigger relevant."},
        ])
        base.update({
            "label": label,
            "phase": phase,
            "summary": summary,
            "action_hint": action,
            "score": int(round(quality)),
            "drivers": (drivers + list(base.get("drivers") or []))[:6],
            "zones": zones,
            "plain_hint": f"{sequence}: {summary}",
            "wave_phase": phase,
            "wave_label": label,
            "wave_sequence": sequence,
            "wave_quality_score": int(round(quality)),
            "wave_quality_label": quality_label,
            "wave_pullback_depth_pct": round(float(pullback_pct), 1),
            "wave_trigger": trigger,
            "wave_trigger_price": round(float(trigger_price), 2) if trigger_price is not None and pd.notna(trigger_price) else "n/a",
            "wave_invalidation": invalidation,
            "wave_invalidation_price": round(float(invalid_price), 2) if pd.notna(invalid_price) else "n/a",
            "wave_target_zone": target_zone,
            "wave_extension_127": round(float(extension_127), 2),
            "wave_extension_162": round(float(extension_162), 2),
            "swing_points": swings,
            "is_score_relevant": True,
        })
        # Bestaetigung auf den konkreten Wellentrigger umbiegen, ohne alte Kerzenlogik zu verlieren.
        old_conf_score = int(base.get("confirmation_score") or 0)
        if trigger_price is not None and pd.notna(trigger_price) and price >= trigger_price:
            wave_conf_score = max(old_conf_score, 72)
            wave_conf_label = "Wellentrigger bestaetigt"
            wave_conf_text = f"{trigger}; Kurs handelt darueber. {', '.join(drivers[:3])}."
            wave_conf_action = "Aktiv pruefen, sofern Entry/CRV und Volumen passen."
        elif quality >= 62 and label in {"welle-2-pullback", "frueher-reclaim"}:
            wave_conf_score = max(old_conf_score, 52)
            wave_conf_label = "Wellentrigger unter Beobachtung"
            wave_conf_text = f"{trigger}; Strukturqualitaet {quality_label}, aber Trigger noch nicht voll aktiv."
            wave_conf_action = "Vorbereiten; erst bei Reclaim/Ausbruch und passendem CRV handeln."
        else:
            wave_conf_score = min(max(old_conf_score, int(round(quality * 0.6))), 55)
            wave_conf_label = base.get("confirmation_label", "unter Beobachtung")
            wave_conf_text = f"{trigger}; {summary}"
            wave_conf_action = action
        base["confirmation_label"] = wave_conf_label
        base["confirmation_score"] = int(max(0, min(100, wave_conf_score)))
        base["confirmation_text"] = wave_conf_text
        base["confirmation_action"] = wave_conf_action
        base["confirmation_drivers"] = drivers[:5]
        base.update(_wave_v191_build_readable_fields(base))
        return base
    except Exception as exc:
        base["summary"] = f"Wellenanalyse v21.1 nicht belastbar: {exc}"
        base["action_hint"] = "Nicht als eigenstaendiges Signal verwenden."
        return base


def build_fibonacci_context_v1533(chart_df=None, result=None):
    """Weicher Fibonacci-Kontext fuer Pullback-/Zielzonen.

    Keine harte Kauf-/Verkaufslogik: Fibonacci-Level sind moegliche Zonen, an
    denen Marktteilnehmer reagieren koennen. Sie bestaetigen nur dann etwas,
    wenn Preisreaktion, Volumen, Trend und Support/Resistance dazu passen.
    """
    result = result or {}
    out = {
        "label": "n/a",
        "phase": "Nicht belastbar",
        "summary": "Keine belastbare Fibonacci-Zone ableitbar.",
        "action_hint": "Nicht als eigenständiges Signal verwenden.",
        "active_zone_text": "n/a",
        "swing_low": "n/a",
        "swing_high": "n/a",
        "levels": [],
        "extensions": [],
        "drivers": [],
        "zones": [],
        "plain_hint": "Dieser Kontext beschreibt nur die Struktur des letzten Moves. Er ist kein eigenständiges Kauf-/Verkaufssignal.",
        "confirmation_label": "nicht geprüft",
        "confirmation_score": 0,
        "confirmation_text": "Noch keine automatische Bestätigungsprüfung verfügbar.",
        "confirmation_action": "Bei Annäherung an ein Fibonacci-Level erneut auf Kursreaktion, Kerze, Volumen und kurzfristiges Timing prüfen.",
        "confirmation_drivers": [],
        "is_score_relevant": False,
    }
    try:
        if chart_df is None or getattr(chart_df, "empty", True):
            return out
        dff = chart_df.copy()
        close_col = "Close" if "Close" in dff.columns else "Adj Close" if "Adj Close" in dff.columns else None
        high_col = "High" if "High" in dff.columns else close_col
        low_col = "Low" if "Low" in dff.columns else close_col
        if close_col is None or high_col is None or low_col is None:
            return out
        close = pd.to_numeric(dff[close_col], errors="coerce").dropna()
        highs = pd.to_numeric(dff[high_col], errors="coerce").dropna()
        lows = pd.to_numeric(dff[low_col], errors="coerce").dropna()
        if len(close) < 50 or len(highs) < 50 or len(lows) < 50:
            return out
        lookback = min(160, len(close))
        hh_window = highs.tail(lookback)
        ll_window = lows.tail(lookback)
        swing_high = float(hh_window.max())
        swing_low = float(ll_window.min())
        price = float(close.iloc[-1])
        ma10 = float(close.rolling(10).mean().iloc[-1]) if len(close) >= 10 else np.nan
        ma20 = float(close.rolling(20).mean().iloc[-1]) if len(close) >= 20 else np.nan
        ma50 = float(close.rolling(50).mean().iloc[-1]) if len(close) >= 50 else np.nan
        dist_ma10 = ((price / ma10) - 1.0) * 100.0 if pd.notna(ma10) and ma10 else np.nan
        dist_ma20 = ((price / ma20) - 1.0) * 100.0 if pd.notna(ma20) and ma20 else np.nan
        vol_ratio = np.nan
        try:
            if "Volume" in dff.columns:
                vol_s = pd.to_numeric(dff["Volume"], errors="coerce").dropna()
                if len(vol_s) >= 21 and float(vol_s.tail(20).mean()) > 0:
                    vol_ratio = float(vol_s.iloc[-1]) / float(vol_s.tail(20).mean())
        except Exception:
            vol_ratio = np.nan
        last_open = np.nan
        last_high = np.nan
        last_low = np.nan
        prev_high = np.nan
        prev_close = np.nan
        try:
            open_col = "Open" if "Open" in dff.columns else close_col
            open_s = pd.to_numeric(dff[open_col], errors="coerce").dropna()
            last_open = float(open_s.iloc[-1]) if len(open_s) else np.nan
            last_high = float(highs.iloc[-1]) if len(highs) else np.nan
            last_low = float(lows.iloc[-1]) if len(lows) else np.nan
            prev_high = float(highs.iloc[-2]) if len(highs) >= 2 else np.nan
            prev_close = float(close.iloc[-2]) if len(close) >= 2 else np.nan
        except Exception:
            pass
        if not np.isfinite(swing_high) or not np.isfinite(swing_low) or swing_high <= swing_low or price <= 0:
            return out
        swing_range = swing_high - swing_low
        # Retracements in einem Aufwaerts-Swing: Level unterhalb des Swing-Hochs.
        fib_defs = [(23.6, 0.236), (38.2, 0.382), (50.0, 0.500), (61.8, 0.618), (78.6, 0.786)]
        levels = []
        for pct, ratio in fib_defs:
            lvl = swing_high - swing_range * ratio
            dist_pct = ((price / lvl) - 1.0) * 100.0 if lvl else np.nan
            if pd.notna(dist_pct):
                if abs(float(dist_pct)) <= 1.0:
                    lage = "am Kurs"
                    lesart = "Kurs liegt direkt an dieser Fibonacci-Zone; relevant ist die Reaktion/Stabilisierung, nicht das Level allein."
                elif float(dist_pct) > 0:
                    lage = "unter Kurs"
                    lesart = "Liegt unter dem aktuellen Kurs: mögliche Pullback-/Unterstützungszone, falls der Kurs dorthin zurücksetzt."
                else:
                    lage = "über Kurs"
                    lesart = "Liegt über dem aktuellen Kurs: eher Reclaim-/Widerstandszone; erst ein Rücklauf über dieses Level wäre konstruktiver."
            else:
                lage = "n/a"
                lesart = "Nicht belastbar interpretierbar."
            levels.append({
                "Level": f"{pct:.1f}%",
                "Kurszone": round(lvl, 2),
                "Abstand_%": round(float(dist_pct), 1) if pd.notna(dist_pct) else "n/a",
                "Lage": lage,
                "Lesart": lesart,
            })
        ext_defs = [(127.2, 1.272), (161.8, 1.618)]
        extensions = []
        for pct, ratio in ext_defs:
            lvl = swing_low + swing_range * ratio
            dist_pct = ((price / lvl) - 1.0) * 100.0 if lvl else np.nan
            extensions.append({"Extension": f"{pct:.1f}%", "Kurszone": round(lvl, 2), "Abstand_%": round(float(dist_pct), 1) if pd.notna(dist_pct) else "n/a"})

        nearest = min(levels, key=lambda x: abs(float(x.get("Abstand_%", 999) if x.get("Abstand_%") != "n/a" else 999)))
        nearest_level = nearest.get("Level", "n/a")
        nearest_price = nearest.get("Kurszone", "n/a")
        nearest_dist = nearest.get("Abstand_%", "n/a")
        nearest_lage = nearest.get("Lage", "n/a")

        # v15.36.1: automatische Fib-Bestaetigungspruefung.
        # Fibonacci bleibt weicher Kontext, aber die App bewertet, ob an der Zone
        # bereits eine sichtbare Reaktion entsteht oder ob nur Beobachten sinnvoll ist.
        confirm_score = 0.0
        confirm_drivers = []
        try:
            nd = float(nearest_dist) if nearest_dist != "n/a" else np.nan
        except Exception:
            nd = np.nan
        near_zone = pd.notna(nd) and abs(nd) <= 1.25
        slightly_near_zone = pd.notna(nd) and abs(nd) <= 2.5
        bullish_candle = pd.notna(last_open) and pd.notna(price) and price > last_open
        bearish_candle = pd.notna(last_open) and pd.notna(price) and price < last_open
        closes_above_prev = pd.notna(prev_high) and price > prev_high
        recovered_prev_close = pd.notna(prev_close) and price > prev_close
        long_lower_wick = False
        try:
            rng = max(float(last_high) - float(last_low), 1e-9)
            lower_wick = min(float(price), float(last_open)) - float(last_low)
            long_lower_wick = (lower_wick / rng) >= 0.35
        except Exception:
            long_lower_wick = False
        above_ma10 = pd.notna(ma10) and price >= ma10
        above_ma20 = pd.notna(ma20) and price >= ma20
        vol_confirm = pd.notna(vol_ratio) and vol_ratio >= 1.05
        vol_strong = pd.notna(vol_ratio) and vol_ratio >= 1.25
        if near_zone:
            confirm_score += 24
            confirm_drivers.append(f"Kurs direkt an Fib-Zone {nearest_level} ({_v1533_1_fmt_price(nearest_price)})")
        elif slightly_near_zone:
            confirm_score += 12
            confirm_drivers.append(f"Kurs nahe Fib-Zone {nearest_level} ({_v1533_1_fmt_price(nearest_price)})")
        if bullish_candle:
            confirm_score += 14
            confirm_drivers.append("bullische Tageskerze/Reaktion")
        if long_lower_wick:
            confirm_score += 12
            confirm_drivers.append("unterer Docht zeigt Kaufreaktion")
        if closes_above_prev:
            confirm_score += 18
            confirm_drivers.append("Bruch ueber Vortageshoch")
        elif recovered_prev_close:
            confirm_score += 8
            confirm_drivers.append("Schluss ueber Vortag")
        if above_ma10:
            confirm_score += 10
            confirm_drivers.append(f"Kurs ueber/auf MA10 ({_v1533_1_fmt_price(ma10)})")
        elif pd.notna(ma10):
            confirm_drivers.append(f"noch unter MA10 ({_v1533_1_fmt_price(ma10)})")
        if above_ma20:
            confirm_score += 6
        if vol_strong:
            confirm_score += 14
            confirm_drivers.append(f"Volumen bestaetigt deutlich ({vol_ratio:.2f}x 20T)")
        elif vol_confirm:
            confirm_score += 7
            confirm_drivers.append(f"Volumen bestaetigt leicht ({vol_ratio:.2f}x 20T)")
        elif pd.notna(vol_ratio):
            confirm_drivers.append(f"Volumen noch ohne klare Bestaetigung ({vol_ratio:.2f}x 20T)")
        if bearish_candle and near_zone:
            confirm_score -= 12
            confirm_drivers.append("bearische Kerze an der Zone bremst")
        confirm_score = int(max(0, min(100, round(confirm_score))))
        if not near_zone and not slightly_near_zone:
            confirmation_label = "nur beobachten"
            confirmation_text = f"Kurs ist nicht direkt an der naechsten Fibonacci-Zone {nearest_level} bei {_v1533_1_fmt_price(nearest_price)}. Keine automatische Fib-Bestaetigung."
            confirmation_action = "Nicht aus Fibonacci handeln. Erst bei Annaeherung an die Zone erneut analysieren oder auf andere aktive Trigger achten."
        elif confirm_score >= 70:
            confirmation_label = "bestaetigt"
            confirmation_text = f"Fib-Zone {nearest_level} bei {_v1533_1_fmt_price(nearest_price)} wird aktuell durch Kursreaktion und Zusatzsignale bestaetigt."
            confirmation_action = "Einstieg kann aktiv geprueft werden, sofern Aktion/Signal-Konflikt/Risiko nicht dagegen sprechen. Invalidierung bleibt der Bruch der Zone bzw. naechsten Supportzone."
        elif confirm_score >= 45:
            confirmation_label = "erste Bestaetigung"
            confirmation_text = f"Fib-Zone {nearest_level} bei {_v1533_1_fmt_price(nearest_price)} zeigt erste Reaktion, aber noch keine starke Bestaetigung."
            confirmation_action = "Vorbereiten: weitere Bestaetigung abwarten, z. B. Stabilisierung, Bruch ueber kurzfristiges Hoch oder Volumenbestaetigung."
        elif confirm_score >= 25:
            confirmation_label = "Reaktion unvollstaendig"
            confirmation_text = f"Kurs ist an/nahe Fib-Zone {nearest_level} bei {_v1533_1_fmt_price(nearest_price)}, aber die Bestaetigung ist noch schwach."
            confirmation_action = "Noch nicht blind handeln. Erneut pruefen, wenn Kerze, MA10/MA20 oder Volumen klarer werden."
        else:
            confirmation_label = "keine Bestaetigung"
            confirmation_text = f"Kurs ist zwar an/nahe Fib-Zone {nearest_level} bei {_v1533_1_fmt_price(nearest_price)}, aber es fehlt eine belastbare positive Reaktion."
            confirmation_action = "Abwarten. Bei Bruch der Zone eher tiefere Fib-/Supportzone beobachten."

        def _fib_zone_phrase(level_name, level_price, lage):
            if lage == "über Kurs":
                return f"naechste Reclaim-/Widerstandszone: {level_name} bei {level_price}"
            if lage == "unter Kurs":
                return f"naechste Pullback-/Unterstuetzungszone: {level_name} bei {level_price}"
            if lage == "am Kurs":
                return f"Kurs direkt an Fibonacci-Zone: {level_name} bei {level_price}"
            return f"naechstes Fibonacci-Level: {level_name} bei {level_price}"
        pullback_from_high = ((swing_high - price) / swing_high) * 100.0 if swing_high else np.nan
        position_in_swing = ((price - swing_low) / max(swing_range, 1e-9)) * 100.0
        drivers = []
        if pd.notna(pullback_from_high):
            drivers.append(f"Rücklauf vom Swing-Hoch {pullback_from_high:.1f}%")
        drivers.append(f"Position im Swing {position_in_swing:.0f}%")
        drivers.append(f"nächstes Fib-Level {nearest_level} bei {nearest_price}")

        # Aktive Zone grob bestimmen.
        if price > swing_high:
            label = "Extension"
            phase = "Über dem letzten Swing-Hoch"
            active_zone = f"oberhalb Swing-Hoch {swing_high:.2f}; mögliche Extensions: {extensions[0]['Kurszone']} / {extensions[1]['Kurszone']}"
            summary = "Kurs liegt über dem letzten relevanten Swing-Hoch. Fibonacci dient hier eher als Ziel-/Überdehnungszone, nicht als Entry-Signal."
            action = f"Nicht blind hinterherlaufen. Re-Test des alten Swing-Hochs {swing_high:.2f} oder neue Base abwarten; Extensions {extensions[0]['Kurszone']} / {extensions[1]['Kurszone']} eher als Ziel-/Ueberdehnungszonen lesen."
        elif position_in_swing >= 85:
            label = "hoch im Swing"
            phase = "Nahe Swing-Hoch / eher spät im Move"
            active_zone = f"Swing-Hoch {swing_high:.2f}; nächster Pullback-Kontext: {levels[0]['Level']} bei {levels[0]['Kurszone']}"
            summary = "Kurs befindet sich weit oben im letzten Swing. Das ist bei starken Leadern nicht automatisch negativ, erhöht aber das Risiko eines späten Einstiegs."
            action = f"Ruecklaufbereiche bei {levels[0]['Kurszone']} und {levels[1]['Kurszone']} sind Beobachtungszonen, keine automatischen Kaufmarken. Bei Annaeherung erneut analysieren: Einstieg nur pruefen, wenn Kursreaktion, Candlestick, Volumen und kurzfristiges Timing bestaetigen."
        elif 70 <= position_in_swing < 85:
            label = "konstruktiv"
            phase = "Oberer Swing-Bereich"
            active_zone = f"nächstes relevantes Retracement: {nearest_level} bei {nearest_price}"
            summary = "Kurs hält sich im oberen Bereich des Swings. Fibonacci liefert eher Pullback-Orientierung als ein eigenständiges Kaufsignal."
            action = f"Bei Entry-Naehe Bestaetigung pruefen. Konstruktiver Pullback waere vor allem im Bereich 23,6-38,2% ({levels[0]['Kurszone']} bis {levels[1]['Kurszone']}); darunter auf 50/61,8% achten."
        elif 45 <= position_in_swing < 70:
            label = "Pullback-Zone"
            phase = "Mittlerer Retracement-Bereich"
            active_zone = _fib_zone_phrase(nearest_level, nearest_price, nearest_lage)
            if nearest_lage == "über Kurs":
                summary = "Kurs liegt unter dem naechsten Fibonacci-Level. Dieses Level ist aktuell keine Unterstuetzung, sondern eine Reclaim-/Widerstandszone."
                action = f"Bullisher erst bei Reclaim/Stabilisierung ueber {nearest_level} bei {nearest_price}. Defensiver bei weiterem Bruch Richtung 61,8%-Zone bei {levels[3]['Kurszone']}."
            elif nearest_lage == "unter Kurs":
                summary = "Kurs liegt im mittleren Swing-Bereich; die naechste Fibonacci-Zone darunter kann bei einem Ruecksetzer als moegliche Unterstuetzung relevant werden."
                action = f"Nicht automatisch kaufen. Bullisher erst bei Stabilisierung/Reaktion; naechste Pullback-Unterstuetzung: {nearest_level} bei {nearest_price}. Defensiver bei Bruch der 61,8%-Zone bei {levels[3]['Kurszone']}."
            else:
                summary = "Kurs liegt direkt an einer Fibonacci-Zone. Das kann eine gesunde Korrektur sein, braucht aber sichtbare Stabilisierung."
                action = f"Bullisher erst bei Reaktion/Stabilisierung an {nearest_level} bei {nearest_price}. Defensiver bei Bruch der 61,8%-Zone bei {levels[3]['Kurszone']}."
        else:
            label = "tief"
            phase = "Tiefe Korrektur / Struktur prüfen"
            active_zone = f"tiefer Bereich; 61,8% bei {levels[3]['Kurszone']} / 78,6% bei {levels[4]['Kurszone']}"
            summary = "Kurs liegt tief im letzten Swing. Das kann Chance oder Strukturbruch sein; Fibonacci allein reicht hier nicht."
            action = f"Erst Bodenbildung/Reclaim abwarten. Unter 78,6% bei {levels[4]['Kurszone']} wirkt der vorherige Swing zunehmend beschaedigt; Reclaim ueber 61,8% bei {levels[3]['Kurszone']} waere konstruktiver."

        # Konkrete Orientierungspunkte fuer die Anzeige. Keine harte Wellenzaehlung.
        support_txt = _v1533_1_support_zone_text(result, ma20 if pd.notna(ma20) else ma50)
        zones = [
            {"Punkt": "Aktueller Kurs", "Zone/Wert": _v1533_1_fmt_price(price), "Lesart": "Ausgangspunkt fuer die Strukturlesart."},
            {"Punkt": "MA10", "Zone/Wert": _v1533_1_fmt_price(ma10), "Lesart": "Kurzfristiger Trendtakt. Deutlich darueber = moeglich spaet/ueberdehnt; Reclaim/Halten = konstruktiv."},
            {"Punkt": "MA20", "Zone/Wert": _v1533_1_fmt_price(ma20), "Lesart": "Erste Pullback-/Stabilisierungszone im Trend."},
            {"Punkt": "MA50", "Zone/Wert": _v1533_1_fmt_price(ma50), "Lesart": "Mittelfristige Strukturzone. Bruch/Reclaim veraendert die Lage deutlich."},
            {"Punkt": "Naechste Invalidierung", "Zone/Wert": support_txt, "Lesart": "Darunter wird die Struktur defensiver; nicht als exakter Stop missverstehen."},
        ]
        if label == "fortgeschritten":
            plain_hint = f"Starker Move, aber der Kurs liegt weit ueber kurzfristigen Taktgebern. Konkreter: Kurs {_v1533_1_fmt_price(price)}, MA10 {_v1533_1_fmt_price(ma10)} ({_v1533_1_fmt_pct(dist_ma10)} Abstand). Nicht hinterherlaufen; Pullback in Richtung MA10/MA20 oder neue Base abwarten."
        elif label == "impulsiv":
            plain_hint = f"Trendstruktur ist konstruktiv, solange Kurs {_v1533_1_fmt_price(price)} die kurzfristigen Taktgeber/Trigger haelt. Relevante Orientierung: MA10 {_v1533_1_fmt_price(ma10)}, MA20 {_v1533_1_fmt_price(ma20)}."
        elif label == "korrektiv":
            plain_hint = f"Der Ruecklauf wirkt bisher geordnet. Bullisher erst bei Stabilisierung/Reclaim im Bereich MA10/MA20 ({_v1533_1_fmt_price(ma10)} / {_v1533_1_fmt_price(ma20)}); defensiver unter {support_txt}."
        elif label == "angeschlagen":
            plain_hint = f"Kurs liegt unter wichtiger Struktur. Erst Reclaim von MA50 ({_v1533_1_fmt_price(ma50)}) oder klare Bodenbildung wuerde die Lage verbessern."
        else:
            plain_hint = "Keine belastbare Strukturlesart. Nutze Entry-Zone, Support/Resistance und Bestaetigung als primaere Orientierung."

        if label == "Extension":
            fib_plain_hint = f"Kurs {_v1533_1_fmt_price(price)} liegt ueber dem letzten Swing-Hoch {_v1533_1_fmt_price(swing_high)}. Das ist Staerke, aber kein guenstiger Pullback. Naechste Orientierung: Extension {_v1533_1_fmt_price(extensions[0]['Kurszone'])} / {_v1533_1_fmt_price(extensions[1]['Kurszone'])}."
        elif label == "hoch im Swing":
            fib_plain_hint = f"Kurs {_v1533_1_fmt_price(price)} liegt hoch im Swing zwischen {_v1533_1_fmt_price(swing_low)} und {_v1533_1_fmt_price(swing_high)}. Pullback-Zonen zur Orientierung: 23,6% {_v1533_1_fmt_price(levels[0]['Kurszone'])}, 38,2% {_v1533_1_fmt_price(levels[1]['Kurszone'])}."
        elif label == "konstruktiv":
            fib_plain_hint = f"Kurs {_v1533_1_fmt_price(price)} haelt den oberen Swing-Bereich. Fibonacci hilft hier vor allem als Pullback-Landkarte: 23,6% {_v1533_1_fmt_price(levels[0]['Kurszone'])}, 38,2% {_v1533_1_fmt_price(levels[1]['Kurszone'])}."
        elif label == "Pullback-Zone":
            if nearest_lage == "über Kurs":
                fib_plain_hint = f"Kurs {_v1533_1_fmt_price(price)} liegt unter dem naechsten Fibonacci-Level {nearest_level} bei {_v1533_1_fmt_price(nearest_price)}. Dieses Level ist aktuell keine Unterstuetzung, sondern eine Reclaim-/Widerstandszone; bullisher wird es erst bei Rueckeroberung/Stabilisierung darueber."
            elif nearest_lage == "unter Kurs":
                fib_plain_hint = f"Kurs {_v1533_1_fmt_price(price)} liegt oberhalb des naechsten Fibonacci-Levels {nearest_level} bei {_v1533_1_fmt_price(nearest_price)}. Das Level waere bei einem Ruecksetzer eine moegliche Pullback-Unterstuetzung; wichtig waere dort eine sichtbare Reaktion."
            else:
                fib_plain_hint = f"Kurs {_v1533_1_fmt_price(price)} liegt direkt an der Fibonacci-Zone {nearest_level} bei {_v1533_1_fmt_price(nearest_price)}. Wichtig ist jetzt Stabilisierung/Reaktion dort, nicht das Level allein."
        else:
            fib_plain_hint = f"Kurs {_v1533_1_fmt_price(price)} liegt tief im Swing. Kritische Orientierung: 61,8% {_v1533_1_fmt_price(levels[3]['Kurszone'])}, 78,6% {_v1533_1_fmt_price(levels[4]['Kurszone'])}."

        out.update({
            "label": label,
            "phase": phase,
            "summary": summary,
            "action_hint": action,
            "active_zone_text": active_zone,
            "swing_low": round(swing_low, 2),
            "swing_high": round(swing_high, 2),
            "levels": levels,
            "extensions": extensions,
            "drivers": drivers[:5],
            "zones": zones,
            "plain_hint": fib_plain_hint,
            "confirmation_label": confirmation_label,
            "confirmation_score": confirm_score,
            "confirmation_text": confirmation_text,
            "confirmation_action": confirmation_action,
            "confirmation_drivers": confirm_drivers[:8],
            "confirmation_near_zone": bool(near_zone or slightly_near_zone),
            "metrics": {
                "Swing_Low": round(swing_low, 2),
                "Swing_High": round(swing_high, 2),
                "Pullback_vom_Swing_Hoch_%": round(float(pullback_from_high), 1) if pd.notna(pullback_from_high) else "n/a",
                "Position_im_Swing_%": round(float(position_in_swing), 1),
                "Naechstes_Level": nearest_level,
                "Naechste_Zone": nearest_price,
                "Abstand_zur_naechsten_Zone_%": nearest_dist,
            },
        })
        return out
    except Exception as exc:
        out["summary"] = f"Fibonacci-Kontext nicht belastbar: {exc}"
        return out



def _chart_label_xpos_v205(df, position="right"):
    """Verteilt dauerhafte Chart-Labels horizontal, damit rechts nicht alles kollidiert."""
    try:
        if df is None or df.empty:
            return None
        n = len(df.index)
        if n <= 1:
            return df.index[-1]
        pos = str(position or "right").lower()
        if pos in {"left", "links"}:
            return df.index[max(0, int(n * 0.05))]
        if pos in {"mid", "middle", "center", "zentrum"}:
            return df.index[min(n - 1, max(0, int(n * 0.55)))]
        if pos in {"right_inner", "innen_rechts"}:
            return df.index[min(n - 1, max(0, int(n * 0.86)))]
        return df.index[-1]
    except Exception:
        try:
            return df.index[-1]
        except Exception:
            return None




_CHART_LARGE_LABELS_V207 = False

def _chart_annotation_style_v206(kind="neutral"):
    """Einheitliche, kontrastreiche Chart-Badges fuer v21.1.

    v21.1: Labels koennen optional groesser dargestellt werden. Zusaetzlich
    bekommen alle Badge-Labels unsichtbare Hover-Punkte mit gut lesbaren
    Detail-Tooltips.
    """
    kind = str(kind or "neutral").lower()
    large = bool(globals().get("_CHART_LARGE_LABELS_V207", False))
    small_size = 10 if large else 8
    trend_size = 11 if large else 9
    price_size = 13 if large else 11
    pad_small = 4 if large else 2
    styles = {
        "fib": dict(font=dict(size=small_size, color="#111827"), bgcolor="rgba(255,255,255,0.90)", bordercolor="rgba(31,41,55,0.38)", borderwidth=1, borderpad=pad_small),
        "support": dict(font=dict(size=small_size, color="#052e16"), bgcolor="rgba(220,252,231,0.92)", bordercolor="rgba(22,163,74,0.42)", borderwidth=1, borderpad=pad_small),
        "resistance": dict(font=dict(size=small_size, color="#450a0a"), bgcolor="rgba(254,226,226,0.92)", bordercolor="rgba(220,38,38,0.42)", borderwidth=1, borderpad=pad_small),
        "active": dict(font=dict(size=small_size, color="#082f49"), bgcolor="rgba(224,242,254,0.92)", bordercolor="rgba(14,165,233,0.42)", borderwidth=1, borderpad=pad_small),
        "trend": dict(font=dict(size=trend_size, color="#111827"), bgcolor="rgba(255,255,255,0.88)", bordercolor="rgba(59,130,246,0.35)", borderwidth=1, borderpad=4 if large else 3),
        "price": dict(font=dict(size=price_size, color="white"), bgcolor="rgba(2,132,199,0.94)", bordercolor="rgba(226,232,240,0.90)", borderwidth=1, borderpad=5 if large else 4),
    }
    return styles.get(kind, dict(font=dict(size=small_size, color="#111827"), bgcolor="rgba(255,255,255,0.88)", bordercolor="rgba(31,41,55,0.30)", borderwidth=1, borderpad=pad_small))

def _chart_hover_text_v207(text, kind="neutral"):
    try:
        clean = str(text or "").replace("<br>", " ").strip()
        title = str(kind or "Info").replace("_", " ").title()
        return f"<b>{clean}</b><br>{title}<extra></extra>"
    except Exception:
        return str(text or "") + "<extra></extra>"

def _chart_add_hover_point_v207(fig, *, x, y, text, kind="neutral", row=1, col=1):
    """Unsichtbarer Hover-Trefferpunkt fuer Annotationen.

    Plotly-Annotationen selbst besitzen keinen verlaesslichen Hover-/Mouseover-
    Stil. Dieser sehr transparente Marker erzeugt einen gut lesbaren Tooltip,
    ohne den Chart sichtbar zu ueberladen.
    """
    try:
        if x is None or y is None:
            return
        fig.add_trace(
            go.Scatter(
                x=[x],
                y=[float(y)],
                mode="markers",
                name=str(text or "Info"),
                marker=dict(size=22 if bool(globals().get("_CHART_LARGE_LABELS_V207", False)) else 18, color="rgba(15,23,42,0.01)", line=dict(width=0)),
                hovertemplate=_chart_hover_text_v207(text, kind),
                showlegend=False,
            ),
            row=row,
            col=col,
        )
    except Exception:
        pass


def _chart_label_yshift_v206(index, total=1, amplitude=13):
    """Kleine Pixel-Staffelung gegen Label-Ueberlagerungen.

    Plotly-Annotationen bleiben am korrekten Preis verankert, werden aber
    optisch leicht versetzt. Dadurch kollidieren nahe Fib-/S/R-Labels nicht
    mehr direkt miteinander.
    """
    try:
        i = int(index)
        total = max(1, int(total or 1))
        if total <= 1:
            return 0
        pattern = [0, 12, -12, 24, -24, 36, -36]
        return pattern[i % len(pattern)]
    except Exception:
        return 0


def _chart_add_annotation_v206(fig, *, x, y, text, kind="neutral", xanchor="left", yanchor="middle", yshift=0, row=1, col=1):
    """Robuste Chart-Beschriftung mit einheitlichem Kontrast."""
    try:
        style = _chart_annotation_style_v206(kind)
        fig.add_annotation(
            x=x,
            y=y,
            text=str(text or ""),
            showarrow=False,
            xanchor=xanchor,
            yanchor=yanchor,
            align="left",
            yshift=yshift,
            row=row,
            col=col,
            **style,
        )
        # v21.1: Mouseover ueber dem Label zeigt groesseren Detail-Tooltip.
        _chart_add_hover_point_v207(fig, x=x, y=y, text=text, kind=kind, row=row, col=col)
    except Exception:
        pass

def _chart_zone_compact_label_v205(prefix, idx, z, ccy=""):
    """Kompaktes Zonenlabel fuer den Chart; Details bleiben im Hover/unterhalb des Charts."""
    try:
        lo = float(z.get("low"))
        hi = float(z.get("high"))
        touches = int(z.get("touches", 0) or 0)
        cur = f" {ccy}" if str(ccy or "").strip() else ""
        touch_txt = f" · {touches}x" if touches else ""
        if abs(hi - lo) <= max(abs(hi), 1.0) * 0.002:
            return f"{prefix}{idx} {hi:.2f}{cur}{touch_txt}"
        return f"{prefix}{idx} {lo:.2f}-{hi:.2f}{cur}{touch_txt}"
    except Exception:
        return format_chart_zone_label(prefix, idx, z, ccy=ccy)

def add_fibonacci_levels_to_plotly_v1533(fig, chart_df, fib_pkg, show_labels=True):
    """Optionale Fibonacci-Linien im Chart. In kompakten Ansichten ohne rechte Dauerlabels."""
    try:
        if not isinstance(fib_pkg, dict):
            return fig
        levels = fib_pkg.get("levels") or []
        if not levels:
            return fig

        def _fmt_fib_price_v1535_1(value):
            try:
                v = float(value)
                if not pd.notna(v):
                    return "n/a"
                if abs(v) >= 100:
                    return f"{v:,.2f}"
                if abs(v) >= 10:
                    return f"{v:,.2f}"
                if abs(v) >= 1:
                    return f"{v:,.2f}"
                return f"{v:,.4f}"
            except Exception:
                return str(value or "n/a")

        # Plotlys add_hline annotation can truncate labels in some Streamlit/browser
        # combinations. Therefore we draw the line and the label separately.
        try:
            x0 = chart_df.index[0]
            x1 = chart_df.index[-1]
        except Exception:
            x0 = None
            x1 = None

        _fib_items = sorted(levels, key=lambda it: float(it.get("Kurszone") or 0), reverse=True)
        for _fib_idx, item in enumerate(_fib_items):
            y = item.get("Kurszone")
            name = str(item.get("Level") or "").strip()
            if y is None or str(y).strip().lower() in {"", "n/a", "nan", "none"}:
                continue
            y_float = float(y)
            price_txt = _fmt_fib_price_v1535_1(y_float)
            label = f"Fib {name} · {price_txt}" if name else f"Fib · {price_txt}"

            if x0 is not None and x1 is not None:
                fig.add_shape(
                    type="line",
                    x0=x0,
                    x1=x1,
                    y0=y_float,
                    y1=y_float,
                    xref="x",
                    yref="y",
                    line=dict(width=1, dash="dot", color="rgba(220,220,220,0.55)"),
                    row=1,
                    col=1,
                )
                if show_labels:
                    _chart_add_annotation_v206(
                        fig,
                        x=_chart_label_xpos_v205(chart_df, "left") or x0,
                        y=y_float,
                        text=label,
                        kind="fib",
                        xanchor="left",
                        yanchor="middle",
                        yshift=_chart_label_yshift_v206(_fib_idx, len(_fib_items)),
                        row=1,
                        col=1,
                    )
            else:
                fig.add_hline(
                    y=y_float,
                    line_width=1,
                    line_dash="dot",
                    opacity=0.45,
                    row=1,
                    col=1,
                )
        return fig
    except Exception:
        return fig

def align_action_with_trigger_v1520_2(action_label, action_reason, next_trigger, trigger_status, entry_quality, position_mode=False):
    """Keep the action label consistent with the operative trigger text.

    In Pre-Entry mode, "kaufen" should only appear when the entry is active/now
    (for example: trigger active, now checkable, good entry zone). If the next trigger
    says to wait for a pullback/confirmation/better environment, the correct action is
    "vorbereiten" or "abwarten".
    """
    action = str(action_label or "-").strip().lower()
    reason = str(action_reason or "").strip() or "Die Aktion folgt Timing, Risiko und Triggerstatus."
    nt = str(next_trigger or "").strip().lower()
    ts = str(trigger_status or "").strip().lower()
    eq = str(entry_quality or "").strip().lower()

    if position_mode or action != "kaufen":
        return action_label, reason

    wait_words = (
        "abwarten", "warten", "rücksetzer", "ruecksetzer", "confirmation",
        "bestätigung", "bestaetigung", "besseres marktumfeld", "neu prüfen",
        "neu pruefen", "verbessern", "klareres setup", "neues setup"
    )
    active_words = ("jetzt", "aktiv", "prüfbar", "pruefbar", "in entry-zone", "entry-zone")

    says_wait = any(w in nt for w in wait_words)
    says_active = any(w in nt for w in active_words) or ts == "aktiv" or eq == "gut"

    if says_wait and not says_active:
        if ts in {"passiv", "warten"}:
            return "abwarten", "Kein Sofortkauf: Der operative Trigger verlangt noch Geduld."
        return "vorbereiten", "Noch kein Sofortkauf: Der nächste Schritt ist ein Trigger/Entry-Zone abzuwarten."

    if not says_active and ts not in {"aktiv"} and eq != "gut":
        return "vorbereiten", "Kaufen wird erst freigegeben, wenn der Einstiegstrigger wirklich aktiv ist."

    return action_label, reason


def _parse_entry_zone_bounds_v1524_12(entry_zone):
    """Parse simple price ranges like '420.62 - 424.84 USD' safely."""
    import re
    txt = str(entry_zone or "").replace(",", ".")
    nums = [float(x) for x in re.findall(r"[-+]?\d+(?:\.\d+)?", txt)]
    if len(nums) >= 2:
        low, high = min(nums[0], nums[1]), max(nums[0], nums[1])
        return low, high
    return None, None


def _entry_zone_position_text_v1524_12(entry_zone="-", current_price=None):
    """Return a short explanation of where the current price sits vs. the entry zone.

    v15.26.2.2: Mit Toleranzband. Ein Kurs knapp unter/über der Zone soll
    nicht mehr wie ein weit entfernter Rücklauf wirken. Bei ca. 1.5% Abstand
    zur Zonenkante gilt die Zone als praktisch erreicht und die UI fragt nach
    Bestätigung/Reclaim statt nach einem generischen Rücklauf.
    """
    low, high = _parse_entry_zone_bounds_v1524_12(entry_zone)
    try:
        price = float(current_price)
    except Exception:
        price = float("nan")
    if low is None or high is None or pd.isna(price):
        return "", False, False, False
    base = max(abs(price), abs(low), abs(high), 1e-9)
    below_dist_pct = ((low - price) / base) * 100.0 if price < low else 0.0
    above_dist_pct = ((price - high) / base) * 100.0 if price > high else 0.0
    near_tol_pct = 1.5
    if low <= price <= high:
        return "Kurs liegt bereits in der Entry-Zone", True, False, False
    if price < low:
        if below_dist_pct <= near_tol_pct:
            return f"Kurs liegt knapp unter der Entry-Zone ({below_dist_pct:.1f}% unter Unterkante)", False, True, False
        return f"Kurs liegt noch unter der Entry-Zone ({below_dist_pct:.1f}% unter Unterkante)", False, True, False
    if above_dist_pct <= near_tol_pct:
        return f"Kurs liegt knapp über der Entry-Zone ({above_dist_pct:.1f}% über Oberkante)", False, False, True
    return f"Kurs liegt oberhalb der Entry-Zone ({above_dist_pct:.1f}% über Oberkante)", False, False, True




def _fmt_zone_range_v1525_9(zone, ccy=""):
    """Formatiert eine S/R-Zone lesbar für Triggertexte."""
    try:
        low = float(zone.get("low", np.nan))
        high = float(zone.get("high", np.nan))
        mid = float(zone.get("mid", np.nan))
    except Exception:
        return ""
    if pd.isna(low) or pd.isna(high):
        return ""
    suffix = f" {ccy}" if str(ccy or "").strip() else ""
    if abs(high - low) / max(abs(mid), 1e-9) < 0.002:
        return f"{mid:.2f}{suffix}"
    return f"{low:.2f} - {high:.2f}{suffix}"


def support_zone_text_v1525_9(structures=None, current_price=None, ccy="", fallback="Bruch der nächsten relevanten Support-Zone"):
    """Gibt für UI-Trigger die konkrete naechste Supportzone aus.

    Ziel: Texte wie 'Bruch der naechsten relevanten Support-Zone' sollen nicht
    abstrakt bleiben. Wenn Chart-S/R-Zonen verfuegbar sind, wird S1 inkl. Zone
    ausgegeben; falls der Kurs bereits in einer aktiven Zone liegt, wird diese
    Zone als aktive Trigger-/Support-Zone verwendet.
    """
    try:
        structures = structures or {}
        active = structures.get("active_zones", []) or []
        supports = structures.get("supports", []) or []
        zone = None
        label = "Support-Zone"
        if active:
            zone = active[0]
            label = "aktive Trigger-/Support-Zone"
        elif supports:
            zone = supports[0]
            label = "Support S1"
        if zone:
            zone_txt = _fmt_zone_range_v1525_9(zone, ccy)
            if zone_txt:
                try:
                    mid = float(zone.get("mid", np.nan))
                    cp = float(current_price) if current_price is not None and not pd.isna(current_price) else np.nan
                    dist = abs((cp / mid) - 1.0) * 100.0 if pd.notna(cp) and pd.notna(mid) and mid else np.nan
                    dist_txt = f", Abstand {dist:.1f}%" if pd.notna(dist) else ""
                except Exception:
                    dist_txt = ""
                return f"Bruch der {label} bei {zone_txt}{dist_txt}"
    except Exception:
        pass
    return fallback


def explain_clearer_setup_trigger_v1525_9(entry_zone="-", current_price=None, structures=None, ccy=""):
    """Ersetzt generische Trigger wie 'Auf klareres Setup warten'."""
    zone_txt = str(entry_zone or "-").strip()
    has_entry = zone_txt not in {"", "-", "None", "nan"}
    if has_entry:
        pos_txt, in_zone, below_zone, above_zone = _entry_zone_position_text_v1524_12(zone_txt, current_price)
        if in_zone:
            return f"Noch kein bullisher Trigger: Entry-Zone {zone_txt} ist erreicht, aber es fehlt Bestätigung. Nötig ist Stabilisierung in der Zone, bullische Reaktion oder Bruch über ein kurzfristiges Hoch."
        if below_zone:
            if "knapp unter" in str(pos_txt).lower():
                return f"Noch kein bullisher Trigger: Entry-Zone {zone_txt} ist praktisch erreicht ({pos_txt}). Jetzt zählt Reclaim/Stabilisierung in der Zone oder eine bullische Reaktion - nicht bloß auf den Preisbereich warten."
            return f"Noch kein bullisher Trigger: Kurs liegt noch unter der Entry-Zone {zone_txt}. Erst Annäherung/Reclaim der Zone plus Bestätigung abwarten."
        if above_zone:
            if "knapp über" in str(pos_txt).lower():
                return f"Noch kein bullisher Trigger: Kurs liegt knapp über der Entry-Zone {zone_txt}. Nicht hinterherlaufen; Pullback in die Zone oder neue Bestätigung abwarten."
            return f"Noch kein bullisher Trigger: Kurs liegt über der Entry-Zone {zone_txt}; nicht hinterherlaufen, sondern Rücksetzer oder neue Base abwarten."
        return f"Noch kein bullisher Trigger: Entry-Zone {zone_txt} beobachten und erst bei klarer Bestätigung handeln."
    support_txt = support_zone_text_v1525_9(structures, current_price, ccy, fallback="")
    if support_txt:
        # Aus 'Bruch der Support-Zone bei X' eine positive Beobachtungszone ableiten.
        zone_part = support_txt.replace("Bruch der ", "").strip()
        return f"Noch kein bullisher Trigger: erst Stabilisierung an der {zone_part} oder Bruch über ein kurzfristiges Hoch abwarten."
    return "Noch kein bullisher Trigger: nötig ist ein klareres Setup, z. B. neue Base, Stabilisierung an Support oder Bruch über ein kurzfristiges Hoch."


def operational_trigger_text_v1523_12(next_trigger="-", trigger_status="-", trigger_reason="-", action_label="-", entry_quality="-", entry_zone="-", current_price=None, structures=None, ccy=""):
    """Uebersetzt technische Trigger-Statuslabels in handlungsnahe Sprache.

    Labels wie "Jetzt pruefbar" sind intern hilfreich, aber allein in der UI
    zu vage. Diese Funktion erzeugt deshalb immer eine konkrete Aussage: was
    pruefen, woran gueltig, oder worauf warten. Seit v15.24.13 wird zusätzlich
    geprüft, ob der aktuelle Kurs bereits in der Entry-Zone liegt.
    """
    nt = str(next_trigger or "").strip()
    ts = str(trigger_status or "").strip().lower()
    tr = str(trigger_reason or "").strip()
    action = str(action_label or "").strip().lower()
    entry = str(entry_quality or "").strip().lower()
    zone_txt = str(entry_zone or "-").strip()
    has_zone = zone_txt not in {"", "-", "None", "nan"}
    zone_pos_txt, in_zone, below_zone, above_zone = _entry_zone_position_text_v1524_12(zone_txt, current_price)
    low = nt.lower()

    empty_vals = {"", "-", "none", "nan", "nicht anwendbar"}

    if low in {"jetzt prüfbar", "jetzt pruefbar", "aktiv"} or ts == "aktiv":
        if action == "kaufen":
            if has_zone:
                if in_zone:
                    return f"Einstieg ist jetzt prüfbar; Entry-Zone: {zone_txt}. {zone_pos_txt}. Negativ wird es bei Bruch der Zone/Support-Bestätigung."
                if below_zone:
                    if "knapp unter" in str(zone_pos_txt).lower():
                        return f"Einstieg ist nah an der Entry-Zone prüfbar: {zone_txt}. {zone_pos_txt}. Positiv erst bei Reclaim/Stabilisierung in der Zone."
                    return f"Einstieg erst bei Annäherung/Reclaim der Entry-Zone prüfen: {zone_txt}. {zone_pos_txt}."
                if above_zone:
                    if "knapp über" in str(zone_pos_txt).lower():
                        return f"Einstieg nicht blind hinterherlaufen; Entry-Zone: {zone_txt}. {zone_pos_txt}. Pullback oder Bestätigung abwarten."
                    return f"Einstieg nicht hinterherlaufen; Entry-Zone: {zone_txt}. {zone_pos_txt}."
                return f"Einstieg ist jetzt prüfbar; Entry-Zone: {zone_txt}. Nur gültig, solange Kurs und Trigger-/Support-Zone halten."
            return "Einstieg ist jetzt prüfbar; nur gültig, solange Kurs und Trigger-/Support-Zone halten."
        if has_zone:
            if in_zone:
                return f"Entry-Zone {zone_txt} ist erreicht. Vorbereitung heißt jetzt: Bestätigung abwarten, z. B. Stabilisierung in der Zone, bullische Reaktion oder Bruch über ein kurzfristiges Hoch. Ungültig bei Bruch unter die Zone."
            if below_zone:
                if "knapp unter" in str(zone_pos_txt).lower():
                    return f"Entry-Zone {zone_txt} ist fast erreicht. {zone_pos_txt}. Jetzt nicht auf einen weiteren Rücklauf warten, sondern Reclaim/Stabilisierung in der Zone oder bullische Reaktion prüfen."
                return f"Entry-Zone {zone_txt} noch nicht erreicht. Annäherung/Reclaim plus Bestätigung abwarten."
            if above_zone:
                if "knapp über" in str(zone_pos_txt).lower():
                    return f"Kurs liegt knapp über der Entry-Zone {zone_txt}. Kein blinder Einstieg; Pullback in die Zone oder neue Bestätigung abwarten."
                return f"Kurs liegt über der Entry-Zone {zone_txt}. Kein Hinterherlaufen; Rücksetzer oder neuen Trigger abwarten."
            return f"Entry-Zone {zone_txt}: Einstieg erst bei klarer Bestätigung, nicht nur wegen Erreichen der Zone."
        return "Einstieg erst bei klarer Bestätigung; Zone/Support und Invalidierung prüfen."

    if low in empty_vals:
        if ts in {"nahe dran", "fast prüfbar", "fast pruefbar"}:
            if has_zone and zone_pos_txt:
                return f"Noch keinen Soforteinstieg erzwingen; Entry-Zone: {zone_txt}. {zone_pos_txt}."
            return f"Noch keinen Soforteinstieg erzwingen; auf Bestätigung oder Rücksetzer in die Entry-Zone: {zone_txt} warten." if has_zone else "Noch keinen Soforteinstieg erzwingen; auf Bestätigung oder Rücksetzer in die Entry-Zone warten."
        if ts in {"passiv", "warten"}:
            return "Noch kein aktiver Einstieg; erst bei klarerem Setup oder besserem Umfeld neu prüfen."
        return "Sauberen nächsten Bestätigungsschritt abwarten."

    # Generische interne Statuswerte in konkrete Handlungsbedingungen uebersetzen.
    if low in {"auf klareres setup warten", "auf neues setup warten", "trading-case verbessern", "setup-confirmation oder bessere entry-lage"}:
        return explain_clearer_setup_trigger_v1525_9(entry_zone, current_price, structures, ccy)

    # Wenn der Text schon konkret ist, nicht unnötig umformulieren.
    concrete_tokens = [
        "rücksetzer", "ruecksetzer", "entry-zone", "support", "widerstand",
        "zahlen", "marktumfeld", "confirmation", "bestätigung", "bestaetigung",
        "setup", "trigger", "prüfen", "pruefen", "warten", "zone"
    ]
    if any(tok in low for tok in concrete_tokens):
        if has_zone and zone_pos_txt and ("entry-zone" in low or "zone" in low):
            return f"{nt}. {zone_pos_txt}."
        return nt

    if tr and tr.lower() not in empty_vals:
        return tr
    return nt



def sanitize_operational_bearish_trigger_v1523_13(value="-", fallback="Bruch der nächsten relevanten Support-Zone", structures=None, current_price=None, ccy=""):
    """Nur operative/charttechnische Kipp-Punkte als bearishen Trigger anzeigen.

    Fundamentale Diagnosehinweise wie negatives Gewinnwachstum sind Bremsfaktoren,
    aber kein konkreter Trading-Trigger. Solche Texte werden deshalb aus
    'Bearisher bei' / 'Kippt bei' entfernt und durch eine technische Invalidation ersetzt.
    """
    txt = str(value or "").strip()
    empty_vals = {"", "-", "none", "nan", "nicht anwendbar", "None"}
    if txt in empty_vals or txt.lower() in empty_vals:
        return fallback

    low = txt.lower()
    concrete_fallback = support_zone_text_v1525_9(structures, current_price, ccy, fallback=fallback)
    fundamental_tokens = (
        "gewinnwachstum", "ertrags", "earnings", "umsatzwachstum", "marge",
        "cashflow", "free cash flow", "operativer cashflow", "fundamental",
        "bewertung", "valuation", "analyst", "revision"
    )
    # Diese Punkte gehören in Bremsfaktoren/Red Flags, nicht in operative Trigger.
    if any(tok in low for tok in fundamental_tokens):
        return concrete_fallback

    # Wenn es bereits ein konkreter technischer/operativer Kipp-Punkt ist, behalten.
    technical_tokens = (
        "bruch", "unter", "support", "stop", "entry-zone", "trigger", "zone",
        "reaktionstief", "tagestief", "kerzentief", "trend", "ema", "sma",
        "widerstand", "rückfall", "rueckfall", "invalid", "verliert"
    )
    if any(tok in low for tok in technical_tokens):
        return txt

    # Generische Support-Formulierungen konkretisieren.
    if "nächsten relevanten support" in low or "naechsten relevanten support" in low or txt.strip().lower() == fallback.strip().lower():
        return concrete_fallback

    return concrete_fallback


def action_trigger_note_v1523_13(action_label, next_trigger, negative_trigger="-", trigger_status="-", trigger_reason="-", entry_quality="-", entry_zone="-", current_price=None, structures=None, ccy=""):
    action = str(action_label or "").strip().lower()
    nt_display = operational_trigger_text_v1523_12(next_trigger, trigger_status, trigger_reason, action_label, entry_quality, entry_zone, current_price, structures, ccy)
    neg = sanitize_operational_bearish_trigger_v1523_13(negative_trigger, structures=structures, current_price=current_price, ccy=ccy)
    if action == "kaufen":
        return f"Negativer Trigger: {neg}"
    if nt_display and str(nt_display).strip() not in {"", "-", "None", "nan"}:
        return f"Nächster Trigger: {nt_display}"
    return "Nächster Trigger: sauberer nächster Bestätigungsschritt"


def executive_summary_concrete_fields_v1525_10(
    verdict="-", why="-", improve="-", worsen="-", action_label="-",
    trigger_status="-", trigger_reason="-", entry_quality="-", entry_zone="-",
    current_price=None, structures=None, ccy="",
):
    """Macht die Executive Summary konkret: Statuswerte werden in Bedingungen uebersetzt."""
    action = str(action_label or "-").strip().lower()
    zone_txt = str(entry_zone or "-").strip()
    has_zone = zone_txt not in {"", "-", "None", "nan"}
    zone_pos_txt, in_zone, below_zone, above_zone = _entry_zone_position_text_v1524_12(zone_txt, current_price)

    v = str(verdict or "-").strip()
    if v == "Ja":
        focus = "Einstieg ist grundsätzlich freigegeben - aber nur, wenn Zone und Invalidierung respektiert werden."
    elif v == "Fast":
        focus = "Setup ist interessant, aber noch bestätigungsabhängig."
    elif v == "Nein":
        focus = "Kein Einstiegssignal: Risiko, Timing oder Umfeld sprechen dagegen."
    else:
        focus = "Noch kein aktiver Einstieg: erst Setup/Timing verbessern lassen."
    base_why = str(why or "").strip()
    if base_why and base_why not in {"-", "None", "nan"} and base_why not in focus:
        focus = f"{focus} {base_why}"

    bull = operational_trigger_text_v1523_12(
        improve, trigger_status, trigger_reason, action_label, entry_quality,
        entry_zone, current_price, structures, ccy
    )
    low_bull = str(bull or "").strip().lower()
    if low_bull in {"", "-", "none", "nan", "sauberem trigger nach oben", "sauberer trigger nach oben"}:
        bull = explain_clearer_setup_trigger_v1525_9(entry_zone, current_price, structures, ccy)

    if has_zone:
        if in_zone and action != "kaufen":
            bull = f"Entry-Zone {zone_txt} ist erreicht. Bullisher wird es erst bei Bestätigung: Stabilisierung in der Zone, bullische Reaktion oder Bruch über ein kurzfristiges Hoch."
        elif below_zone:
            if "knapp unter" in str(zone_pos_txt).lower():
                bull = f"Entry-Zone {zone_txt} ist fast erreicht. Bullisher wird es bei Reclaim/Stabilisierung in der Zone oder bullischer Reaktion - nicht erst durch weiteres Warten auf den Preisbereich."
            else:
                bull = f"Bullisher bei Annäherung/Reclaim der Entry-Zone {zone_txt} plus klarer Bestätigung."
        elif above_zone:
            if "knapp über" in str(zone_pos_txt).lower():
                bull = f"Kurs liegt knapp über der Entry-Zone {zone_txt}. Bullisher erst bei Pullback in die Zone oder neuer Bestätigung - nicht blind hinterherlaufen."
            else:
                bull = f"Kurs liegt über der Entry-Zone {zone_txt}. Bullisher erst bei Rücksetzer oder neuer Base - nicht hinterherlaufen."

    bear = sanitize_operational_bearish_trigger_v1523_13(
        worsen, structures=structures, current_price=current_price, ccy=ccy
    )
    low_bear = str(bear or "").strip().lower()
    if low_bear in {"", "-", "none", "nan"} or "nächsten relevanten support" in low_bear or "naechsten relevanten support" in low_bear:
        bear = support_zone_text_v1525_9(structures, current_price, ccy, fallback="Bruch der aktiven Entry-/Support-Zone")

    return focus, bull, bear


def action_trigger_note_v1520_2(action_label, next_trigger, negative_trigger="-", trigger_status="-", trigger_reason="-", entry_quality="-", entry_zone="-", current_price=None):
    action = str(action_label or "").strip().lower()
    nt_display = operational_trigger_text_v1523_12(next_trigger, trigger_status, trigger_reason, action_label, entry_quality, entry_zone, current_price)
    neg = str(negative_trigger or "-").strip()
    if action == "kaufen":
        if neg and neg not in {"-", "None", "nan"}:
            return f"Negativer Trigger: {neg}"
        return "Negativer Trigger: Einstieg verwerfen, wenn der Kurs die Entry-/Support-Zone klar verliert."
    if nt_display and nt_display not in {"-", "None", "nan"}:
        return f"Nächster Trigger: {nt_display}"
    return "Nächster Trigger: sauberer nächster Bestätigungsschritt"


def apply_conflict_to_timing_label(base_timing, conflict_pkg, risk_label="stabil"):
    result = str(base_timing or "noch nicht reif")
    conflict = str((conflict_pkg or {}).get("label", "konsistent")).lower()
    reason = "Kein dominanter Signal-Konflikt wirkt auf das Timing."

    if conflict == "widersprüchlich":
        if result == "reif":
            result = "fast reif"
        elif result == "fast reif":
            result = "noch nicht reif"
        elif result == "noch nicht reif" and risk_label != "stabil":
            result = "unattraktiv"
        reason = "Widersprüchliche Signale machen das Timing defensiver."
    elif conflict == "gemischt":
        if result == "reif" and risk_label != "stabil":
            result = "fast reif"
        elif result == "fast reif" and risk_label == "kritisch":
            result = "noch nicht reif"
        reason = "Gemischte Signale bremsen das Timing leicht."
    return result, reason


def apply_conflict_to_action_label(base_action, conflict_pkg, timing_label="-", risk_label="stabil", position_mode=False):
    result = str(base_action or ("halten" if position_mode else "abwarten"))
    conflict = str((conflict_pkg or {}).get("label", "konsistent")).lower()
    reason = "Kein dominanter Signal-Konflikt wirkt auf die Aktion."

    if not position_mode:
        if conflict == "widersprüchlich":
            if result == "kaufen":
                result = "vorbereiten"
            elif result == "vorbereiten":
                result = "abwarten"
            reason = "Widersprüchliche Signale erzwingen eine defensivere Aktion."
        elif conflict == "gemischt":
            if result == "kaufen":
                result = "vorbereiten"
                reason = "Gemischte Signale sprechen gegen einen sofortigen Kauf und eher für Vorbereiten."
            elif result == "vorbereiten" and risk_label == "kritisch":
                result = "abwarten"
                reason = "Gemischte Signale plus kritisches Risiko sprechen für mehr Geduld."
            else:
                reason = "Gemischte Signale bremsen die Aktion leicht, aber nicht übermäßig."
    else:
        if conflict == "widersprüchlich":
            if result == "halten" and risk_label in {"erhöht", "kritisch"}:
                result = "stop enger"
            elif result == "stop enger" and risk_label == "kritisch":
                result = "teilgewinn prüfen"
            reason = "Widersprüchliche Signale verlangen defensiveres Positionsmanagement."
        elif conflict == "gemischt":
            if result == "halten" and risk_label == "kritisch":
                result = "stop enger"
            reason = "Gemischte Signale sprechen für engere Kontrolle."
    return result, reason


def apply_conflict_to_priority_label(base_priority, conflict_pkg, timing_label="-", risk_label="stabil"):
    result = str(base_priority or "mittel")
    conflict = str((conflict_pkg or {}).get("label", "konsistent")).lower()
    reason = "Kein dominanter Signal-Konflikt wirkt auf die Priorität."

    if conflict == "widersprüchlich":
        if result == "hoch":
            result = "mittel"
        elif result == "mittel":
            result = "niedrig"
        reason = "Widersprüchliche Signale drücken die Priorität spürbar."
    elif conflict == "gemischt":
        if result == "hoch" and (timing_label != "reif" or risk_label != "stabil"):
            result = "mittel"
        reason = "Gemischte Signale machen die Priorisierung selektiver."
    return result, reason


def merge_reasons(primary_reason, conflict_reason):
    p = str(primary_reason or "").strip()
    c = str(conflict_reason or "").strip()
    if not c or "Kein dominanter Signal-Konflikt" in c:
        return p
    if not p:
        return c
    return p + " " + c

def compute_overall_setup_quality_phase_ui(
    investment_case="-",
    timing_label="-",
    risk_label="-",
    priority_label="-",
    action_label="-",
    regime_ctx=None,
    conflict_pkg=None,
    tactical_label="-",
    ultra_label="-",
    candle_daily=None,
    candle_hourly=None,
):
    inv = str(investment_case or "").lower()
    timing = str(timing_label or "").lower()
    risk = str(risk_label or "").lower()
    priority = str(priority_label or "").lower()
    action = str(action_label or "").lower()
    tactical = str(tactical_label or "").lower()
    ultra = str(ultra_label or "").lower()
    regime_bias = int((regime_ctx or {}).get("bias_factor", 0))
    conflict_label = str((conflict_pkg or {}).get("label", "konsistent")).lower()

    daily_tone = str((candle_daily or {}).get("tone", "neutral")).lower() if isinstance(candle_daily, dict) else "neutral"
    hourly_tone = str((candle_hourly or {}).get("tone", "neutral")).lower() if isinstance(candle_hourly, dict) else "neutral"

    score = 0
    reasons_up = []
    reasons_down = []

    # positive contributors
    if inv == "attraktiv":
        score += 2
        reasons_up.append("starker Grundcase")
    elif inv == "solide":
        score += 1
        reasons_up.append("solider Grundcase")

    if timing == "reif":
        score += 3
        reasons_up.append("Timing ist reif")
    elif timing == "fast reif":
        score += 2
        reasons_up.append("Timing ist fast reif")
    elif timing == "noch nicht reif":
        score -= 1
        reasons_down.append("Timing ist noch nicht frei")
    elif timing == "unattraktiv":
        score -= 3
        reasons_down.append("Timing ist unattraktiv")

    if risk == "stabil":
        score += 2
        reasons_up.append("Risiko ist stabil")
    elif risk == "erhöht":
        score -= 1
        reasons_down.append("Risiko ist erhöht")
    elif risk == "kritisch":
        score -= 4
        reasons_down.append("Risiko ist kritisch")

    if priority == "hoch":
        score += 2
        reasons_up.append("hohe Setup-Priorität")
    elif priority == "mittel":
        score += 0
    elif priority == "niedrig":
        score -= 1
        reasons_down.append("geringe Setup-Priorität")

    if action in {"kaufen", "vorbereiten"}:
        score += 1
    elif action in {"abwarten", "stop enger"}:
        score -= 1
    elif action in {"teilgewinn prüfen", "exit prüfen"}:
        score -= 2
        reasons_down.append("Aktion ist defensiv")

    if regime_bias > 0:
        score += 1
        reasons_up.append("positives Marktumfeld")
    elif regime_bias < 0:
        score -= 2
        reasons_down.append("risk-off Umfeld")

    if conflict_label == "konsistent":
        score += 1
        reasons_up.append("Signale sind konsistent")
    elif conflict_label == "gemischt":
        score -= 1
        reasons_down.append("Signalbild gemischt")
    elif conflict_label == "widersprüchlich":
        score -= 3
        reasons_down.append("Signalbild widersprüchlich")

    if tactical in {"erhöht"}:
        score -= 1
        reasons_down.append("taktische Warnung")
    elif tactical in {"kritisch"}:
        score -= 2
        reasons_down.append("kritische Taktik")

    if ultra in {"aktives signal", "frühe reaktion"} and risk != "kritisch":
        score += 1
        reasons_up.append("kurzfristig konstruktive Reaktion")
    elif ultra in {"kein signal"} and timing in {"noch nicht reif", "unattraktiv"}:
        score -= 1

    if daily_tone == "bullish" or hourly_tone == "bullish":
        score += 1
    if daily_tone == "bearish" and hourly_tone == "bearish":
        score -= 1
        reasons_down.append("Candle-Lesart bleibt defensiv")

    # hard clamps
    if risk == "kritisch" or conflict_label == "widersprüchlich":
        if score > 2:
            score = 2
    if timing == "reif" and risk == "stabil" and conflict_label == "konsistent" and regime_bias >= 0 and inv in {"attraktiv", "solide"}:
        score = max(score, 7)

    if score >= 7:
        label = "hochwertig"
        summary = "Gutes Gesamtbild mit tragfähigem Timing und begrenzten Störfaktoren."
        tone = "bull"
    elif score >= 3:
        label = "brauchbar"
        summary = "Interessant, aber noch nicht durchgehend sauber oder frei genug."
        tone = "neutral"
    elif score >= 0:
        label = "grenzwertig"
        summary = "Mehrere Spannungen bremsen das Setup derzeit noch sichtbar."
        tone = "warn"
    else:
        label = "schwach"
        summary = "Aktuell kein überzeugendes Gesamtbild für ein belastbares Setup."
        tone = "bear"

    top_up = reasons_up[0] if reasons_up else "-"
    top_down = reasons_down[0] if reasons_down else "-"
    return {
        "label": label,
        "summary": summary,
        "tone": tone,
        "score": score,
        "top_up": top_up,
        "top_down": top_down,
        "reasons_up": reasons_up[:4],
        "reasons_down": reasons_down[:4],
    }




