def first_existing_row(df, names):
    if df is None or getattr(df, "empty", True):
        return None
    for name in names:
        if name in df.index:
            row = df.loc[name]
            if isinstance(row, pd.DataFrame):
                row = row.iloc[0]
            return pd.to_numeric(row, errors="coerce")
    return None


def latest_valid(series_like):
    if series_like is None:
        return np.nan
    s = pd.to_numeric(pd.Series(series_like), errors="coerce").dropna()
    return float(s.iloc[0]) if len(s) else np.nan


def previous_valid(series_like):
    if series_like is None:
        return np.nan
    s = pd.to_numeric(pd.Series(series_like), errors="coerce").dropna()
    return float(s.iloc[1]) if len(s) > 1 else np.nan


def select_benchmark(ticker, info=None):
    suffix = ticker.split(".")[-1].upper() if "." in ticker else ""
    exchange = str((info or {}).get("exchange", "") or "").upper()

    german_suffixes = {"DE", "F", "HM", "BE", "DU", "MU", "SG"}
    europe_suffixes = {"PA", "AS", "BR", "MI", "MC", "HE", "VI", "LS"}
    swiss_suffixes = {"SW"}
    uk_suffixes = {"L"}
    nordic_suffixes = {"ST", "OL", "CO"}

    if suffix in german_suffixes or exchange in {"XETRA", "GER"}:
        return "^GDAXI", "DAX"
    if suffix in europe_suffixes or exchange in {"PAR", "AMS", "MIL", "MAD", "HEL", "VIE", "BRU", "EURONEXT"}:
        return "^STOXX50E", "STOXX 50"
    if suffix in swiss_suffixes or exchange in {"SIX"}:
        return "^SSMI", "SMI"
    if suffix in uk_suffixes or exchange in {"LSE"}:
        return "^FTSE", "FTSE 100"
    if suffix in nordic_suffixes:
        return "^STOXX50E", "STOXX 50"

    return "SPY", "S&P 500"


def calc_return_metrics(close_series):
    return {
        "ret21": safe_last(close_series.pct_change(21) * 100, np.nan),
        "ret63": safe_last(close_series.pct_change(63) * 100, np.nan),
        "ret126": safe_last(close_series.pct_change(126) * 100, np.nan),
    }


def evaluate_market_filter(benchmark_df):
    """
    v17.11: Marktfilter mit Schock-/Korrektur-Normalisierung.

    Ein einzelner starker Index-Rueckgang soll nicht automatisch alle Aktien wie in
    einem strukturellen Risk-off bewerten. Deshalb trennt die Logik jetzt:
    - strukturelles Risk-off: Index unter MA50/MA200 und MA50 unter MA200
    - Korrekturmodus: kurzfristiger Schock/Ruecksetzer, aber langfristiger Trend noch intakt
    - normales positives/neutrales Umfeld
    """
    if benchmark_df is None or benchmark_df.empty or "Close" not in benchmark_df.columns:
        return {
            "price": np.nan,
            "ma50": np.nan,
            "ma200": np.nan,
            "ret1": np.nan,
            "ret5": np.nan,
            "ret10": np.nan,
            "ret21": np.nan,
            "ret63": np.nan,
            "ret126": np.nan,
            "high252": np.nan,
            "low252": np.nan,
            "dist252": np.nan,
            "correction_mode": False,
            "market_shock": False,
            "shock_reason": "Keine belastbaren Benchmark-Daten.",
            "regime": "UNBEKANNT",
            "ampel": "⚪",
            "score": 50
        }

    close = benchmark_df["Close"]
    price = safe_last(close, np.nan)
    ma50 = safe_last(close.rolling(50).mean(), np.nan)
    ma200 = safe_last(close.rolling(200).mean(), np.nan)
    high252 = safe_last(close.rolling(252).max(), float(close.max()) if len(close.dropna()) else np.nan)
    low252 = safe_last(close.rolling(252).min(), float(close.min()) if len(close.dropna()) else np.nan)
    dist252 = price / high252 * 100 if pd.notna(price) and pd.notna(high252) and high252 else np.nan

    rets = calc_return_metrics(close)
    ret1 = safe_last(close.pct_change(1) * 100, np.nan)
    ret5 = safe_last(close.pct_change(5) * 100, np.nan)
    ret10 = safe_last(close.pct_change(10) * 100, np.nan)

    correction_mode = False
    market_shock = False
    shock_reason = ""

    if pd.notna(price) and pd.notna(ma50) and pd.notna(ma200):
        long_trend_intact = price > ma200 and ma50 >= ma200
        structural_bear = price < ma50 and price < ma200 and ma50 < ma200
        short_shock = (pd.notna(ret1) and ret1 <= -3.0) or (pd.notna(ret5) and ret5 <= -4.5)
        ma50_lost_but_long_ok = price < ma50 and long_trend_intact

        if structural_bear:
            regime, ampel_icon, score = "NEGATIV", "🔴", 30
            shock_reason = "Strukturelles Risk-off: Index unter MA50 und MA200, MA50 unter MA200."
        elif long_trend_intact and (short_shock or ma50_lost_but_long_ok):
            # Bewusst als NEUTRAL belassen, damit alte harte NEGATIV-Pfade nicht alles pauschal abwerten.
            regime, ampel_icon, score = "NEUTRAL", "🟠", 58
            correction_mode = True
            market_shock = bool(short_shock)
            bits = []
            if pd.notna(ret1) and ret1 <= -3.0:
                bits.append(f"1T {ret1:.1f}%")
            if pd.notna(ret5) and ret5 <= -4.5:
                bits.append(f"5T {ret5:.1f}%")
            if ma50_lost_but_long_ok:
                bits.append("MA50 unter Druck, MA200-Trend noch intakt")
            shock_reason = "Korrekturmodus: " + "; ".join(bits) if bits else "Kurzfristige Korrektur, langfristiger Trend noch nicht gebrochen."
        elif price > ma50 and price > ma200 and ma50 > ma200:
            regime, ampel_icon, score = "POSITIV", "🟢", 100
            shock_reason = "Trendbild positiv."
        else:
            regime, ampel_icon, score = "NEUTRAL", "🟡", 60
            shock_reason = "Gemischtes Marktbild."
    else:
        regime, ampel_icon, score = "UNBEKANNT", "⚪", 50
        shock_reason = "Benchmark-Daten unvollstaendig."

    return {
        "price": price,
        "ma50": ma50,
        "ma200": ma200,
        "ret1": ret1,
        "ret5": ret5,
        "ret10": ret10,
        "ret21": rets["ret21"],
        "ret63": rets["ret63"],
        "ret126": rets["ret126"],
        "high252": high252,
        "low252": low252,
        "dist252": dist252,
        "correction_mode": correction_mode,
        "market_shock": market_shock,
        "shock_reason": shock_reason,
        "regime": regime,
        "ampel": ampel_icon,
        "score": score
    }


def infer_market_bucket(ticker, info):
    suffix = ticker.split(".")[-1].upper() if "." in ticker else ""
    exchange = str((info or {}).get("exchange", "") or "").upper()
    ccy = str((info or {}).get("currency", "") or "").upper()

    us_ex = {"NASDAQ", "NASDAQGS", "NYQ", "NYSE", "AMEX", "PCX"}
    eu_suffixes = {"DE", "PA", "AS", "BR", "MI", "MC", "HE", "VI", "LS", "F", "SW", "L", "ST", "OL", "CO"}

    if exchange in us_ex or ccy == "USD" and suffix == "":
        return "USA"
    if suffix in eu_suffixes or ccy in {"EUR", "GBP", "CHF", "SEK", "NOK", "DKK"}:
        return "Europa"
    return "Andere"


def infer_stock_style_advanced(revenue_growth, earnings_growth, pe, pb, beta, debt_to_equity, roe, profit_margin, sector):
    sector = str(sector or "").lower()
    if pd.notna(revenue_growth) and revenue_growth > 0.15 and pd.notna(pe) and pe > 25:
        return "Growth"
    if pd.notna(roe) and roe > 0.18 and pd.notna(profit_margin) and profit_margin > 0.15:
        return "Quality"
    if pd.notna(pe) and pe < 15 and pd.notna(pb) and pb < 2:
        return "Value"
    if pd.notna(beta) and beta > 1.5:
        return "Cyclical"
    if pd.notna(earnings_growth) and earnings_growth < 0 and pd.notna(debt_to_equity) and debt_to_equity > 150:
        return "Turnaround / Risk"
    if "utility" in sector or "consumer defensive" in sector:
        return "Defensive"
    return "Neutral"


def get_style_sector_adjustment(style, sector):
    sector = str(sector or "").lower()
    weights = {
        "quality": 1.0,
        "growth": 1.0,
        "valuation": 1.0,
        "balance": 1.0,
        "momentum": 1.0,
        "trend": 1.0,
    }

    if style == "Growth":
        weights["growth"] = 1.18
        weights["momentum"] = 1.10
        weights["valuation"] = 0.82
    elif style == "Quality":
        weights["quality"] = 1.15
        weights["balance"] = 1.08
    elif style == "Value":
        weights["valuation"] = 1.20
        weights["balance"] = 1.08
        weights["growth"] = 0.88
    elif style == "Defensive":
        weights["balance"] = 1.16
        weights["momentum"] = 0.90
    elif style == "Cyclical":
        weights["trend"] = 1.12
        weights["momentum"] = 1.12

    if "technology" in sector or "software" in sector or "semiconductor" in sector:
        weights["growth"] *= 1.10
        weights["trend"] *= 1.07
        weights["valuation"] *= 0.86
    elif "financial" in sector or "bank" in sector or "insurance" in sector:
        weights["balance"] *= 1.15
        weights["valuation"] *= 1.12
        weights["growth"] *= 0.90
    elif "health" in sector or "pharma" in sector or "biotech" in sector:
        weights["quality"] *= 1.08
        weights["balance"] *= 1.05
    elif "energy" in sector or "materials" in sector:
        weights["trend"] *= 1.12
        weights["momentum"] *= 1.05
    elif "consumer defensive" in sector or "utilities" in sector:
        weights["balance"] *= 1.18
        weights["momentum"] *= 0.88

    return weights


def build_red_flags(
    revenue_growth,
    earnings_growth,
    profit_margin,
    fcf,
    op_cf,
    debt_to_equity,
    current_ratio,
    quick_ratio,
    has_upcoming_earnings,
    days_earn
):
    items = []

    def add_item(category, detail, penalty):
        is_hard_red_flag = penalty >= 6
        items.append({
            "Kategorie": category,
            "Status": "🔴" if is_hard_red_flag else "🟡",
            "Schwere": "Red Flag" if is_hard_red_flag else "Hinweis",
            "Detail": detail,
            "Penalty": penalty,
            "Score_Wirksam": is_hard_red_flag
        })

    # v16.0: Qualitätsunternehmen nicht durch einzelne kurzfristige yfinance-Wachstumswerte hart bestrafen.
    # earningsGrowth/revenueGrowth sind oft kurzzyklische YoY-/Quartalswerte. Bei profitablen Unternehmen
    # mit positiven Cashflows sollen sie als Bremse/Hinweis erscheinen, aber nicht als harte Red Flag.
    earnings_growth_weak = pd.notna(earnings_growth) and earnings_growth < -0.15
    earnings_growth_very_weak = pd.notna(earnings_growth) and earnings_growth < -0.35
    revenue_growth_weak = pd.notna(revenue_growth) and revenue_growth < -0.03
    revenue_growth_very_weak = pd.notna(revenue_growth) and revenue_growth < -0.10
    margin_negative = pd.notna(profit_margin) and profit_margin < 0
    margin_thin = pd.notna(profit_margin) and profit_margin < 0.05
    cashflow_negative = (pd.notna(fcf) and fcf < 0) or (pd.notna(op_cf) and op_cf < 0)
    cashflow_positive = (pd.notna(fcf) and fcf > 0) or (pd.notna(op_cf) and op_cf > 0)
    quality_buffer = (pd.notna(profit_margin) and profit_margin >= 0.12 and cashflow_positive)

    if earnings_growth_weak:
        # v16.0.3: Kurzfristiges Gewinnwachstum allein ist KEINE harte Red Flag.
        # Hart nur bei klarer operativer Bestätigung durch negative Marge oder negativen Cashflow.
        if margin_negative or cashflow_negative:
            add_item("Ertrags-Risiko", "Gewinnwachstum stark negativ und durch Marge/Cashflow operativ bestaetigt", 7)
        elif earnings_growth_very_weak:
            add_item("Ertragsdynamik", "Kurzfristiges Gewinnwachstum sehr schwach; als Bremse beobachten, nicht als harte Red Flag", 0)
        else:
            add_item("Ertragsdynamik", "Kurzfristiges Gewinnwachstum negativ; als Bremse beobachten, nicht als harte Red Flag", 0)

    if margin_negative:
        add_item("Ertrags-Risiko", "Gewinnmarge negativ", 8)

    if revenue_growth_very_weak:
        # v16.0.3: Umsatzrückgang allein ist bei Qualitätswerten kein harter Problemfall.
        # Hart nur bei klarer operativer Bestätigung durch negative Marge oder negativen Cashflow.
        if margin_negative or cashflow_negative:
            add_item("Umsatz-/Geschäfts-Risiko", "Umsatzwachstum negativ und durch Marge/Cashflow operativ bestaetigt", 6)
        else:
            add_item("Umsatzdynamik", "Umsatzwachstum negativ; als Bremse beobachten, nicht als harte Red Flag", 0)
    elif revenue_growth_weak:
        add_item("Umsatzdynamik", "Umsatzwachstum kurzfristig schwach", 0)

    if pd.notna(fcf) and fcf < 0:
        add_item("Cashflow-Risiko", "Freier Cashflow negativ", 6)
    if pd.notna(op_cf) and op_cf < 0:
        add_item("Cashflow-Risiko", "Operativer Cashflow negativ", 5)
    if pd.notna(debt_to_equity) and debt_to_equity > 180:
        add_item("Bilanz-Risiko", "Verschuldung sehr hoch", 8)

    current_ratio_weak = pd.notna(current_ratio) and current_ratio < 1.0
    quick_ratio_weak = pd.notna(quick_ratio) and quick_ratio < 0.8
    cashflow_weak = (
        (pd.notna(op_cf) and op_cf < 0)
        or (pd.notna(fcf) and fcf < 0)
    )
    cashflow_strong = (
        (pd.notna(op_cf) and op_cf > 0)
        and (pd.notna(fcf) and fcf > 0)
    )

    if current_ratio_weak and (quick_ratio_weak or cashflow_weak):
        add_item("Bilanz-Risiko", "Liquidität schwach (Current Ratio < 1.0)", 5)

    if quick_ratio_weak and not cashflow_strong:
        add_item("Bilanz-Risiko", "Quick Ratio schwach (< 0.8)", 4)
    if has_upcoming_earnings and pd.notna(days_earn) and days_earn <= 7:
        add_item("Event-Risiko", f"Earnings in {int(days_earn)} Tagen", 6)

    # v15.23.7: Nur echte rote Red Flags sollen das Gesamtergebnis spürbar belasten.
    # Gelbe Hinweise bleiben sichtbar, verfälschen aber nicht mehr die Kernbewertung.
    total_penalty = sum(x["Penalty"] for x in items if x.get("Score_Wirksam", x.get("Penalty", 0) >= 6))
    return items, total_penalty

# ---------- v16.0.2: Qualitäts-Red-Flags robust nachsanieren ----------
def sanitize_quality_red_flags_v1601(items):
    """
    Verhindert, dass einzelne kurzzyklische yfinance-Wachstumswerte bei Qualitätswerten
    als harte Red Flags angezeigt oder score-wirksam werden.
    Harte Red Flags bleiben nur erhalten, wenn operative Bestätigung vorliegt.
    """
    cleaned = []
    for item in items or []:
        if not isinstance(item, dict):
            cleaned.append(item)
            continue
        new = dict(item)
        category = str(new.get("Kategorie", ""))
        detail = str(new.get("Detail", ""))
        txt = (category + " " + detail).lower()
        # v16.0.3: "operativ bestaetigt" alleine reicht nicht mehr, weil ältere
        # Ergebnisobjekte diesen Text pauschal enthielten. Hart bleibt nur, wenn
        # negative Marge oder negativer Cashflow explizit im Text steht.
        operative_confirmed = any(x in txt for x in [
            "marge negativ", "cashflow negativ", "freier cashflow negativ", "operativer cashflow negativ"
        ])

        if ("gewinnwachstum stark negativ" in txt or "gewinnwachstum negativ" in txt) and not operative_confirmed:
            new.update({
                "Kategorie": "Ertragsdynamik",
                "Status": "🟡",
                "Schwere": "Hinweis",
                "Detail": "Kurzfristiges Gewinnwachstum negativ; als Bremse beobachten, nicht als harte Red Flag",
                "Penalty": 0,
                "Score_Wirksam": False,
            })
        elif "umsatzwachstum negativ" in txt and not operative_confirmed:
            new.update({
                "Kategorie": "Umsatzdynamik",
                "Status": "🟡",
                "Schwere": "Hinweis",
                "Detail": "Umsatzwachstum kurzfristig schwach; als Bremse beobachten, nicht als harte Red Flag",
                "Penalty": 0,
                "Score_Wirksam": False,
            })
        cleaned.append(new)

    total_penalty = sum(
        float(x.get("Penalty", 0) or 0)
        for x in cleaned
        if isinstance(x, dict) and bool(x.get("Score_Wirksam", x.get("Penalty", 0) >= 6))
    )
    return cleaned, total_penalty


# ---------- v16.0.4: harte Red Flags final klassifizieren ----------
def is_hard_red_flag_v1604(item):
    """Nur operative, score-wirksame Problemfälle als harte Red Flag anzeigen.

    Kurzfristig negatives Gewinn-/Umsatzwachstum aus yfinance darf selbst dann
    nicht als harte Red Flag durchrutschen, wenn ältere Ergebnisobjekte noch
    Score_Wirksam=True oder Penalty>=6 enthalten.
    """
    if not isinstance(item, dict):
        return False
    category = str(item.get("Kategorie", "") or "")
    detail = str(item.get("Detail", "") or "")
    txt = (category + " " + detail).lower()

    growth_only_patterns = [
        "gewinnwachstum stark negativ",
        "gewinnwachstum negativ",
        "umsatzwachstum negativ",
        "umsatzwachstum kurzfristig schwach",
        "kurzfristiges gewinnwachstum",
        "ertragsdynamik",
        "umsatzdynamik",
    ]
    operative_patterns = [
        "gewinnmarge negativ",
        "marge negativ",
        "freier cashflow negativ",
        "operativer cashflow negativ",
        "cashflow negativ",
        "verschuldung sehr hoch",
        "liquiditaet kritisch",
        "liquidität kritisch",
    ]

    # Wachstum allein ist nur Hinweis. Hart nur, wenn im selben Text ein echter
    # operativer Bestätiger steht.
    if any(p in txt for p in growth_only_patterns) and not any(p in txt for p in operative_patterns):
        return False

    return bool(item.get("Score_Wirksam", item.get("Penalty", 0) >= 6))


def soften_growth_red_flag_item_v1604(item):
    if not isinstance(item, dict):
        return item
    new = dict(item)
    txt = (str(new.get("Kategorie", "")) + " " + str(new.get("Detail", ""))).lower()
    if "gewinnwachstum" in txt or "ertrags-risiko" in txt and "gewinn" in txt:
        new.update({
            "Kategorie": "Ertragsdynamik",
            "Status": "🟡",
            "Schwere": "Hinweis",
            "Detail": "Kurzfristiges Gewinnwachstum schwach; als Bremse beobachten, nicht als harte Red Flag",
            "Penalty": 0,
            "Score_Wirksam": False,
        })
    elif "umsatzwachstum" in txt or "umsatz-/geschäfts-risiko" in txt or "umsatz-/geschaefts-risiko" in txt:
        new.update({
            "Kategorie": "Umsatzdynamik",
            "Status": "🟡",
            "Schwere": "Hinweis",
            "Detail": "Umsatzwachstum kurzfristig schwach; als Bremse beobachten, nicht als harte Red Flag",
            "Penalty": 0,
            "Score_Wirksam": False,
        })
    return new


def build_decision_explanation(
    setup,
    company,
    investment,
    market_regime,
    rs_vs_benchmark_63,
    quality_score,
    growth_score,
    valuation_score,
    balance_score,
    red_flag_items,
    earnings_warning,
    kb,
    position_mode
):
    strengths = []
    weaknesses = []

    if setup >= 75:
        strengths.append("Technisches Setup ist stark.")
    elif setup < 50:
        weaknesses.append("Technisches Setup ist derzeit schwach.")

    if company >= 70:
        strengths.append("Unternehmensqualität ist solide bis stark.")
    elif company < 50:
        weaknesses.append("Unternehmensqualität ist eher schwach.")

    if pd.notna(rs_vs_benchmark_63) and rs_vs_benchmark_63 > 5:
        strengths.append("Die Aktie zeigt klare Outperformance gegenüber dem Benchmark.")
    elif pd.notna(rs_vs_benchmark_63) and rs_vs_benchmark_63 < -5:
        weaknesses.append("Die Aktie underperformt ihren Benchmark spürbar.")

    if quality_score >= 75:
        strengths.append("Profitabilität und Kapitalrendite sind überzeugend.")
    if growth_score >= 75:
        strengths.append("Wachstum ist aktuell stark.")
    if valuation_score >= 72:
        strengths.append("Bewertung wirkt noch akzeptabel bis attraktiv.")
    elif valuation_score < 50:
        weaknesses.append("Bewertung wirkt anspruchsvoll.")

    if balance_score >= 72:
        strengths.append("Bilanzqualität ist ordentlich.")
    elif balance_score < 50:
        weaknesses.append("Bilanzqualität ist belastet.")

    if market_regime == "POSITIV":
        strengths.append("Das Marktumfeld unterstützt Long-Setups.")
    elif market_regime == "NEGATIV":
        weaknesses.append("Das Marktumfeld ist aktuell klar negativ.")

    if kb >= 3:
        strengths.append("Hohe Konfluenz der Kernblöcke.")
    elif kb <= 1:
        weaknesses.append("Zu wenig Konfluenz der Kernblöcke.")

    if earnings_warning:
        weaknesses.append("Kurzfristiges Earnings-Risiko erhöht die Unsicherheit.")

    for item in red_flag_items[:3]:
        weaknesses.append(f"{item['Kategorie']}: {item['Detail']}")

    strengths = strengths[:5]
    weaknesses = weaknesses[:5]

    if position_mode:
        if investment >= 75 and market_regime != "NEGATIV":
            summary = "Bestehende Position wirkt insgesamt stark. Halten oder selektiv ausbauen ist plausibel."
        elif investment >= 60:
            summary = "Bestehende Position ist grundsätzlich okay, aber nicht frei von Risiken. Eng beobachten."
        else:
            summary = "Bestehende Position wirkt anfällig. Risiko-Management und Stopps prüfen."
    else:
        if investment >= 75 and market_regime == "POSITIV":
            summary = "Guter Watchlist-Kandidat mit unterstützendem Marktumfeld."
        elif investment >= 60:
            summary = "Interessanter Kandidat, aber Timing oder Teilbereiche sind noch nicht ideal."
        else:
            summary = "Aktuell eher Beobachtung statt Einstieg."

    return strengths, weaknesses, summary


def infer_data_source_flags(info):
    direct_fields = [
        "profitMargins", "operatingMargins", "grossMargins", "returnOnEquity", "returnOnAssets",
        "revenueGrowth", "earningsGrowth", "currentRatio", "quickRatio", "debtToEquity",
        "freeCashflow", "operatingCashflow", "forwardPE", "pegRatio", "priceToSalesTrailing12Months",
        "priceToBook", "beta", "shortPercentOfFloat", "recommendationMean",
        "numberOfAnalystOpinions", "targetMeanPrice"
    ]
    loaded = int(info.get("_fund_fields_loaded", 0) or 0)
    total = len(direct_fields)
    derived = 0
    coverage = loaded / total if total else 0
    if coverage >= 0.75:
        confidence = "Hoch"
        confidence_icon = "🟢"
    elif coverage >= 0.50:
        confidence = "Mittel"
        confidence_icon = "🟡"
    else:
        confidence = "Niedrig"
        confidence_icon = "🔴"
    return {
        "loaded": loaded,
        "total": total,
        "coverage": coverage,
        "derived_estimate": derived,
        "confidence": confidence,
        "confidence_icon": confidence_icon
    }


def detect_chart_pivots(df, left=3, right=3):
    highs = []
    lows = []
    if df is None or df.empty or len(df) < left + right + 3:
        return highs, lows

    high = pd.to_numeric(df["High"], errors="coerce").reset_index(drop=True)
    low = pd.to_numeric(df["Low"], errors="coerce").reset_index(drop=True)

    for i in range(left, len(df) - right):
        current_high = high.iloc[i]
        current_low = low.iloc[i]
        if pd.isna(current_high) or pd.isna(current_low):
            continue

        high_left = high.iloc[i-left:i]
        high_right = high.iloc[i+1:i+1+right]
        low_left = low.iloc[i-left:i]
        low_right = low.iloc[i+1:i+1+right]

        if len(high_left.dropna()) == left and len(high_right.dropna()) == right:
            if current_high >= high_left.max() and current_high >= high_right.max():
                highs.append((i, float(current_high)))

        if len(low_left.dropna()) == left and len(low_right.dropna()) == right:
            if current_low <= low_left.min() and current_low <= low_right.min():
                lows.append((i, float(current_low)))

    return highs, lows



def cluster_chart_price_levels(points, tolerance_pct=1.5, min_touches=2):
    if not points:
        return []

    prices = sorted([float(p) for _, p in points if pd.notna(p)])
    if not prices:
        return []

    clusters = []
    current_cluster = [prices[0]]

    for price in prices[1:]:
        cluster_mean = float(np.mean(current_cluster))
        tolerance_abs = cluster_mean * (tolerance_pct / 100)
        if abs(price - cluster_mean) <= tolerance_abs:
            current_cluster.append(price)
        else:
            clusters.append(current_cluster)
            current_cluster = [price]

    clusters.append(current_cluster)

    zones = []
    for cluster in clusters:
        if len(cluster) >= min_touches:
            zones.append({
                "low": float(min(cluster)),
                "high": float(max(cluster)),
                "mid": float(np.mean(cluster)),
                "touches": int(len(cluster)),
            })
    return zones




def filter_chart_relevant_zones(zones, current_price, max_supports=2, max_resistances=2):
    if current_price is None or pd.isna(current_price):
        return [], []

    def _zone_rank(z):
        mid = float(z.get("mid", np.nan))
        touches = int(z.get("touches", 0) or 0)
        width_pct = float(z.get("width_pct", np.nan)) if pd.notna(z.get("width_pct", np.nan)) else np.nan
        dist_pct = abs((current_price - mid) / current_price) * 100 if pd.notna(mid) and current_price else 999.0

        score = 0.0
        score += min(touches, 5) * 12.0
        score += max(0.0, 22.0 - dist_pct * 2.0)

        if pd.notna(width_pct):
            if width_pct <= 1.8:
                score += 10.0
            elif width_pct <= 3.0:
                score += 6.0
            elif width_pct > 6.0:
                score -= 6.0

        return score

    filtered = []
    for z in zones:
        mid = z.get("mid", np.nan)
        low = z.get("low", np.nan)
        high = z.get("high", np.nan)
        touches = int(z.get("touches", 0) or 0)

        if pd.isna(mid) or pd.isna(low) or pd.isna(high):
            continue
        if touches < 2:
            continue

        width_pct = ((high / low) - 1) * 100 if low and low > 0 else np.nan
        dist_pct = abs((current_price - mid) / current_price) * 100 if current_price else np.nan

        if pd.notna(width_pct) and width_pct > 8.0:
            continue
        if pd.notna(dist_pct) and dist_pct > 22.0:
            continue

        z2 = dict(z)
        z2["width_pct"] = width_pct
        z2["dist_pct"] = dist_pct
        z2["_rank"] = _zone_rank(z2)
        filtered.append(z2)

    supports = [z for z in filtered if z["mid"] < current_price]
    resistances = [z for z in filtered if z["mid"] > current_price]

    supports = sorted(supports, key=lambda z: (-z["_rank"], abs(current_price - z["mid"])))[:max_supports]
    resistances = sorted(resistances, key=lambda z: (-z["_rank"], abs(current_price - z["mid"])))[:max_resistances]

    return supports, resistances




def fit_chart_line(points):
    if len(points) < 2:
        return None
    x = np.array([p[0] for p in points], dtype=float)
    y = np.array([p[1] for p in points], dtype=float)
    if len(np.unique(x)) < 2:
        return None
    slope, intercept = np.polyfit(x, y, 1)
    return float(slope), float(intercept)




def detect_chart_trend_channel(df, pivot_highs, pivot_lows, lookback=120):
    if df is None or df.empty:
        return None

    close = pd.to_numeric(df["Close"], errors="coerce").dropna()
    if close.empty or len(close) < 25:
        return None

    last_idx = len(df) - 1
    recent_highs = sorted([(i, p) for i, p in pivot_highs if i >= last_idx - lookback], key=lambda x: x[0])[-6:]
    recent_lows = sorted([(i, p) for i, p in pivot_lows if i >= last_idx - lookback], key=lambda x: x[0])[-6:]

    price_span = float(close.max() - close.min()) if len(close) else 0.0
    last_price = float(close.iloc[-1]) if len(close) else 0.0
    min_slope = max(price_span * 0.0010, last_price * 0.00025) if price_span > 0 else 0.0

    def _mostly_rising(points):
        if len(points) < 3:
            return False
        prices = [p for _, p in points]
        rises = sum(prices[i] >= prices[i-1] for i in range(1, len(prices)))
        return rises >= max(2, len(prices) - 2)

    def _mostly_falling(points):
        if len(points) < 3:
            return False
        prices = [p for _, p in points]
        falls = sum(prices[i] <= prices[i-1] for i in range(1, len(prices)))
        return falls >= max(2, len(prices) - 2)

    # 1) Pivot-basierter Kanal, wenn sauber vorhanden
    if _mostly_rising(recent_lows):
        line = fit_chart_line(recent_lows)
        if line:
            slope, intercept = line
            if slope > min_slope:
                offsets = [float(p - (slope * i + intercept)) for i, p in recent_highs]
                positive_offsets = [x for x in offsets if pd.notna(x)]
                if positive_offsets:
                    upper_offset = max(positive_offsets)
                    if upper_offset > max(price_span * 0.015, last_price * 0.01):
                        return {
                            "type": "uptrend",
                            "source": "pivot",
                            "slope": slope,
                            "lower_intercept": intercept,
                            "upper_intercept": intercept + upper_offset,
                        }

    if _mostly_falling(recent_highs):
        line = fit_chart_line(recent_highs)
        if line:
            slope, intercept = line
            if slope < -min_slope:
                offsets = [float(p - (slope * i + intercept)) for i, p in recent_lows]
                negative_offsets = [x for x in offsets if pd.notna(x)]
                if negative_offsets:
                    lower_offset = min(negative_offsets)
                    if abs(lower_offset) > max(price_span * 0.015, last_price * 0.01):
                        return {
                            "type": "downtrend",
                            "source": "pivot",
                            "slope": slope,
                            "upper_intercept": intercept,
                            "lower_intercept": intercept + lower_offset,
                        }

    # 2) Robuster Fallback: Regressionskanal über Schlusskurse
    reg_lookback = min(max(60, lookback), len(close))
    reg_close = close.tail(reg_lookback)
    if len(reg_close) < 25:
        return None

    x = np.arange(len(reg_close), dtype=float)
    y = reg_close.to_numpy(dtype=float)
    slope, intercept = np.polyfit(x, y, 1)

    residuals = y - (slope * x + intercept)
    channel_half_width = float(np.std(residuals) * 1.6) if len(residuals) else 0.0

    if not np.isfinite(channel_half_width) or channel_half_width <= 0:
        return None

    # zu enge Kanäle unterdrücken
    min_width = max(float(reg_close.iloc[-1]) * 0.008, price_span * 0.01 if price_span > 0 else 0.0)
    if channel_half_width < min_width:
        channel_half_width = min_width

    # in globale Indizes umrechnen
    global_start_idx = len(df) - len(reg_close)
    global_intercept = intercept - slope * global_start_idx

    if abs(slope) < max(min_slope * 0.35, last_price * 0.00008):
        channel_type = "sideways"
    else:
        channel_type = "uptrend" if slope > 0 else "downtrend"

    return {
        "type": channel_type,
        "source": "regression",
        "slope": float(slope),
        "lower_intercept": float(global_intercept - channel_half_width),
        "upper_intercept": float(global_intercept + channel_half_width),
    }

    close = pd.to_numeric(df["Close"], errors="coerce").dropna()
    if close.empty:
        return None

    last_idx = len(df) - 1
    recent_highs = sorted([(i, p) for i, p in pivot_highs if i >= last_idx - lookback], key=lambda x: x[0])[-6:]
    recent_lows = sorted([(i, p) for i, p in pivot_lows if i >= last_idx - lookback], key=lambda x: x[0])[-6:]

    price_span = float(close.max() - close.min()) if len(close) else 0.0
    min_slope = max(price_span * 0.0015, float(close.iloc[-1]) * 0.0004) if price_span > 0 else 0.0

    def _mostly_rising(points):
        if len(points) < 3:
            return False
        prices = [p for _, p in points]
        rises = sum(prices[i] >= prices[i-1] for i in range(1, len(prices)))
        return rises >= max(2, len(prices) - 2)

    def _mostly_falling(points):
        if len(points) < 3:
            return False
        prices = [p for _, p in points]
        falls = sum(prices[i] <= prices[i-1] for i in range(1, len(prices)))
        return falls >= max(2, len(prices) - 2)

    if _mostly_rising(recent_lows):
        line = fit_chart_line(recent_lows)
        if line:
            slope, intercept = line
            if slope > min_slope:
                offsets = [float(p - (slope * i + intercept)) for i, p in recent_highs]
                if offsets:
                    upper_offset = max(offsets)
                    if upper_offset > price_span * 0.03:
                        return {
                            "type": "uptrend",
                            "slope": slope,
                            "lower_intercept": intercept,
                            "upper_intercept": intercept + upper_offset,
                        }

    if _mostly_falling(recent_highs):
        line = fit_chart_line(recent_highs)
        if line:
            slope, intercept = line
            if slope < -min_slope:
                offsets = [float(p - (slope * i + intercept)) for i, p in recent_lows]
                if offsets:
                    lower_offset = min(offsets)
                    if abs(lower_offset) > price_span * 0.03:
                        return {
                            "type": "downtrend",
                            "slope": slope,
                            "upper_intercept": intercept,
                            "lower_intercept": intercept + lower_offset,
                        }

    return None




def classify_chart_zones_against_price(zones, current_price, max_supports=2, max_resistances=2, max_active=1):
    supports, resistances, active_zones = [], [], []
    if pd.isna(current_price):
        return supports, resistances, active_zones

    for z in zones or []:
        try:
            low = float(z.get("low", np.nan))
            high = float(z.get("high", np.nan))
            if pd.isna(low) or pd.isna(high):
                continue
            zone = dict(z)
            if high < current_price:
                zone["zone_type"] = "support"
                supports.append(zone)
            elif low > current_price:
                zone["zone_type"] = "resistance"
                resistances.append(zone)
            else:
                zone["zone_type"] = "active"
                active_zones.append(zone)
        except Exception:
            continue

    supports = sorted(supports, key=lambda z: abs(current_price - float(z.get("mid", current_price))))[:max_supports]
    resistances = sorted(resistances, key=lambda z: abs(float(z.get("mid", current_price)) - current_price))[:max_resistances]
    active_zones = sorted(active_zones, key=lambda z: abs(float(z.get("mid", current_price)) - current_price))[:max_active]
    return supports, resistances, active_zones



def build_chart_structures(df, sr_basis_df=None):
    basis_df = sr_basis_df if sr_basis_df is not None and not sr_basis_df.empty else df

    pivot_highs_basis, pivot_lows_basis = detect_chart_pivots(basis_df, left=3, right=3)
    pivot_zones = cluster_chart_price_levels(pivot_highs_basis + pivot_lows_basis, tolerance_pct=1.5, min_touches=2)

    current_price = float(pd.to_numeric(df["Close"], errors="coerce").iloc[-1]) if df is not None and not df.empty else np.nan
    supports, resistances, active_zones = classify_chart_zones_against_price(
        pivot_zones,
        current_price,
        max_supports=2,
        max_resistances=2,
        max_active=1,
    )

    pivot_highs, pivot_lows = detect_chart_pivots(df, left=3, right=3)
    channel = detect_chart_trend_channel(df, pivot_highs, pivot_lows, lookback=min(120, max(40, len(df) - 5)))

    if channel:
        channel["label"] = "Aufwaertskanal" if channel.get("type") == "uptrend" else "Abwaertskanal"
        channel["quality"] = "hoch" if channel.get("source") == "pivot" else "mittel"

    return {
        "pivot_highs": pivot_highs,
        "pivot_lows": pivot_lows,
        "pivot_highs_basis": pivot_highs_basis,
        "pivot_lows_basis": pivot_lows_basis,
        "zones": pivot_zones,
        "supports": supports,
        "resistances": resistances,
        "active_zones": active_zones,
        "current_price": current_price,
        "channel": channel,
        "sr_basis_label": "1 Jahr" if sr_basis_df is not None and not sr_basis_df.empty else "Chart-Zeitraum",
    }







def format_chart_zone_label(prefix, idx, zone, ccy=""):
    try:
        low = float(zone.get("low", np.nan))
        high = float(zone.get("high", np.nan))
        touches = int(zone.get("touches", 0))
        ccy_suffix = f" {ccy}".strip()
        return f"{prefix}{idx} ({touches}x) - {low:.2f} bis {high:.2f}{(' ' + ccy) if ccy else ''}"
    except Exception:
        touches = zone.get("touches", "?")
        return f"{prefix}{idx} ({touches}x)"

def add_sr_zones_to_plotly(fig, df, supports, resistances, active_zones=None, ccy="", show_labels=True):
    if df is None or df.empty:
        return
    x0 = df.index.min()
    x1 = df.index.max()

    for idx, z in enumerate(supports, start=1):
        label = _chart_zone_compact_label_v205("S", idx, z, ccy=ccy)
        fig.add_shape(
            type="rect",
            x0=x0,
            x1=x1,
            y0=z["low"],
            y1=z["high"],
            line=dict(width=0),
            fillcolor="rgba(34,197,94,0.24)",
            layer="below",
            row=1,
            col=1
        )
        if show_labels:
            _chart_add_annotation_v206(
                fig,
                x=_chart_label_xpos_v205(df, "left") or x0,
                y=z["mid"],
                text=label,
                kind="support",
                xanchor="left",
                yanchor="middle",
                yshift=_chart_label_yshift_v206(idx - 1, len(supports)),
                row=1,
                col=1,
            )

    for idx, z in enumerate(resistances, start=1):
        label = _chart_zone_compact_label_v205("R", idx, z, ccy=ccy)
        fig.add_shape(
            type="rect",
            x0=x0,
            x1=x1,
            y0=z["low"],
            y1=z["high"],
            line=dict(width=0),
            fillcolor="rgba(239,68,68,0.24)",
            layer="below",
            row=1,
            col=1
        )
        if show_labels:
            _chart_add_annotation_v206(
                fig,
                x=_chart_label_xpos_v205(df, "mid") or x1,
                y=z["mid"],
                text=label,
                kind="resistance",
                xanchor="center",
                yanchor="middle",
                yshift=_chart_label_yshift_v206(idx - 1, len(resistances)),
                row=1,
                col=1,
            )


    for idx, z in enumerate(active_zones or [], start=1):
        label = _chart_zone_compact_label_v205("Aktiv ", idx, z, ccy=ccy)
        fig.add_shape(
            type="rect",
            x0=x0,
            x1=x1,
            y0=z["low"],
            y1=z["high"],
            line=dict(width=0),
            fillcolor="rgba(59,130,246,0.18)",
            layer="below",
            row=1,
            col=1
        )
        if show_labels:
            _chart_add_annotation_v206(
                fig,
                x=_chart_label_xpos_v205(df, "right_inner") or x1,
                y=z["mid"],
                text=label,
                kind="active",
                xanchor="center",
                yanchor="middle",
                yshift=_chart_label_yshift_v206(idx - 1, len(active_zones or [])),
                row=1,
                col=1,
            )


def add_trend_channel_to_plotly(fig, df, channel):
    if not channel or df is None or df.empty:
        return

    x_vals = np.arange(len(df), dtype=float)
    x_dates = df.index
    slope = channel["slope"]
    lower_intercept = channel["lower_intercept"]
    upper_intercept = channel["upper_intercept"]

    lower_y = slope * x_vals + lower_intercept
    upper_y = slope * x_vals + upper_intercept

    lower_name = "Trendkanal unten" if channel.get("source") == "pivot" else "Trendkanal unten (Reg.)"
    upper_name = "Trendkanal oben" if channel.get("source") == "pivot" else "Trendkanal oben (Reg.)"

    fig.add_trace(
        go.Scatter(
            x=x_dates,
            y=lower_y,
            mode="lines",
            name=lower_name,
            line=dict(dash="dash", width=2.2, color="rgba(34,197,94,0.95)")
        ),
        row=1,
        col=1
    )
    fig.add_trace(
        go.Scatter(
            x=x_dates,
            y=upper_y,
            mode="lines",
            name=upper_name,
            line=dict(dash="dash", width=2.2, color="rgba(239,68,68,0.95)")
        ),
        row=1,
        col=1
    )

    label = channel.get("label", "Trendkanal")
    quality = channel.get("quality", "")
    label_text = f"{label} - Qualitaet: {quality}" if quality else label

    _chart_add_annotation_v206(
        fig,
        x=_chart_label_xpos_v205(df, "mid") or x_dates[-1],
        y=float((lower_y[-1] + upper_y[-1]) / 2.0),
        text=label_text,
        kind="trend",
        xanchor="center",
        yanchor="middle",
        yshift=18,
        row=1,
        col=1,
    )


def summarize_chart_structures(df, structures):
    summaries = []
    if df is None or df.empty or not structures:
        return summaries

    try:
        current_price = float(pd.to_numeric(df["Close"], errors="coerce").iloc[-1])
    except Exception:
        return summaries

    supports = structures.get("supports", []) or []
    resistances = structures.get("resistances", []) or []
    active_zones = structures.get("active_zones", []) or []
    channel = structures.get("channel")

    if supports:
        s1 = supports[0]
        s_mid = float(s1.get("mid", np.nan))
        s_touches = int(s1.get("touches", 0) or 0)
        if pd.notna(s_mid) and s_mid > 0:
            dist_pct = ((current_price / s_mid) - 1.0) * 100.0
            if abs(dist_pct) <= 1.5:
                summaries.append(f"Kurs aktuell nahe Support S1 ({s_touches}x) bei {s_mid:.2f}.")
            elif current_price < s_mid:
                summaries.append(f"Kurs unter S1 bei {s_mid:.2f} - Support wurde zuletzt unterschritten.")
            else:
                summaries.append(f"Nächster Support S1 liegt bei {s_mid:.2f}, Abstand {dist_pct:.1f}%.")

    if active_zones:
        z0 = active_zones[0]
        z_mid = float(z0.get("mid", np.nan))
        if pd.notna(z_mid):
            summaries.append(f"Kurs handelt aktuell in einer aktiven Zone um {z_mid:.2f}.")

    if resistances:
        r1 = resistances[0]
        r_mid = float(r1.get("mid", np.nan))
        r_touches = int(r1.get("touches", 0) or 0)
        if pd.notna(r_mid) and r_mid > 0:
            dist_pct = ((r_mid / current_price) - 1.0) * 100.0
            if abs(dist_pct) <= 1.5:
                summaries.append(f"Kurs läuft direkt an Widerstand R1 ({r_touches}x) bei {r_mid:.2f}.")
            elif current_price > r_mid:
                summaries.append(f"Kurs über R1 bei {r_mid:.2f} - Ausbruch über den nächsten Widerstand.")
            else:
                summaries.append(f"Nächster Widerstand R1 liegt bei {r_mid:.2f}, Abstand {dist_pct:.1f}%.")

    if channel:
        try:
            idx = len(df) - 1
            slope = float(channel.get("slope", 0.0))
            lower = slope * idx + float(channel.get("lower_intercept", 0.0))
            upper = slope * idx + float(channel.get("upper_intercept", 0.0))
            if upper > lower and current_price > 0:
                pos = (current_price - lower) / (upper - lower)
                label = channel.get("label", "Trendkanal")
                quality = channel.get("quality", "")
                quality_txt = f" ({quality})" if quality else ""
                if pos <= 0.25:
                    summaries.append(f"Kurs im unteren Bereich des {label.lower()}{quality_txt} - eher supportnah.")
                elif pos >= 0.75:
                    summaries.append(f"Kurs im oberen Bereich des {label.lower()}{quality_txt} - eher widerstandsnah.")
                else:
                    summaries.append(f"Kurs bewegt sich im mittleren Bereich des {label.lower()}{quality_txt}.")
        except Exception:
            pass

    return summaries


def compute_ultra_short_term_zone_signal(df, structures):
    signal = {
        "label": "Kein Signal",
        "strength": 0,
        "confirmation": "fehlt",
        "reason": "Keine klare Reaktion an einer relevanten Zone.",
        "bullets": [],
        "tone": "blue",
    }
    if df is None or df.empty or not structures or len(df) < 5:
        return signal

    try:
        close = pd.to_numeric(df["Close"], errors="coerce")
        open_ = pd.to_numeric(df["Open"], errors="coerce")
        high = pd.to_numeric(df["High"], errors="coerce")
        low = pd.to_numeric(df["Low"], errors="coerce")
        volume = pd.to_numeric(df.get("Volume"), errors="coerce") if "Volume" in df.columns else pd.Series(index=df.index, dtype=float)
        current_price = float(close.iloc[-1])
        prev_close = float(close.iloc[-2])
        prev_high = float(high.iloc[-2])
        prev_low = float(low.iloc[-2])
    except Exception:
        return signal

    ema10 = close.ewm(span=10, adjust=False).mean()
    ema20 = close.ewm(span=20, adjust=False).mean()
    vol20 = volume.rolling(20, min_periods=5).mean() if not volume.empty else pd.Series(index=df.index, dtype=float)

    candle_range = max(0.01, float(high.iloc[-1] - low.iloc[-1]))
    lower_wick = max(0.0, float(min(open_.iloc[-1], close.iloc[-1]) - low.iloc[-1]))
    upper_wick = max(0.0, float(high.iloc[-1] - max(open_.iloc[-1], close.iloc[-1])))
    lower_wick_ratio = lower_wick / candle_range
    upper_wick_ratio = upper_wick / candle_range
    close_pos = (float(close.iloc[-1]) - float(low.iloc[-1])) / candle_range

    supports = structures.get("supports", []) or []
    resistances = structures.get("resistances", []) or []
    active_zones = structures.get("active_zones", []) or []
    channel = structures.get("channel")

    bull = 0.0
    bear = 0.0
    watch = 0.0
    confirm = 0.0
    reasons_bull = []
    reasons_bear = []
    reasons_watch = []

    near_support = False
    near_resistance = False

    if supports:
        s1 = supports[0]
        s_mid = float(s1.get("mid", np.nan))
        if pd.notna(s_mid) and current_price > 0:
            dist_support = abs((current_price / s_mid) - 1.0) * 100.0
            if dist_support <= 1.8:
                bull += 26
                near_support = True
                reasons_bull.append("Kurs direkt an Support S1")
            elif dist_support <= 3.2:
                bull += 16
                reasons_bull.append("Kurs nahe Support S1")
            if current_price < s_mid:
                bear += 16
                reasons_bear.append("Kurs unter Support S1")

    if resistances:
        r1 = resistances[0]
        r_mid = float(r1.get("mid", np.nan))
        if pd.notna(r_mid) and current_price > 0:
            dist_res = abs((r_mid / current_price) - 1.0) * 100.0
            if dist_res <= 1.8:
                bear += 26
                near_resistance = True
                reasons_bear.append("Kurs direkt an Widerstand R1")
            elif dist_res <= 3.2:
                bear += 16
                reasons_bear.append("Kurs nahe Widerstand R1")
            if current_price > r_mid:
                bull += 14
                reasons_bull.append("Kurs ueber R1")

    if active_zones:
        z0 = active_zones[0]
        z_low = float(z0.get("low", np.nan))
        z_high = float(z0.get("high", np.nan))
        if pd.notna(z_low) and pd.notna(z_high) and z_low <= current_price <= z_high:
            watch += 24
            reasons_watch.append("Kurs in aktiver Entscheidungszone")

    if near_support:
        if lower_wick_ratio >= 0.35:
            bull += 12
            reasons_bull.append("unterer Docht an Support")
        if close_pos >= 0.62:
            bull += 8
            reasons_bull.append("Schlusskurs erholt sich aus der Zone")
        if float(close.iloc[-1]) > float(close.iloc[-2]):
            confirm += 10

    if near_resistance:
        if upper_wick_ratio >= 0.35:
            bear += 12
            reasons_bear.append("oberer Docht an Widerstand")
        if close_pos <= 0.42:
            bear += 8
            reasons_bear.append("schwacher Schlusskurs an R1")
        if float(close.iloc[-1]) < float(close.iloc[-2]):
            confirm += 10

    if len(df) >= 3:
        ret2 = ((float(close.iloc[-1]) / float(close.iloc[-3])) - 1.0) * 100.0
    else:
        ret2 = np.nan
    ret3 = ((float(close.iloc[-1]) / float(close.iloc[-4])) - 1.0) * 100.0 if len(df) >= 4 else np.nan

    if pd.notna(ema10.iloc[-1]):
        if current_price > float(ema10.iloc[-1]) and near_support:
            bull += 8
            reasons_bull.append("ueber EMA10")
        elif current_price < float(ema10.iloc[-1]) and near_resistance:
            bear += 8
            reasons_bear.append("unter EMA10")

    if pd.notna(ret2):
        if ret2 > 1.5 and near_support:
            bull += 10
            confirm += 8
            reasons_bull.append("2T-Momentum zieht an")
        elif ret2 < -1.5 and near_resistance:
            bear += 10
            confirm += 8
            reasons_bear.append("2T-Momentum kippt ab")
    if pd.notna(ret3):
        if ret3 > 2.5 and near_support:
            bull += 6
        elif ret3 < -2.5 and near_resistance:
            bear += 6

    if not vol20.empty and pd.notna(vol20.iloc[-1]) and vol20.iloc[-1] > 0 and not volume.empty and pd.notna(volume.iloc[-1]):
        vol_ratio = float(volume.iloc[-1] / vol20.iloc[-1])
        if near_support and float(close.iloc[-1]) > float(open_.iloc[-1]) and vol_ratio >= 1.1:
            bull += 8
            reasons_bull.append("Reaktion mit besserem Volumen")
        elif near_resistance and float(close.iloc[-1]) < float(open_.iloc[-1]) and vol_ratio >= 1.1:
            bear += 8
            reasons_bear.append("Ablehnung mit erhoehtem Volumen")
        elif vol_ratio < 0.85 and (near_support or near_resistance):
            watch += 4

    if channel:
        try:
            idx_last = len(df) - 1
            slope = float(channel.get("slope", 0.0))
            lower = slope * idx_last + float(channel.get("lower_intercept", 0.0))
            upper = slope * idx_last + float(channel.get("upper_intercept", 0.0))
            if upper > lower:
                pos = (current_price - lower) / (upper - lower)
                if pos <= 0.22:
                    bull += 10
                    reasons_bull.append("unterer Kanalbereich")
                elif pos >= 0.78:
                    bear += 10
                    reasons_bear.append("oberer Kanalbereich")
        except Exception:
            pass

    bull = int(round(clamp(bull, 0, 100)))
    bear = int(round(clamp(bear, 0, 100)))
    watch = int(round(clamp(watch, 0, 100)))
    confirm = int(round(clamp(confirm, 0, 100)))

    # v15.24.13: Ultra-Kurzfrist war zu streng und fiel dadurch fast immer auf
    # "Kein Signal" zurück. Für den Nutzer ist aber bereits eine kurzfristige
    # Reaktion an/nahe einer Zone relevant. Deshalb: harte Signale bleiben streng,
    # frühe Reaktionen werden separat ausgewiesen, statt komplett neutral zu wirken.
    max_side = max(bull, bear)
    side_gap = abs(bull - bear)

    if bull >= 48 and bull >= bear + 6:
        signal.update({
            "label": "Ultra-Kurzfrist bullish",
            "strength": bull,
            "tone": "blue",
            "reason": reasons_bull[0] if reasons_bull else "Support wird kurzfristig verteidigt.",
            "bullets": list(dict.fromkeys(reasons_bull))[:4],
        })
    elif bear >= 48 and bear >= bull + 6:
        signal.update({
            "label": "Ultra-Kurzfrist bearish",
            "strength": bear,
            "tone": "red",
            "reason": reasons_bear[0] if reasons_bear else "Widerstand wird kurzfristig bestaetigt.",
            "bullets": list(dict.fromkeys(reasons_bear))[:4],
        })
    elif bull >= 34 and bull >= bear + 5:
        signal.update({
            "label": "Frühe bullische Reaktion",
            "strength": bull,
            "tone": "amber",
            "reason": reasons_bull[0] if reasons_bull else "Erste konstruktive Reaktion, Bestaetigung fehlt noch.",
            "bullets": list(dict.fromkeys(reasons_bull + reasons_watch))[:4],
        })
    elif bear >= 34 and bear >= bull + 5:
        signal.update({
            "label": "Frühe bearische Reaktion",
            "strength": bear,
            "tone": "amber",
            "reason": reasons_bear[0] if reasons_bear else "Erste Schwäche an einer relevanten Zone, Bestaetigung fehlt noch.",
            "bullets": list(dict.fromkeys(reasons_bear + reasons_watch))[:4],
        })
    elif max(bull, bear, watch) >= 22:
        signal.update({
            "label": "Zone unter Beobachtung",
            "strength": max(bull, bear, watch),
            "tone": "amber",
            "reason": (reasons_watch or reasons_bull or reasons_bear or ["Zone wird getestet, Bestaetigung fehlt noch."])[0],
            "bullets": list(dict.fromkeys((reasons_watch + reasons_bull + reasons_bear)))[:4],
        })

    if confirm >= 20:
        signal["confirmation"] = "vorhanden"
    elif confirm >= 10:
        signal["confirmation"] = "teilweise"
    else:
        signal["confirmation"] = "fehlt"

    return signal


def evaluate_chart_structure_bias(df, structures):
    """
    Leichte Zusatzlesart aus S/R-Zonen und Trendkanal.
    Gibt nur kleine Adjustments zur operativen Einordnung zurück.
    """
    result = {
        "bias": 0,
        "setup_bias": 0,
        "tradeability_bias": 0,
        "notes_pos": [],
        "notes_neg": [],
        "summary": [],
    }
    if df is None or df.empty or not structures:
        return result

    try:
        current_price = float(pd.to_numeric(df["Close"], errors="coerce").iloc[-1])
    except Exception:
        return result

    supports = structures.get("supports", []) or []
    resistances = structures.get("resistances", []) or []
    active_zones = structures.get("active_zones", []) or []
    channel = structures.get("channel")

    if supports:
        s1 = supports[0]
        s_mid = float(s1.get("mid", np.nan))
        if pd.notna(s_mid) and s_mid > 0:
            dist_pct = ((current_price / s_mid) - 1.0) * 100.0
            if 0 <= dist_pct <= 1.6:
                result["bias"] += 2
                result["setup_bias"] += 2
                result["notes_pos"].append("Kurs nahe Support S1")
                result["summary"].append(f"Support S1 stützt bei {s_mid:.2f}.")
            elif current_price < s_mid:
                result["bias"] -= 2
                result["tradeability_bias"] -= 2
                result["notes_neg"].append("Kurs unter Support S1")
                result["summary"].append(f"S1 bei {s_mid:.2f} wurde unterschritten.")

    if active_zones:
        z0 = active_zones[0]
        z_mid = float(z0.get("mid", np.nan))
        if pd.notna(z_mid):
            summaries.append(f"Kurs handelt aktuell in einer aktiven Zone um {z_mid:.2f}.")

    if resistances:
        r1 = resistances[0]
        r_mid = float(r1.get("mid", np.nan))
        if pd.notna(r_mid) and r_mid > 0:
            dist_pct = ((r_mid / current_price) - 1.0) * 100.0
            if 0 <= dist_pct <= 1.6:
                result["bias"] -= 1
                result["tradeability_bias"] -= 1
                result["notes_neg"].append("Kurs direkt an Widerstand R1")
                result["summary"].append(f"R1 liegt direkt bei {r_mid:.2f}.")
            elif current_price > r_mid:
                result["bias"] += 2
                result["setup_bias"] += 1
                result["notes_pos"].append("Ausbruch über Widerstand R1")
                result["summary"].append(f"R1 bei {r_mid:.2f} wurde überschritten.")

    if channel:
        try:
            idx_last = len(df) - 1
            slope = float(channel.get("slope", 0.0))
            lower = slope * idx_last + float(channel.get("lower_intercept", 0.0))
            upper = slope * idx_last + float(channel.get("upper_intercept", 0.0))
            if upper > lower:
                pos = (current_price - lower) / (upper - lower)
                label = str(channel.get("label", "Trendkanal")).strip()
                if str(channel.get("type")) == "uptrend":
                    if pos <= 0.30:
                        result["bias"] += 1
                        result["setup_bias"] += 1
                        result["notes_pos"].append("Im unteren Bereich eines Aufwaertskanals")
                    elif pos >= 0.82:
                        result["bias"] -= 1
                        result["tradeability_bias"] -= 1
                        result["notes_neg"].append("Im oberen Bereich eines Aufwaertskanals")
                elif str(channel.get("type")) == "downtrend":
                    result["bias"] -= 2
                    result["tradeability_bias"] -= 1
                    result["notes_neg"].append(label)
                result["summary"].append(f"Chart laeuft in {label.lower()}.")
        except Exception:
            pass

    result["bias"] = int(max(-4, min(4, result["bias"])))
    result["setup_bias"] = int(max(-3, min(3, result["setup_bias"])))
    result["tradeability_bias"] = int(max(-3, min(3, result["tradeability_bias"])))
    return result




def _trade_overlay_num_v193(value, default=None):
    """Robuste Zahlenerkennung fuer Trade-Setup-Overlay."""
    try:
        if value is None:
            return default
        if isinstance(value, (int, float, np.integer, np.floating)):
            if pd.isna(value):
                return default
            return float(value)
        text = str(value).strip()
        if not text or text.lower() in {"nan", "none", "n/a", "na", "-"}:
            return default
        text = text.replace("%", "").replace("EUR", "").replace("USD", "").replace("$", "")
        text = text.replace("–", "-").replace("—", "-").replace(",", ".")
        m = re.search(r"-?\d+(?:\.\d+)?", text)
        return float(m.group(0)) if m else default
    except Exception:
        return default


def _trade_overlay_zone_v193(value):
    """Extrahiert eine Preiszone aus Text wie '254.30 - 259.41 USD'."""
    try:
        text = str(value or "").strip()
        if not text or text.lower() in {"nan", "none", "n/a", "na", "-"}:
            return None, None
        text = text.replace("–", "-").replace("—", "-").replace(",", ".")
        nums = re.findall(r"-?\d+(?:\.\d+)?", text)
        vals = [float(x) for x in nums if x not in {"", "-"}]
        vals = [x for x in vals if x > 0]
        if len(vals) >= 2:
            lo, hi = min(vals[0], vals[1]), max(vals[0], vals[1])
            return lo, hi
        if len(vals) == 1:
            return vals[0], vals[0]
    except Exception:
        pass
    return None, None


def _trade_overlay_wave_level_v193(text):
    """Nimmt aus Wave-Texten den relevantesten Preislevel."""
    try:
        raw = str(text or "").replace(",", ".")
        nums = [float(x) for x in re.findall(r"-?\d+(?:\.\d+)?", raw) if float(x) > 0]
        if not nums:
            return None
        # Bei Texten wie '1.272-1.618 Extension ca. 320.77 - 325.05' sollen
        # die Extension-Verhaeltnisse ignoriert werden. Preislevels sind meist deutlich > 10.
        price_like = [x for x in nums if x > 10]
        return price_like[0] if price_like else nums[-1]
    except Exception:
        return None


def _trade_overlay_wave_zone_v193(text):
    try:
        raw = str(text or "").replace(",", ".")
        nums = [float(x) for x in re.findall(r"-?\d+(?:\.\d+)?", raw) if float(x) > 10]
        if len(nums) >= 2:
            return min(nums[-2], nums[-1]), max(nums[-2], nums[-1])
        if len(nums) == 1:
            return nums[0], nums[0]
    except Exception:
        pass
    return None, None


def build_trade_setup_overlay_v193(result=None, wave_pkg=None, ccy=""):
    """Sammelt Entry, Stop/Invalidierung, Ziele und Wave-Levels fuer das Chart-Overlay.

    Ziel v19.4: Alles, was die Entscheidung beeinflusst, soll im Chart sichtbar sein.
    Die Funktion ist absichtlich defensiv, damit fehlende Felder den Chart nicht brechen.
    """
    r = result or {}
    wave = wave_pkg or r.get("wave_structure_pkg") or {}
    entry_text = r.get("suggested_entry_zone") or r.get("Entry-Zone") or r.get("Entry_Zone") or ""
    entry_low, entry_high = _trade_overlay_zone_v193(entry_text)
    stop = _trade_overlay_num_v193(r.get("stop_used") or r.get("stop") or r.get("Stop"), default=None)
    tp1 = _trade_overlay_num_v193(r.get("tp1") or r.get("TP1"), default=None)
    tp2 = _trade_overlay_num_v193(r.get("tp2") or r.get("TP2"), default=None)
    tp3 = _trade_overlay_num_v193(r.get("tp3") or r.get("TP3"), default=None)

    wave_trigger_text = wave.get("wave_trigger") or wave.get("wave_readable_action") or wave.get("trigger_label") or ""
    wave_invalid_text = wave.get("wave_invalidation") or wave.get("wave_readable_risk") or ""
    wave_target_text = wave.get("wave_target_zone") or wave.get("wave_readable_target") or ""
    wave_trigger = _trade_overlay_wave_level_v193(wave_trigger_text)
    wave_invalid = _trade_overlay_wave_level_v193(wave_invalid_text)
    wave_target_low, wave_target_high = _trade_overlay_wave_zone_v193(wave_target_text)

    price = _trade_overlay_num_v193(r.get("live_price") or r.get("analysis_price") or r.get("price"), default=None)
    crv = None
    try:
        # v21.1: CRV im Chart ebenfalls am Hauptziel orientieren. TP1 ist oft nur 1R.
        rr_target = tp2 if tp2 and price and tp2 > price else tp1
        if price and stop and rr_target and price > stop and rr_target > price:
            crv = (rr_target - price) / (price - stop)
    except Exception:
        crv = None

    return {
        "entry_text": entry_text,
        "entry_low": entry_low,
        "entry_high": entry_high,
        "stop": stop,
        "tp1": tp1,
        "tp2": tp2,
        "tp3": tp3,
        "price": price,
        "crv": None if crv is None else round(float(crv), 2),
        "wave_trigger": wave_trigger,
        "wave_trigger_text": wave_trigger_text,
        "wave_invalid": wave_invalid,
        "wave_invalid_text": wave_invalid_text,
        "wave_target_low": wave_target_low,
        "wave_target_high": wave_target_high,
        "wave_target_text": wave_target_text,
        "ccy": ccy,
        "has_overlay": any(x is not None for x in [entry_low, stop, tp1, tp2, tp3, wave_trigger, wave_invalid, wave_target_low]),
    }


def _trade_overlay_xrange_v193(chart_df):
    """Chart-X-Spanne fuer echte, per Legende ausblendbare Overlay-Traces."""
    try:
        if chart_df is not None and len(chart_df.index) >= 2:
            return chart_df.index[0], chart_df.index[-1]
    except Exception:
        pass
    return 0, 1


def _trade_overlay_add_hline_v193(fig, chart_df, y, name, *, dash="dot", width=1, hover=None):
    """Fuegt horizontale Levels als echte Scatter-Traces hinzu.

    Plotly-Shapes aus add_hline lassen sich ueber die Legende nicht wirklich
    ein-/ausblenden. Darum nutzt v19.4 echte Linien-Traces; Legendenfarbe und
    Linie im Chart sind dadurch identisch und klickbar.
    """
    try:
        if y is None or not pd.notna(float(y)) or float(y) <= 0:
            return
        x0, x1 = _trade_overlay_xrange_v193(chart_df)
        fig.add_trace(
            go.Scatter(
                x=[x0, x1],
                y=[float(y), float(y)],
                mode="lines",
                name=name,
                line=dict(width=width, dash=dash),
                hovertemplate=(hover or name) + ": %{y:.2f}<extra></extra>",
                showlegend=True,
            ),
            row=1,
            col=1,
        )
    except Exception:
        pass


def _trade_overlay_add_zone_v193(fig, chart_df, y0, y1, name, *, opacity=0.12, hover=None):
    """Fuegt Preiszonen als ausblendbare, gefuellte Trace-Flaeche hinzu."""
    try:
        if y0 is None or y1 is None:
            return
        lo, hi = float(min(y0, y1)), float(max(y0, y1))
        if lo <= 0 or hi <= 0:
            return
        x0, x1 = _trade_overlay_xrange_v193(chart_df)
        fig.add_trace(
            go.Scatter(
                x=[x0, x1, x1, x0, x0],
                y=[lo, lo, hi, hi, lo],
                mode="lines",
                fill="toself",
                name=name,
                line=dict(width=1, dash="dot"),
                opacity=opacity,
                hovertemplate=(hover or name) + f": {lo:.2f} - {hi:.2f}<extra></extra>",
                showlegend=True,
            ),
            row=1,
            col=1,
        )
    except Exception:
        pass




def _chart_current_price_v204(chart_df, trade_overlay_pkg=None):
    """Robuster aktueller/letzter Kurs fuer die Chart-Orientierung.

    Prioritaet:
    1) Live-/Analysepreis aus dem Trade-Overlay, falls vorhanden
    2) letzter Close im dargestellten Chart
    """
    try:
        val = (trade_overlay_pkg or {}).get("price") if isinstance(trade_overlay_pkg, dict) else None
        if val is not None and pd.notna(float(val)) and float(val) > 0:
            return float(val), "Aktuell"
    except Exception:
        pass
    try:
        if chart_df is not None and not chart_df.empty and "Close" in chart_df.columns:
            close = pd.to_numeric(chart_df["Close"], errors="coerce").dropna()
            if not close.empty and float(close.iloc[-1]) > 0:
                return float(close.iloc[-1]), "Letzter Schluss"
    except Exception:
        pass
    return None, "Aktuell"


def add_current_price_marker_to_plotly_v204(fig, chart_df, current_price=None, ccy="", label="Aktuell"):
    """Hebt den aktuellen Kurs im Chart immer sichtbar hervor.

    Der Kurs wird als echte Plotly-Spur gezeichnet, damit er in der Legende
    ein-/ausblendbar bleibt. Zusaetzlich markiert ein Punkt die letzte Kerze
    und eine rechte Annotation zeigt den genauen Betrag.
    """
    try:
        if current_price is None or not pd.notna(float(current_price)) or float(current_price) <= 0:
            return
        price = float(current_price)
        x0, x1 = _trade_overlay_xrange_v193(chart_df)
        suffix = f" {ccy}" if str(ccy or "").strip() else ""
        name = f"{label}: {price:.2f}{suffix}"
        fig.add_trace(
            go.Scatter(
                x=[x0, x1],
                y=[price, price],
                mode="lines",
                name=name,
                line=dict(width=2.5, dash="solid", color="rgba(2,132,199,0.95)"),
                hovertemplate=f"{label}: %{{y:.2f}}{suffix}<extra></extra>",
                showlegend=True,
            ),
            row=1,
            col=1,
        )
        try:
            last_x = chart_df.index[-1]
            fig.add_trace(
                go.Scatter(
                    x=[last_x],
                    y=[price],
                    mode="markers",
                    name="Kursmarker",
                    marker=dict(size=9, color="rgba(2,132,199,1)", symbol="circle"),
                    hovertemplate=f"{label}: %{{y:.2f}}{suffix}<extra></extra>",
                    showlegend=False,
                ),
                row=1,
                col=1,
            )
            fig.add_annotation(
                x=last_x,
                y=price,
                text=f"{label} {price:.2f}{suffix}",
                showarrow=True,
                arrowhead=2,
                ax=58,
                ay=-10,
                bgcolor="rgba(2,132,199,0.94)",
                bordercolor="rgba(226,232,240,0.90)",
                borderwidth=1,
                borderpad=5 if bool(globals().get("_CHART_LARGE_LABELS_V207", False)) else 4,
                font=dict(size=13 if bool(globals().get("_CHART_LARGE_LABELS_V207", False)) else 11, color="white"),
                row=1,
                col=1,
            )
            _chart_add_hover_point_v207(fig, x=last_x, y=price, text=f"{label} {price:.2f}{suffix}", kind="price", row=1, col=1)
        except Exception:
            pass
    except Exception:
        pass

def add_trade_setup_overlay_to_plotly_v193(fig, chart_df, overlay):
    """Zeichnet Entry-Zone, Stop/Invalidierung, Ziele und Wave-Level in den Kurschart."""
    try:
        if not overlay or not overlay.get("has_overlay"):
            return
        entry_low = overlay.get("entry_low")
        entry_high = overlay.get("entry_high")
        stop = overlay.get("stop")
        tp1 = overlay.get("tp1")
        tp2 = overlay.get("tp2")
        tp3 = overlay.get("tp3")
        wave_trigger = overlay.get("wave_trigger")
        wave_invalid = overlay.get("wave_invalid")
        wt_low = overlay.get("wave_target_low")
        wt_high = overlay.get("wave_target_high")
        ccy = str(overlay.get("ccy") or "").strip()

        if entry_low and entry_high:
            _trade_overlay_add_zone_v193(fig, chart_df, entry_low, entry_high, "Entry-Zone", opacity=0.16)
        if wt_low and wt_high:
            _trade_overlay_add_zone_v193(fig, chart_df, wt_low, wt_high, "Ziel bei Bestätigung", opacity=0.12)

        _trade_overlay_add_hline_v193(fig, chart_df, stop, "Stop / Invalidierung", dash="dash", width=2)
        _trade_overlay_add_hline_v193(fig, chart_df, tp1, "TP1", dash="dot", width=1)
        _trade_overlay_add_hline_v193(fig, chart_df, tp2, "TP2", dash="dot", width=1)
        _trade_overlay_add_hline_v193(fig, chart_df, tp3, "TP3", dash="dot", width=1)
        _trade_overlay_add_hline_v193(fig, chart_df, wave_trigger, "Wann aktiv?", dash="dashdot", width=2, hover="Wellenanalyse - wann aktiv")
        # Wellen-Invalidierung nur separat zeichnen, wenn sie nicht praktisch identisch mit Stop ist.
        try:
            if wave_invalid and (not stop or abs(float(wave_invalid) - float(stop)) / max(float(stop), 1.0) > 0.002):
                _trade_overlay_add_hline_v193(fig, chart_df, wave_invalid, "Wann hinfällig?", dash="dash", width=1, hover="Wellenanalyse - wann hinfällig")
        except Exception:
            _trade_overlay_add_hline_v193(fig, chart_df, wave_invalid, "Wann hinfällig?", dash="dash", width=1, hover="Wellenanalyse - wann hinfällig")

        # v21.1: CRV bleibt in der kompakten Zusammenfassung unter dem Chart.
        # Im Kursbereich selbst war die CRV-Box ein zusätzlicher rechter Label-Konflikt.
    except Exception:
        pass

def build_candlestick_chart(chart_df, ticker, ccy, show_sr=False, show_channel=False, structures=None, show_fib=False, fib_pkg=None, show_trade_overlay=False, trade_overlay_pkg=None, chart_view="Setup", large_labels=False):
    global _CHART_LARGE_LABELS_V207
    _CHART_LARGE_LABELS_V207 = bool(large_labels)
    fig = make_subplots(
        rows=2,
        cols=1,
        shared_xaxes=True,
        vertical_spacing=0.03,
        row_heights=[0.75, 0.25]
    )

    fig.add_trace(
        go.Candlestick(
            x=chart_df.index,
            open=chart_df["Open"],
            high=chart_df["High"],
            low=chart_df["Low"],
            close=chart_df["Close"],
            name=ticker
        ),
        row=1,
        col=1
    )

    _chart_view = str(chart_view or "Setup")
    _show_ma10 = _chart_view in {"Setup", "Vollanalyse"}
    _show_ma20 = True
    _show_ma50 = True
    _show_ma200 = _chart_view == "Vollanalyse"

    if _show_ma10 and "MA10" in chart_df.columns:
        fig.add_trace(
            go.Scatter(x=chart_df.index, y=chart_df["MA10"], mode="lines", name="MA10"),
            row=1,
            col=1
        )
    if _show_ma20 and "MA20" in chart_df.columns:
        fig.add_trace(
            go.Scatter(x=chart_df.index, y=chart_df["MA20"], mode="lines", name="MA20"),
            row=1,
            col=1
        )
    if _show_ma50 and "MA50" in chart_df.columns:
        fig.add_trace(
            go.Scatter(x=chart_df.index, y=chart_df["MA50"], mode="lines", name="MA50"),
            row=1,
            col=1
        )
    if _show_ma200 and "MA200" in chart_df.columns:
        fig.add_trace(
            go.Scatter(x=chart_df.index, y=chart_df["MA200"], mode="lines", name="MA200"),
            row=1,
            col=1
        )

    fig.add_trace(
        go.Bar(
            x=chart_df.index,
            y=chart_df["Volume"],
            name="Volumen"
        ),
        row=2,
        col=1
    )

    if show_sr or show_channel:
        try:
            structures = structures or build_chart_structures(chart_df)
            if show_sr:
                add_sr_zones_to_plotly(fig, chart_df, structures.get("supports", []), structures.get("resistances", []), structures.get("active_zones", []), show_labels=(_chart_view == "Vollanalyse"))
            if show_channel:
                add_trend_channel_to_plotly(fig, chart_df, structures.get("channel"))
        except Exception:
            pass

    if show_fib:
        try:
            add_fibonacci_levels_to_plotly_v1533(fig, chart_df, fib_pkg, show_labels=(_chart_view == "Vollanalyse"))
        except Exception:
            pass

    if show_trade_overlay:
        try:
            add_trade_setup_overlay_to_plotly_v193(fig, chart_df, trade_overlay_pkg)
        except Exception:
            pass

    # v21.1: Aktueller Kurs bleibt immer sichtbar, unabhaengig von Chart-Ansicht und Overlay-Schaltern.
    try:
        _current_price, _current_label = _chart_current_price_v204(chart_df, trade_overlay_pkg)
        add_current_price_marker_to_plotly_v204(fig, chart_df, _current_price, ccy, _current_label)
    except Exception:
        pass

    fig.update_layout(
        title="",
        xaxis_rangeslider_visible=False,
        height=620,
        template="plotly_dark",
        margin=dict(l=20, r=20, t=20, b=20),
        legend=dict(
            orientation="h",
            yanchor="bottom",
            y=1.02,
            xanchor="left",
            x=0,
            bgcolor="rgba(0,0,0,0)",
            font=dict(size=9),
            itemwidth=30,
        )
    )
    fig.update_yaxes(title_text=f"Kurs ({ccy})", row=1, col=1)
    fig.update_yaxes(title_text="Volumen", row=2, col=1)
    return fig


# ---------- Data Enrichment ----------
def extract_analyst_data(ticker_obj, info):
    info = dict(info or {})

    try:
        recs = getattr(ticker_obj, "recommendations", None)
    except Exception:
        recs = None

    if recs is not None and not getattr(recs, "empty", True):
        cols = {str(c).lower(): c for c in recs.columns}
        strong_buy_col = cols.get("strongbuy") or cols.get("strong_buy")
        buy_col = cols.get("buy")
        hold_col = cols.get("hold")
        sell_col = cols.get("sell")
        strong_sell_col = cols.get("strongsell") or cols.get("strong_sell")

        if all(c is not None for c in [strong_buy_col, buy_col, hold_col, sell_col, strong_sell_col]):
            row = recs.iloc[-1]
            sb = pd.to_numeric(row.get(strong_buy_col), errors="coerce")
            b = pd.to_numeric(row.get(buy_col), errors="coerce")
            h = pd.to_numeric(row.get(hold_col), errors="coerce")
            s = pd.to_numeric(row.get(sell_col), errors="coerce")
            ss = pd.to_numeric(row.get(strong_sell_col), errors="coerce")
            vals = [sb, b, h, s, ss]
            if sum(pd.notna(v) for v in vals) >= 3:
                sb = 0 if pd.isna(sb) else float(sb)
                b = 0 if pd.isna(b) else float(b)
                h = 0 if pd.isna(h) else float(h)
                s = 0 if pd.isna(s) else float(s)
                ss = 0 if pd.isna(ss) else float(ss)
                total = sb + b + h + s + ss
                if total > 0:
                    mean = (1 * sb + 2 * b + 3 * h + 4 * s + 5 * ss) / total
                    if pd.isna(info.get("recommendationMean")):
                        info["recommendationMean"] = mean
                    if pd.isna(info.get("numberOfAnalystOpinions")):
                        info["numberOfAnalystOpinions"] = int(total)
                    if pd.isna(info.get("recommendationKey")) or str(info.get("recommendationKey", "")).lower() in {"", "none", "nan"}:
                        if mean <= 1.5:
                            info["recommendationKey"] = "strong_buy"
                        elif mean <= 2.5:
                            info["recommendationKey"] = "buy"
                        elif mean <= 3.5:
                            info["recommendationKey"] = "hold"
                        elif mean <= 4.5:
                            info["recommendationKey"] = "sell"
                        else:
                            info["recommendationKey"] = "strong_sell"

    if pd.isna(info.get("targetMeanPrice")):
        try:
            tinfo = ticker_obj.get_info() or {}
            v = normalize_missing(tinfo.get("targetMeanPrice"))
            if not pd.isna(v):
                info["targetMeanPrice"] = v
        except Exception:
            pass

    return info


def extract_earnings_data(ticker_obj, info):
    info = dict(info or {})

    ts = normalize_missing(info.get("earningsTimestamp"))
    if not pd.isna(ts):
        return info

    try:
        cal = ticker_obj.calendar
        if isinstance(cal, dict) and "Earnings Date" in cal:
            dates = cal["Earnings Date"]
            if isinstance(dates, list) and len(dates) > 0:
                dt = pd.to_datetime(dates[0], errors="coerce", utc=True)
                if pd.notna(dt):
                    info["earningsTimestamp"] = int(dt.timestamp())
                    return info
    except Exception:
        pass

    try:
        ed = ticker_obj.get_earnings_dates(limit=8)
        if ed is not None and not getattr(ed, "empty", True):
            idx = ed.index
            idx = pd.to_datetime(pd.Series(idx), errors="coerce", utc=True)
            now_utc = pd.Timestamp.now(tz="UTC")
            future_idx = [x for x in idx if pd.notna(x) and x >= now_utc]
            chosen = min(future_idx) if future_idx else None
            if chosen is None:
                past_idx = [x for x in idx if pd.notna(x)]
                chosen = max(past_idx) if past_idx else None
            if chosen is not None and pd.notna(chosen):
                info["earningsTimestamp"] = int(chosen.timestamp())
    except Exception:
        pass

    return info


def derive_fundamentals_from_statements(ticker_obj, info):
    info = dict(info or {})

    try:
        income = getattr(ticker_obj, "income_stmt", None)
    except Exception:
        income = None
    try:
        q_income = getattr(ticker_obj, "quarterly_income_stmt", None)
    except Exception:
        q_income = None
    try:
        balance = getattr(ticker_obj, "balance_sheet", None)
    except Exception:
        balance = None
    try:
        q_balance = getattr(ticker_obj, "quarterly_balance_sheet", None)
    except Exception:
        q_balance = None
    try:
        cashflow = getattr(ticker_obj, "cashflow", None)
    except Exception:
        cashflow = None
    try:
        q_cashflow = getattr(ticker_obj, "quarterly_cashflow", None)
    except Exception:
        q_cashflow = None

    revenue_row = first_existing_row(income, ["Total Revenue", "Operating Revenue", "Revenue"])
    op_income_row = first_existing_row(income, ["Operating Income", "EBIT", "OperatingIncome"])
    net_income_row = first_existing_row(income, ["Net Income", "NetIncome", "Net Income Common Stockholders"])
    gross_profit_row = first_existing_row(income, ["Gross Profit", "GrossProfit"])
    diluted_eps_row = first_existing_row(income, ["Diluted EPS", "Basic EPS", "DilutedEPS", "BasicEPS"])

    q_revenue_row = first_existing_row(q_income, ["Total Revenue", "Operating Revenue", "Revenue"])
    q_net_income_row = first_existing_row(q_income, ["Net Income", "NetIncome", "Net Income Common Stockholders"])
    q_diluted_eps_row = first_existing_row(q_income, ["Diluted EPS", "Basic EPS", "DilutedEPS", "BasicEPS"])

    total_assets_row = first_existing_row(balance, ["Total Assets", "TotalAssets"])
    total_equity_row = first_existing_row(balance, ["Stockholders Equity", "Total Stockholder Equity", "Common Stock Equity", "Total Equity Gross Minority Interest"])
    current_assets_row = first_existing_row(balance, ["Current Assets", "Total Current Assets", "CurrentAssets"])
    current_liab_row = first_existing_row(balance, ["Current Liabilities", "Total Current Liabilities", "CurrentLiabilities"])
    inventory_row = first_existing_row(balance, ["Inventory", "Inventories"])
    debt_row = first_existing_row(balance, ["Total Debt", "TotalDebt", "Long Term Debt And Capital Lease Obligation", "Long Term Debt"])

    q_current_assets_row = first_existing_row(q_balance, ["Current Assets", "Total Current Assets", "CurrentAssets"])
    q_current_liab_row = first_existing_row(q_balance, ["Current Liabilities", "Total Current Liabilities", "CurrentLiabilities"])
    q_inventory_row = first_existing_row(q_balance, ["Inventory", "Inventories"])
    q_total_equity_row = first_existing_row(q_balance, ["Stockholders Equity", "Total Stockholder Equity", "Common Stock Equity", "Total Equity Gross Minority Interest"])
    q_total_assets_row = first_existing_row(q_balance, ["Total Assets", "TotalAssets"])
    q_debt_row = first_existing_row(q_balance, ["Total Debt", "TotalDebt", "Long Term Debt And Capital Lease Obligation", "Long Term Debt"])

    op_cf_row = first_existing_row(cashflow, ["Operating Cash Flow", "OperatingCashFlow", "Cash Flow From Continuing Operating Activities"])
    fcf_row = first_existing_row(cashflow, ["Free Cash Flow", "FreeCashFlow"])

    revenue = latest_valid(revenue_row)
    op_income = latest_valid(op_income_row)
    net_income = latest_valid(net_income_row)
    gross_profit = latest_valid(gross_profit_row)
    diluted_eps = latest_valid(diluted_eps_row)

    prev_revenue = previous_valid(revenue_row)
    prev_net_income = previous_valid(net_income_row)
    prev_eps = previous_valid(diluted_eps_row)

    q_revenue = latest_valid(q_revenue_row)
    q_prev_revenue = previous_valid(q_revenue_row)
    q_net_income = latest_valid(q_net_income_row)
    q_prev_net_income = previous_valid(q_net_income_row)
    q_eps = latest_valid(q_diluted_eps_row)
    q_prev_eps = previous_valid(q_diluted_eps_row)

    total_assets = latest_valid(total_assets_row)
    total_equity = latest_valid(total_equity_row)
    current_assets = latest_valid(q_current_assets_row if q_current_assets_row is not None else current_assets_row)
    current_liab = latest_valid(q_current_liab_row if q_current_liab_row is not None else current_liab_row)
    inventory = latest_valid(q_inventory_row if q_inventory_row is not None else inventory_row)
    debt = latest_valid(q_debt_row if q_debt_row is not None else debt_row)
    q_total_assets = latest_valid(q_total_assets_row)
    q_total_equity = latest_valid(q_total_equity_row)

    operating_cf = latest_valid(op_cf_row)
    free_cf = latest_valid(fcf_row)

    if pd.isna(info.get("profitMargins")) and pd.notna(net_income) and pd.notna(revenue) and revenue != 0:
        info["profitMargins"] = net_income / revenue
    if pd.isna(info.get("operatingMargins")) and pd.notna(op_income) and pd.notna(revenue) and revenue != 0:
        info["operatingMargins"] = op_income / revenue
    if pd.isna(info.get("grossMargins")) and pd.notna(gross_profit) and pd.notna(revenue) and revenue != 0:
        info["grossMargins"] = gross_profit / revenue

    eq_for_roe = q_total_equity if pd.notna(q_total_equity) else total_equity
    assets_for_roa = q_total_assets if pd.notna(q_total_assets) else total_assets
    if pd.isna(info.get("returnOnEquity")) and pd.notna(net_income) and pd.notna(eq_for_roe) and eq_for_roe != 0:
        info["returnOnEquity"] = net_income / eq_for_roe
    if pd.isna(info.get("returnOnAssets")) and pd.notna(net_income) and pd.notna(assets_for_roa) and assets_for_roa != 0:
        info["returnOnAssets"] = net_income / assets_for_roa

    rev_growth = np.nan
    if pd.notna(q_revenue) and pd.notna(q_prev_revenue) and q_prev_revenue != 0:
        rev_growth = q_revenue / q_prev_revenue - 1
    elif pd.notna(revenue) and pd.notna(prev_revenue) and prev_revenue != 0:
        rev_growth = revenue / prev_revenue - 1
    if pd.isna(info.get("revenueGrowth")) and pd.notna(rev_growth):
        info["revenueGrowth"] = rev_growth

    earn_growth = np.nan
    if pd.notna(q_eps) and pd.notna(q_prev_eps) and q_prev_eps != 0:
        earn_growth = q_eps / q_prev_eps - 1
    elif pd.notna(q_net_income) and pd.notna(q_prev_net_income) and q_prev_net_income != 0:
        earn_growth = q_net_income / q_prev_net_income - 1
    elif pd.notna(diluted_eps) and pd.notna(prev_eps) and prev_eps != 0:
        earn_growth = diluted_eps / prev_eps - 1
    elif pd.notna(net_income) and pd.notna(prev_net_income) and prev_net_income != 0:
        earn_growth = net_income / prev_net_income - 1
    if pd.isna(info.get("earningsGrowth")) and pd.notna(earn_growth):
        info["earningsGrowth"] = earn_growth

    if pd.isna(info.get("currentRatio")) and pd.notna(current_assets) and pd.notna(current_liab) and current_liab != 0:
        info["currentRatio"] = current_assets / current_liab
    if pd.isna(info.get("quickRatio")) and pd.notna(current_assets) and pd.notna(current_liab) and current_liab != 0:
        inv = inventory if pd.notna(inventory) else 0
        info["quickRatio"] = (current_assets - inv) / current_liab
    if pd.isna(info.get("debtToEquity")) and pd.notna(debt) and pd.notna(eq_for_roe) and eq_for_roe != 0:
        info["debtToEquity"] = debt / eq_for_roe * 100

    if pd.isna(info.get("operatingCashflow")) and pd.notna(operating_cf):
        info["operatingCashflow"] = operating_cf
    if pd.isna(info.get("freeCashflow")) and pd.notna(free_cf):
        info["freeCashflow"] = free_cf

    return info




def build_company_summary(info, ticker):
    candidates = [
        info.get("longBusinessSummary"),
        info.get("businessSummary"),
        info.get("description"),
        info.get("longDescription"),
    ]

    for candidate in candidates:
        if isinstance(candidate, str):
            cleaned = " ".join(candidate.strip().split())
            if cleaned:
                return cleaned

    company_name = info.get("longName") or info.get("shortName") or ticker
    sector = info.get("sector")
    industry = info.get("industry")
    exchange = info.get("exchange")
    country = info.get("country")

    parts = []
    if sector and sector != "-":
        parts.append(f"Sektor: {sector}")
    if industry and industry != "-":
        parts.append(f"Branche: {industry}")
    if country and country != "-":
        parts.append(f"Land: {country}")
    if exchange and exchange != "-":
        parts.append(f"Börse: {exchange}")

    if parts:
        return f"{company_name} - " + " - ".join(parts)

    return "Keine Unternehmensbeschreibung verfügbar."


