    vol_ma20 = safe_last(vol.rolling(20).mean(), np.nan)
    prev_close = safe_last(close.shift(1), np.nan)
    ret1 = safe_last(close.pct_change(1) * 100, np.nan)
    ret2 = safe_last(close.shift(1).pct_change(1) * 100, np.nan)
