    def _v17_clean_operational_trigger_text(txt, entry_zone_text="", current_px=None, structures=None, ccy=""):
        raw = str(txt or "").strip()
        ez = str(entry_zone_text or "").strip()
        if not raw or raw in {"-", "None", "nan"}:
            return raw
        # Remove repeated technical prefixes.
        raw = re.sub(r"^Nächster Trigger:\s*", "", raw, flags=re.I)
        raw = re.sub(r"^Noch kein bullisher Trigger:\s*", "", raw, flags=re.I)
        low = raw.lower()
        if ez and ez not in {"-", "None", "nan"}:
            pos_txt, in_zone, below_zone, above_zone = _entry_zone_position_text_v1524_12(ez, current_px)
            if in_zone or "entry-zone" in low:
                return f"Stabilisierung oder bullische Reaktion in der Entry-Zone {ez}. Alternativ Bruch über ein kurzfristiges Hoch."
            if below_zone:
                return f"Reclaim/Stabilisierung der Entry-Zone {ez}. Alternativ Bruch über ein kurzfristiges Hoch."
            if above_zone:
                return f"Nicht hinterherlaufen; Rücksetzer in Richtung Entry-Zone {ez} oder neue Base abwarten."
        # Support/trigger-zone text: keep concrete zone but shorten.
        m = re.search(r"(\d+(?:[\.,]\d+)?)\s*-\s*(\d+(?:[\.,]\d+)?)\s*([A-Z]{3})?", raw)
        if m and ("support" in low or "trigger" in low or "zone" in low):
            cc = m.group(3) or ccy or ""
            return f"Stabilisierung oder bullische Reaktion an der Support-/Triggerzone {m.group(1)} - {m.group(2)} {cc}. Alternativ Bruch über ein kurzfristiges Hoch.".strip()
        return raw

    def _v17_clean_invalid_text(txt, structures=None, current_px=None, ccy=""):
        raw = str(txt or "").strip()
        if not raw or raw in {"-", "None", "nan"}:
            raw = "Bruch der relevanten Support-/Trigger-Zone."
        low = raw.lower()
        if "relevanten support-/trigger-zone" in low or raw == "Bruch der relevanten Support-/Trigger-Zone.":
            concrete = support_zone_text_v1525_9(structures, current_px, ccy, fallback="")
            if concrete:
                return concrete
        if not low.startswith("bruch") and "support" in low:
            return "Bruch " + raw
        return raw

    def _v17_13_2_invalid_zone_for_action(entry_zone_text="", current_px=None, structures=None, ccy=""):
        """Return a coherent invalidation level for the action box.

        The old path sometimes used an active S/R zone above the preferred entry zone
        as "defensiver bei", while the buy condition pointed to a much lower entry
        zone. That reads contradictory. For Pre-Entry we first anchor invalidation to
        the same entry/support zone used for the setup. If no entry zone is available,
        use the next downside support only; avoid upside/overhead active zones as an
        invalidation level.
        """
        ez = str(entry_zone_text or "").strip()
        if ez and ez not in {"-", "None", "nan", "n/a"}:
            return f"Bruch unter die Entry-/Support-Zone {ez}"
        try:
            cp = float(current_px) if current_px is not None and not pd.isna(current_px) else np.nan
        except Exception:
            cp = np.nan
        try:
            structures = structures or {}
            candidates = []
            for z in (structures.get("supports", []) or []):
                try:
                    mid = float(z.get("mid", np.nan))
                    low = float(z.get("low", np.nan))
                    high = float(z.get("high", np.nan))
                    if pd.isna(mid) or pd.isna(low) or pd.isna(high):
                        continue
                    # Invalidation should be a downside level; ignore zones clearly above price.
                    if pd.notna(cp) and low > cp * 1.002:
                        continue
                    candidates.append((abs(cp - mid) if pd.notna(cp) else 0, z, "Support S1"))
                except Exception:
                    continue
            if candidates:
                candidates.sort(key=lambda x: x[0])
                _, z, label = candidates[0]
                ztxt = _fmt_zone_range_v1525_9(z, ccy)
                if ztxt:
                    try:
                        mid = float(z.get("mid", np.nan))
                        dist = abs((cp / mid) - 1.0) * 100.0 if pd.notna(cp) and pd.notna(mid) and mid else np.nan
                        dist_txt = f", Abstand {dist:.1f}%" if pd.notna(dist) else ""
                    except Exception:
                        dist_txt = ""
                    return f"Bruch der {label} bei {ztxt}{dist_txt}"
        except Exception:
            pass
        return "Bruch der relevanten Support-/Trigger-Zone."

    def _v1721_buy_execution_text(entry_zone_text="", current_px=None, structures=None, ccy=""):
        ez = str(entry_zone_text or "").strip()
        if ez and ez not in {"-", "None", "nan"}:
            try:
                pos_txt, in_zone, below_zone, above_zone = _entry_zone_position_text_v1524_12(ez, current_px)
            except Exception:
                pos_txt, in_zone, below_zone, above_zone = "", False, False, False
            if in_zone:
                return f"Einstieg ist grundsätzlich freigegeben. Kurs liegt in der Entry-Zone {ez}; Ausführung aktiv prüfen, Stop/Invalidierung beachten."
            if below_zone:
                return f"Einstieg ist grundsätzlich freigegeben, aber Kurs liegt noch knapp unter der Entry-Zone {ez}; Reclaim/Stabilisierung bevorzugen."
            if above_zone:
                return f"Zwei Wege: Sauberer Einstieg erst bei Pullback in/nahe Entry-Zone {ez}. Aggressiv nur kleine/selektive Position jetzt prüfen, wenn Stärke anhält; nicht hinterherlaufen."
            return f"Einstieg ist grundsätzlich freigegeben. Umsetzung in/nahe Entry-Zone {ez} prüfen; Stop/Invalidierung beachten."
        concrete = support_zone_text_v1525_9(structures, current_px, ccy, fallback="")
        if concrete:
            return f"Einstieg ist grundsätzlich freigegeben. Umsetzung aktiv prüfen; defensiver bei {concrete}."
        return "Einstieg ist grundsätzlich freigegeben. Ausführung, Positionsgröße und Stop aktiv prüfen."

